CREATE EXTENSION IF NOT EXISTS unaccent;
CREATE EXTENSION IF NOT EXISTS pg_trgm;

CREATE INDEX IF NOT EXISTS idx_herbs_fr_name_trgm
  ON public.herbs USING gin ((translations->'fr'->>'name') gin_trgm_ops);

-- 1. Disambiguate 3 distinct species sharing an English generic display name
UPDATE public.herbs SET name = 'Roman Chamomile' WHERE slug = 'chamomile-roman' AND name <> 'Roman Chamomile';
UPDATE public.herbs SET name = 'Java Turmeric' WHERE slug = 'java-turmeric' AND name <> 'Java Turmeric';
UPDATE public.herbs SET name = 'Dragon''s Blood (Croton lechleri)' WHERE slug = 'dragons-blood-croton' AND name <> 'Dragon''s Blood (Croton lechleri)';

-- 2. Merge 8 duplicate pairs into canonical slugs
UPDATE public.herbs dst
SET
  evidence_level = CASE WHEN dst.evidence_level = 'trad' AND src.evidence_level IN ('A','B','C') THEN src.evidence_level ELSE dst.evidence_level END,
  view_count = coalesce(dst.view_count, 0) + coalesce(src.view_count, 0)
FROM public.herbs src
WHERE src.slug = $SQLTXT$berberine-metabolic-v2$SQLTXT$ AND dst.slug = $SQLTXT$berberine$SQLTXT$ AND src.is_published = true;
UPDATE public.herbs SET is_published = false WHERE slug = $SQLTXT$berberine-metabolic-v2$SQLTXT$ AND is_published = true;
