UPDATE public.herbs SET contraindications = ARRAY[$SQLTXT$Contra-Indications: Do not use if you are pregnant or breastfeeding.$SQLTXT$, $SQLTXT$Known Adverse Reactions: Limit Caffeine products to avoid nervousness and sleeplessness. You may experience a Niacin Flush (hot feeling, skin redness) that lasts a few minutes. This is caused by Niacin(VitaminB3) increasing blood flow near the skin.$SQLTXT$, $SQLTXT$Cautions and Warnings: Caution: Do not use with alcohol while using this product. Not recommended for children, women who are pregnant or nursing, or persons taking any medications. Please consult with a physician prior to use. Limit Caffeine products to avoid nervousness and sleeplessness.$SQLTXT$]::text[], translations = jsonb_set(coalesce(translations, '{}'::jsonb), '{fr}', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('contraindications', $SQLTXT$["Contre-indications : N'utilisez pas si vous êtes enceinte ou allaitez.", "Réactions indésirables connues : Limitez les produits contenant de la caféine pour éviter la nervosité et l'insomnie. Vous pouvez ressentir un flush à la niacine (sensation de chaleur, rougeur de la peau) qui dure quelques minutes. Ceci est causé par la niacine (vitamine B3) qui augmente la circulation sanguine près de la peau.", "Contre-indications : Pour des résultats maximaux : prenez la bouteille entière en une seule fois. Pour des résultats modérés : prenez la moitié de la bouteille en une seule fois. NE PAS DÉPASSER DEUX (2) BOUTEILLES PAR JOUR, CONSOMMEZ À PLUSIEURS HEURES D'INTERVALLE. Réfrigérer après ouverture. Non gazéifié. Consommer dans les 3 jours suivant l'ouverture.", "Mises en garde et avertissements : Attention : N'utilisez pas d'alcool pendant l'utilisation de ce produit. Non recommandé pour les enfants, les femmes enceintes ou allaitantes, ou les personnes prenant des médicaments. Veuillez consulter un médecin avant utilisation. Limitez les produits contenant de la caféine pour éviter la nervosité et l'insomnie."]$SQLTXT$::jsonb)) WHERE slug = $SQLTXT$lactuca-quercina$SQLTXT$;
UPDATE public.herbs SET contraindications = ARRAY[$SQLTXT$Contra-Indications: Do not use if you are taking health products that affect blood coagulation (e.g. blood thinners, clotting factor replacements, acetysalicylic acid, ibuprofen, fish oils, Vitamin E) as this may increase the risk of spontaneous bleeding.$SQLTXT$, $SQLTXT$Contra-Indications: Do not use if you are allergic to plants of the Asteraceae/Compositae/Daisy family.$SQLTXT$, $SQLTXT$Contra-Indications: Do not use if you are taking health products that affect blood coagulation (e.g. blood thinners, clotting factor replacements, acetylsalicylic acid, ibuprofen, fish oils, vitamin E) as this may increase the risk of spontaneous blooding. If you are pregnant do not use.$SQLTXT$, $SQLTXT$Known Adverse Reactions: If you experience symptoms of hypoglycemia including feelings of anxiety, dizziness, tremor, sweating, nausea or headache, discontinue use.$SQLTXT$, $SQLTXT$Known Adverse Reactions: Rare, unpredictable cases of liver injury associated with green tea extract-containing products have been reported.$SQLTXT$, $SQLTXT$Contra-Indications: Do not use if you are pregnant or breastfeeding; If you have hypokalemia, heart disease, a cardiovascular disorder, high or low blood pressure, kidney or liver disorder, a bile duct obstruction, diabetes, an immune-compromised condition (e.g. AIDS, lymphoma.$SQLTXT$]::text[], translations = jsonb_set(coalesce(translations, '{}'::jsonb), '{fr}', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('contraindications', $SQLTXT$["Contre-indications : Ne pas utiliser si vous prenez des produits de santé qui influent sur la coagulation sanguine (p. ex. anticoagulants, suppléments de facteurs de coagulation, acide acétylsalicylique, ibuprofène, huiles de poisson, vitamine E), car cela pourrait augmenter le risque de saignement spontané.", "Contre-indications : Ne pas utiliser si vous êtes allergique aux plantes de la famille des Asteraceae/Compositae/Daisy.", "Contre-indications : Ne pas utiliser si vous prenez des produits de santé qui influent sur la coagulation sanguine (p. ex. anticoagulants, suppléments de facteurs de coagulation, acide acétylsalicylique, ibuprofène, huiles de poisson, vitamine E), car cela pourrait augmenter le risque de saignement spontané. Si vous êtes enceinte, ne pas utiliser.", "Réactions indésirables connues : Si vous éprouvez des symptômes d'hypoglycémie, notamment des sensations d'anxiété, des étourdissements, des tremblements, de la transpiration, des nausées ou des maux de tête, cessez l'utilisation.", "Réactions indésirables connues : Des cas rares et imprévisibles de lésions hépatiques associées à des produits contenant de l'extrait de thé vert ont été signalés.", "Contre-indications : Ne pas utiliser si vous êtes enceinte ou si vous allaitez; si vous avez une hypokaliémie, une maladie cardiaque, un trouble cardiovasculaire, une pression artérielle élevée ou basse, un trouble rénal ou hépatique, une obstruction des voies biliaires, un diabète, un état d'immunodépression (p. ex. SIDA, lymphome."]$SQLTXT$::jsonb)) WHERE slug = $SQLTXT$vitis-vinifera$SQLTXT$;
UPDATE public.herbs SET contraindications = ARRAY[$SQLTXT$Known Adverse Reactions: Stop use if hypersensitivity/allergy occurs. May cause mild gastro-intestinal discomfort (such as gas, bloating, cramps). Rare, unpredictable cases of liver injury associated with green tea extract-containing products have been reported (in Canada and internationally).$SQLTXT$, $SQLTXT$Contra-Indications: Do not use this product if you are taking health products that affect blood coagulation as this may increase the risk of spontaneous bleeding. Do not use this product if you are pregnant, breastfeeding or have a history of systemic lupus erythematosus.$SQLTXT$, $SQLTXT$Known Adverse Reactions: Stop use if you experience insomnia, anxiety or headaches. Stop use if hypersensitivity/allergy occurs. Diuretic effect may occur.$SQLTXT$, $SQLTXT$Contra-Indications: Do not use this product if you are taking health products that affect blood coagulation as this may increase the risk of spontaneous bleeding. Do not use this product in cases of yin deficiency with heat signs, heat excess, or in the absence of significant qi deficiency.$SQLTXT$, $SQLTXT$Known Adverse Reactions: People sensitive to nicotinic acid may experience flushing of the skin that is generally mild and transient. May cause mild gastro-intestinal discomfort (such as gas, bloating, cramps). Diuretic effect may occur. Stop use if hypersensitivity/allergy occurs.$SQLTXT$, $SQLTXT$Contra-Indications: Do not use this product with other potassium-containing supplements or with potassium-containing salt-substitutes.$SQLTXT$]::text[], translations = jsonb_set(coalesce(translations, '{}'::jsonb), '{fr}', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('contraindications', $SQLTXT$["Effets indésirables connus : Cessez l'utilisation en cas d'hypersensibilité/allergie. Peut causer un léger inconfort gastro-intestinal (comme des gaz, des ballonnements, des crampes). De rares cas imprévisibles de lésions hépatiques associés à des produits contenant de l'extrait de thé vert ont été signalés (au Canada et à l'international).", "Contre-indications : N'utilisez pas ce produit si vous prenez des produits de santé qui influent sur la coagulation sanguine, car cela pourrait augmenter le risque de saignement spontané. N'utilisez pas ce produit si vous êtes enceinte, allaitez ou avez des antécédents de lupus érythémateux disséminé.", "Effets indésirables connus : Cessez l'utilisation si vous éprouvez de l'insomnie, de l'anxiété ou des maux de tête. Cessez l'utilisation en cas d'hypersensibilité/allergie. Un effet diurétique peut survenir.", "Contre-indications : N'utilisez pas ce produit si vous prenez des produits de santé qui influent sur la coagulation sanguine, car cela pourrait augmenter le risque de saignement spontané. N'utilisez pas ce produit en cas de vide de yin avec signes de chaleur, d'excès de chaleur ou en l'absence de vide de qi significatif.", "Effets indésirables connus : Les personnes sensibles à l'acide nicotinique peuvent éprouver des bouffées de chaleur cutanées généralement légères et transitoires. Peut causer un léger inconfort gastro-intestinal (comme des gaz, des ballonnements, des crampes). Un effet diurétique peut survenir. Cessez l'utilisation en cas d'hypersensibilité/allergie.", "Contre-indications : N'utilisez pas ce produit avec d'autres suppléments contenant du potassium ni avec des substituts de sel contenant du potassium."]$SQLTXT$::jsonb)) WHERE slug = $SQLTXT$crataegus-laevigata-poir-dc$SQLTXT$;
UPDATE public.herbs SET contraindications = ARRAY[$SQLTXT$Contra-Indications: Do not use if you are pregnant or breastfeeding. Do not use if you have persistant or acute abdominal discomfort, intestinal obstruction or inflammation. Do not take if you are using cardiac glycosides, thiazide diuretics, corticoadrenal steroids or licorice root.$SQLTXT$, $SQLTXT$Known Adverse Reactions: May discolour urine. May cause abdominal pain and/or spasms and/or diarrhea. Hypersensitivity (i.e., allergy) is known to occur, in which case discontinue use. Some people may experience headaches.$SQLTXT$, $SQLTXT$Contra-Indications: Do not use during pregnancy or breast feeding.$SQLTXT$]::text[], translations = jsonb_set(coalesce(translations, '{}'::jsonb), '{fr}', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('contraindications', $SQLTXT$["Contre-indications : Ne pas utiliser si vous êtes enceinte ou si vous allaitez. Ne pas utiliser si vous avez un inconfort abdominal persistant ou aigu, une occlusion ou une inflammation intestinale. Ne pas prendre si vous utilisez des glycosides cardiotoniques, des diurétiques thiazidiques, des corticostéroïdes surrénaliens ou de la racine de réglisse.", "Effets indésirables connus : Peut colorer l'urine. Peut causer des douleurs abdominales et/ou des spasmes et/ou de la diarrhée. Une hypersensibilité (c.-à-d. une allergie) est connue pour survenir, auquel cas cessez l'utilisation. Certaines personnes peuvent éprouver des maux de tête.", "Contre-indications : Ne pas utiliser pendant la grossesse ou l'allaitement."]$SQLTXT$::jsonb)) WHERE slug = $SQLTXT$pimpinella-saxifraga$SQLTXT$;
UPDATE public.herbs SET contraindications = ARRAY[$SQLTXT$Contra-Indications: Do not use if you are experiencing nausea, fever, vomiting, bloody diarrhoea or severe abdominal pain. Do not use if you have an immune-compromised condition (e.g. AIDS, lymphoma, patients undergoing long-term corticosteroid treatment).$SQLTXT$, $SQLTXT$Known Adverse Reactions: Hypersensitivity/allergy has been known to occur; in which case, discontinue use. May cause mild gastro-intestinal discomfort (such as gas, bloating, cramps).$SQLTXT$, $SQLTXT$Contra-Indications: Do not use if you have high blood pressure.$SQLTXT$, $SQLTXT$Known Adverse Reactions: Hypersensitivity (e.g. allergy) has been known to occur; in which case discontinue use.$SQLTXT$]::text[], translations = jsonb_set(coalesce(translations, '{}'::jsonb), '{fr}', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('contraindications', $SQLTXT$["Mises en garde et avertissements : Si vous êtes enceinte ou allaitez, consulter un praticien de soins de santé avant l'utilisation. Pour la rhinite allergique, si les symptômes persistent ou s'aggravent, consulter un praticien de soins de santé.", "Contre-indications : Ne pas utiliser si vous présentez des nausées, de la fièvre, des vomissements, une diarrhée sanglante ou des douleurs abdominales sévères. Ne pas utiliser si vous avez un état immunodéprimé (p. ex. SIDA, lymphome, patients sous traitement corticostéroïdien à long terme).", "Réactions indésirables connues : Une hypersensibilité ou une allergie a été signalée; dans ce cas, cesser l'utilisation. Peut causer un léger inconfort gastro-intestinal (comme des gaz, des ballonnements, des crampes).", "Contre-indications : Ne pas utiliser si vous avez une pression artérielle élevée.", "Réactions indésirables connues : Une hypersensibilité (p. ex. allergie) a été signalée; dans ce cas, cesser l'utilisation."]$SQLTXT$::jsonb)) WHERE slug = $SQLTXT$arthrospira-platensis-gomont$SQLTXT$;
UPDATE public.herbs SET contraindications = ARRAY[$SQLTXT$Known Adverse Reactions: Diuretic effect may occur.$SQLTXT$, $SQLTXT$Contra-Indications: Do not use this product if you are taking thiazide diuretics, cardiac glycosides, corticosteroids, stimulant laxatives or other medications which may aggravate electrolyte imbalance. Do not use if you are pregnant or breastfeeding, or if you are trying to conceive.$SQLTXT$]::text[], translations = jsonb_set(coalesce(translations, '{}'::jsonb), '{fr}', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('contraindications', $SQLTXT$["Effets indésirables connus : Un effet diurétique peut survenir.", "Contre-indications : Ne pas utiliser ce produit si vous prenez des diurétiques thiazidiques, des glycosides cardiotoniques, des corticostéroïdes, des laxatifs stimulants ou d'autres médicaments susceptibles d'aggraver un déséquilibre électrolytique. Ne pas utiliser si vous êtes enceinte ou si vous allaitez, ou si vous essayez de concevoir."]$SQLTXT$::jsonb)) WHERE slug = $SQLTXT$ficus-racemosa$SQLTXT$;
UPDATE public.herbs SET contraindications = ARRAY[$SQLTXT$Contra-Indications: Do not use if you are pregnant or breastfeeding and/or you have abnormal constrictions of the gastrointestinal tract, potential or existing intestinal blockage, atonic bowel, appendicitis, inflammatory colon disease such as Crohn's disease or ulcerative colitis.$SQLTXT$, $SQLTXT$Known Adverse Reactions: Hypersensitivity is known to occur, in which case, discontinue use.$SQLTXT$, $SQLTXT$Contra-Indications: Do not use if pregnant or breastfeeding.$SQLTXT$, $SQLTXT$Contra-Indications: Prohibit to use if pregnant or breastfeeding.$SQLTXT$, $SQLTXT$Contra-Indications: Do not use if you have intestinal obstructions and/or stenosis, atony, appendicitis, inflammatory colon diseases (e.g. Crohn's disease, ulcerative colitis), abdominal pain of unknown origin, and/or a severe dehydration state with water and electrolyte depletion.$SQLTXT$, $SQLTXT$Known Adverse Reactions: Hypersensitivity (e.g. allergy) has been known to occur; in which case, discontinue use.$SQLTXT$]::text[], translations = jsonb_set(coalesce(translations, '{}'::jsonb), '{fr}', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('contraindications', $SQLTXT$["Contre-indications : Ne pas utiliser si vous êtes enceinte ou si vous allaitez et/ou si vous présentez des constrictions anormales du tractus gastro-intestinal, une occlusion intestinale potentielle ou existante, un intestin atone, une appendicite, une maladie inflammatoire du côlon telle que la maladie de Crohn ou la colite ulcéreuse.", "Réactions indésirables connues : Une hypersensibilité est connue pour survenir, auquel cas il faut cesser l'utilisation.", "Contre-indications : Ne pas utiliser si vous êtes enceinte ou si vous allaitez.", "Contre-indications : Interdit d'utilisation si vous êtes enceinte ou si vous allaitez.", "Contre-indications : Ne pas utiliser si vous présentez des obstructions et/ou une sténose intestinales, une atonie, une appendicite, des maladies inflammatoires du côlon (p. ex. maladie de Crohn, colite ulcéreuse), une douleur abdominale d'origine inconnue et/ou un état de déshydratation sévère avec déplétion hydrique et électrolytique.", "Réactions indésirables connues : Une hypersensibilité (p. ex. allergie) est connue pour survenir ; auquel cas il faut cesser l'utilisation."]$SQLTXT$::jsonb)) WHERE slug = $SQLTXT$cassia-angustifolia$SQLTXT$;
UPDATE public.herbs SET contraindications = ARRAY[$SQLTXT$Known Adverse Reactions: Zinc supplementation can cause a copper.$SQLTXT$, $SQLTXT$Known Adverse Reactions: May cause mild gastro-intestinal discomfort (such as gas, bloating, cramps). Hypersensitivity /allergy can occur, in which case discontinue use and consult your health care practitioner.$SQLTXT$, $SQLTXT$Contra-Indications: Stop use and consult a health care practitiner /health care provider/health care proffesional/doctor/physician if you develop symptoms of liver trouble such as yellowing of the skin /eyes (jaundice), stomach pain, dark urine, sweating, nausea.$SQLTXT$]::text[], translations = jsonb_set(coalesce(translations, '{}'::jsonb), '{fr}', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('contraindications', $SQLTXT$["Réactions indésirables connues : La supplémentation en zinc peut causer une carence en.", "Réactions indésirables connues : Peut causer un léger inconfort gastro-intestinal (comme des gaz, des ballonnements, des crampes). Une hypersensibilité ou une allergie peut survenir ; dans ce cas, cesser l'utilisation et consulter votre praticien de soins de santé.", "Contre-indications : Cesser l'utilisation et consulter un praticien de soins de santé, un fournisseur de soins de santé, un professionnel de la santé ou un médecin si vous développez des symptômes de troubles hépatiques tels qu'un jaunissement de la peau ou des yeux (jaunisse), des douleurs abdominales, une urine foncée, des sueurs, des nausées, une fatigue inhabituelle et/ou une perte."]$SQLTXT$::jsonb)) WHERE slug = $SQLTXT$cucumis-pepo$SQLTXT$;
UPDATE public.herbs SET contraindications = ARRAY[$SQLTXT$Contra-Indications: Do not use if you are pregnant, breastfeeding or attempting to conceive unless you have consulted with a health care practitioner. Do not use if you have alllergies to Asteraceae/Compositae (Daisy family).$SQLTXT$, $SQLTXT$Contra-Indications: Do not use if you are pregnant or breastfeeding. Do not use if you have an allergy to Asteraceae/ Compositae (daisy) family. Do not use if you have a bile duct obstruction.$SQLTXT$, $SQLTXT$Known Adverse Reactions: Some people may experience drowsiness. Exercise caution if operating heavy machinery, driving a motor vehicle or involved in activities requiring mental alertness. Hypersensitivity/allergy is known to occur, in which case, discontinue use.$SQLTXT$]::text[], translations = jsonb_set(coalesce(translations, '{}'::jsonb), '{fr}', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('contraindications', $SQLTXT$["Contre-indications : Ne pas utiliser si vous êtes enceinte, si vous allaitez ou si vous tentez de concevoir, à moins d'avoir consulté un professionnel de la santé. Ne pas utiliser si vous avez des allergies aux Asteraceae/Compositae (famille des marguerites).", "Contre-indications : Ne pas utiliser si vous êtes enceinte ou si vous allaitez. Ne pas utiliser si vous avez une allergie à la famille des Asteraceae/Compositae (marguerites). Ne pas utiliser si vous avez une obstruction des voies biliaires.", "Effets indésirables connus : Certaines personnes peuvent ressentir de la somnolence. Faites preuve de prudence si vous utilisez de la machinerie lourde, si vous conduisez un véhicule automobile ou si vous participez à des activités exigeant de la vigilance mentale. Une hypersensibilité/allergie est connue pour survenir, auquel cas cessez l'utilisation."]$SQLTXT$::jsonb)) WHERE slug = $SQLTXT$eupatorium-purpureum$SQLTXT$;
UPDATE public.herbs SET contraindications = ARRAY[$SQLTXT$Contra-Indications: Do not use if you are pregnant or breastfeeding.$SQLTXT$, $SQLTXT$Known Adverse Reactions: People sensitive to nicotinic acid may experience flushing of the skin that is generally mild and transient. Hypersensitivity (e.g. allergy) has been known to occur; in which case, discontinue use.$SQLTXT$, $SQLTXT$Contra-Indications: Hypersensitivity (e.g. allergy) has been known to occur; in which case, discontinue use.$SQLTXT$, $SQLTXT$Known Adverse Reactions: Some people may experience mild gastrointestinal disturbances. Rare, unpredictable cases of liver injury associated with green tea extract-containing products have been reported (in Canada and internationally).$SQLTXT$, $SQLTXT$Cautions and Warnings: Not to be taken by children, during pregnancy, while breastfeeding, by those on medication, or by those with chronic health problems unless under the recommendation of a health care practitioner. Use with caution if allergic to bee products.$SQLTXT$, $SQLTXT$Contra-Indications: Do not use if you have gastrointestinal blockage.$SQLTXT$]::text[], translations = jsonb_set(coalesce(translations, '{}'::jsonb), '{fr}', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('contraindications', $SQLTXT$["Contre-indications : Ne pas utiliser si vous êtes enceinte ou si vous allaitez.", "Réactions indésirables connues : Les personnes sensibles à l'acide nicotinique peuvent éprouver un flushing cutané généralement léger et transitoire. Une hypersensibilité (p. ex. allergie) a été signalée ; dans ce cas, cessez l'utilisation.", "Contre-indications : Une hypersensibilité (p. ex. allergie) a été signalée ; dans ce cas, cessez l'utilisation.", "Réactions indésirables connues : Certaines personnes peuvent éprouver des troubles gastro-intestinaux légers. De rares cas imprévisibles de lésions hépatiques associés à des produits contenant de l'extrait de thé vert ont été signalés (au Canada et à l'échelle internationale).", "Mises en garde et avertissements : Ne doit pas être pris par les enfants, pendant la grossesse, pendant l'allaitement, par les personnes prenant des médicaments ou par les personnes ayant des problèmes de santé chroniques, sauf sur recommandation d'un professionnel de la santé. Utiliser avec prudence en cas d'allergie aux produits de l'abeille.", "Contre-indications : Ne pas utiliser en cas d'occlusion gastro-intestinale."]$SQLTXT$::jsonb)) WHERE slug = $SQLTXT$chlorella-pyrenoidosa$SQLTXT$;
UPDATE public.herbs SET contraindications = ARRAY[$SQLTXT$Known Adverse Reactions: Hypersensitivity has been known to occur. Rare, unpredictable cases of liver injury associated with green tea extract-containing products have been reported (in Canada and internationally). Stop use if you experience irritability or insomnia.$SQLTXT$, $SQLTXT$Contra-Indications: Do not use this product if you have high blood pressure. Do not use this product if you have bipolar disorder or bipolar spectrum disorder. Do not use this product if you are pregnant or breastfeeding.$SQLTXT$, $SQLTXT$Contra-Indications: Do not use this product if you have an immune-compromised condition (e.g. AIDS, lymphoma, patients undergoing long-term corticosteroid treatment).$SQLTXT$, $SQLTXT$Known Adverse Reactions: Stop use if hypersensitivity/allergy occurs.$SQLTXT$]::text[], translations = jsonb_set(coalesce(translations, '{}'::jsonb), '{fr}', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('contraindications', $SQLTXT$["Effets indésirables connus : Une hypersensibilité a été signalée. Des cas rares et imprévisibles de lésions hépatiques associés à des produits contenant de l'extrait de thé vert ont été rapportés (au Canada et à l'international). Cessez l'utilisation si vous ressentez de l'irritabilité ou de l'insomnie.", "Contre-indications : Ne pas utiliser ce produit si vous avez de l'hypertension artérielle. Ne pas utiliser ce produit si vous avez un trouble bipolaire ou un trouble du spectre bipolaire. Ne pas utiliser ce produit si vous êtes enceinte ou si vous allaitez.", "Contre-indications : Ne pas utiliser ce produit si vous avez une immunodépression (p. ex. SIDA, lymphome, patients sous corticothérapie à long terme).", "Effets indésirables connus : Cessez l'utilisation en cas d'hypersensibilité/allergie."]$SQLTXT$::jsonb)) WHERE slug = $SQLTXT$euterpe-oleracea-mart-arecaceae$SQLTXT$;
UPDATE public.herbs SET contraindications = ARRAY[$SQLTXT$Known Adverse Reactions: Stop use if hypersensitivity/allergy occurs.$SQLTXT$, $SQLTXT$Contra-Indications: Do not use if you have a history of systemic lupus erythematosus. If you are pregnant or breastfeeding, do not use.$SQLTXT$, $SQLTXT$Contra-Indications: Keep out of the reach of children. If overdose or accidental ingestion occurs, call a Poison Control Center immediately. Do not use if you are pregnant or breastfeeding, or if you have known allergy/hypersensitivity to members of the Brassicaceae family.$SQLTXT$]::text[], translations = jsonb_set(coalesce(translations, '{}'::jsonb), '{fr}', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('contraindications', $SQLTXT$["Réactions indésirables connues : Cesser l'utilisation si une hypersensibilité/allergie survient.", "Contre-indications : Ne pas utiliser si vous avez des antécédents de lupus érythémateux disséminé. Si vous êtes enceinte ou si vous allaitez, ne pas utiliser.", "Contre-indications : Tenir hors de portée des enfants. En cas de surdosage ou d'ingestion accidentelle, appeler immédiatement un centre antipoison. Ne pas utiliser si vous êtes enceinte ou si vous allaitez, ou si vous avez une allergie/hypersensibilité connue aux membres de la famille des Brassicaceae.", "Mises en garde et précautions : Si vous êtes enceintes ou si vous allaitez, consulter un praticien de soins de santé avant d'en faire l'usage. Si vous prenez des médicaments d'ordonnance, consulter un praticien de soins de santé avant d'en faire l'usage."]$SQLTXT$::jsonb)) WHERE slug = $SQLTXT$alaria-esculenta$SQLTXT$;
UPDATE public.herbs SET contraindications = ARRAY[$SQLTXT$Contra-Indications: Do not use if you are pregnant or breastfeeding.$SQLTXT$, $SQLTXT$Contra-Indications: Do not use if you are pregnant or breastfeeding. Do not use if you are taking heart medications, corticosteroids, stimulant laxatives, or other health products that may contribute electrolyte imbalance. Do not use if you have diarrhea, hemorrhagic diseases or heavy periods.$SQLTXT$, $SQLTXT$Contra-Indications: If you are pregnant or breastfeeding, do not use this product.$SQLTXT$]::text[], translations = jsonb_set(coalesce(translations, '{}'::jsonb), '{fr}', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('contraindications', $SQLTXT$["Contre-indications : Ne pas utiliser si vous êtes enceinte ou si vous allaitez.", "Contre-indications : Ne pas utiliser si vous êtes enceinte ou si vous allaitez. Ne pas utiliser si vous prenez des médicaments pour le cœur, des corticostéroïdes, des laxatifs stimulants ou d'autres produits de santé susceptibles de contribuer à un déséquilibre électrolytique. Ne pas utiliser en cas de diarrhée, de maladies hémorragiques ou de règles abondantes.", "Contre-indications : Si vous êtes enceinte ou si vous allaitez, ne pas utiliser ce produit."]$SQLTXT$::jsonb)) WHERE slug = $SQLTXT$paeonia-anomala-subsp-veitchii$SQLTXT$;
UPDATE public.herbs SET contraindications = ARRAY[$SQLTXT$Known Adverse Reactions: Hypersensitivity (e.g. allergy) has been known to occur, in which case, discontinue use.$SQLTXT$, $SQLTXT$Contra-Indications: For adult use only.$SQLTXT$, $SQLTXT$Known Adverse Reactions: Some people may experience swelling, burning, gastrointestinal upset (diarrhea, cramps, nausea, vomiting), dizziness, insomnia, anxiety, increased heart rate, arrhythmia, tremors, or headaches, in which case, discontinue use.$SQLTXT$, $SQLTXT$Contra-Indications: For adults use only.$SQLTXT$, $SQLTXT$Contra-Indications: Do not use if you are pregnant or breastfeeding or following vigorous exercise or acute dehydration.$SQLTXT$, $SQLTXT$Known Adverse Reactions: Hypersensitivity (e.g. allergy) has been known to occur; in which case, discontinue use. Some people may experience mild gastrointenstinal disturbances such as diarrhea, abdominal pain, heartburn, nausea and vomiting; in which case discontinue use.$SQLTXT$]::text[], translations = jsonb_set(coalesce(translations, '{}'::jsonb), '{fr}', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('contraindications', $SQLTXT$["Réactions indésirables connues : Une hypersensibilité (p. ex. allergie) a été signalée ; le cas échéant, cesser l'utilisation.", "Contre-indications : Pour usage adulte seulement.", "Réactions indésirables connues : Certaines personnes peuvent ressentir un gonflement, une sensation de brûlure, des troubles gastro-intestinaux (diarrhée, crampes, nausées, vomissements), des étourdissements, de l'insomnie, de l'anxiété, une augmentation du rythme cardiaque, une arythmie, des tremblements ou des maux de tête ; le cas échéant, cesser l'utilisation.", "Contre-indications : Ne pas utiliser si vous êtes enceinte ou si vous allaitez, ou après un exercice vigoureux ou une déshydratation aiguë.", "Réactions indésirables connues : Une hypersensibilité (p. ex. allergie) a été signalée ; le cas échéant, cesser l'utilisation. Certaines personnes peuvent ressentir des troubles gastro-intestinaux légers tels que diarrhée, douleurs abdominales, brûlures d'estomac, nausées et vomissements ; le cas échéant, cesser l'utilisation."]$SQLTXT$::jsonb)) WHERE slug = $SQLTXT$smilax-aristolochiifolia$SQLTXT$;
UPDATE public.herbs SET contraindications = ARRAY[$SQLTXT$Contra-Indications: Do not use if you are pregnant of breastfeeding. Discontinue use if allergy such as itches or rash develops. Do not apply to open wound. Avoid contact with the eyes and mucous membranes. Do not tightly bandage.$SQLTXT$]::text[], translations = jsonb_set(coalesce(translations, '{}'::jsonb), '{fr}', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('contraindications', $SQLTXT$["Contre-indications : Ne pas utiliser si vous êtes enceinte ou si vous allaitez. Cesser l'utilisation en cas d'allergie telle que des démangeaisons ou une éruption cutanée. Ne pas appliquer sur une plaie ouverte. Éviter le contact avec les yeux et les muqueuses. Ne pas bander serré."]$SQLTXT$::jsonb)) WHERE slug = $SQLTXT$inula-cappa$SQLTXT$;
