UPDATE public.herbs SET contraindications = ARRAY[$SQLTXT$Contra-Indications: If you are pregnant or breastfeeding, do not use this product.$SQLTXT$, $SQLTXT$Contra-Indications: Stop use if hypersensitivity/allergy occurs.$SQLTXT$, $SQLTXT$Known Adverse Reactions: Diuretic effect may occur.$SQLTXT$]::text[], translations = jsonb_set(coalesce(translations, '{}'::jsonb), '{fr}', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('contraindications', $SQLTXT$["Contre-indications : Si vous êtes enceinte ou si vous allaitez, n'utilisez pas ce produit.", "Contre-indications : Cessez l'utilisation en cas d'hypersensibilité/allergie.", "Effets indésirables connus : Un effet diurétique peut survenir."]$SQLTXT$::jsonb)) WHERE slug = $SQLTXT$dendrobium-fimbriatum$SQLTXT$;
UPDATE public.herbs SET contraindications = ARRAY[$SQLTXT$Known Adverse Reactions: Some people may experience drowsiness. Exercise caution if operating heavy machinery, driving a motor vehicle or involved in activities requiring mental alertness.$SQLTXT$, $SQLTXT$Contra-Indications: Do not use this product if you are pregnant or breastfeeding.$SQLTXT$, $SQLTXT$Cautions and Warnings: Hypersensitivity, such as an allergy, has been known to occur; in which case, discontinue use.$SQLTXT$, $SQLTXT$Known Adverse Reactions: Diuretic effect may occur.$SQLTXT$, $SQLTXT$Contra-Indications: Do not use this product if you are taking thiazide diuretics, cardiac glycosides, corticosteroids, stimulant laxatives or other medications which may aggravate electrolyte imbalance. Do not use if you are pregnant or breastfeeding, or if you are trying to conceive.$SQLTXT$]::text[], translations = jsonb_set(coalesce(translations, '{}'::jsonb), '{fr}', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('contraindications', $SQLTXT$["Réactions indésirables connues : Certaines personnes peuvent ressentir de la somnolence. Faire preuve de prudence si vous utilisez de la machinerie lourde, conduisez un véhicule automobile ou pratiquez des activités nécessitant de la vigilance mentale. Des inconforts gastro-intestinaux (c.-à-d.", "Contre-indications : Ne pas utiliser ce produit si vous êtes enceinte ou si vous allaitez.", "Mises en garde et avertissements : Une hypersensibilité, telle qu'une allergie, a été signalée ; dans ce cas, cesser l'utilisation.", "Réactions indésirables connues : Un effet diurétique peut survenir.", "Contre-indications : Ne pas utiliser ce produit si vous prenez des diurétiques thiazidiques, des glycosides cardiaques, des corticostéroïdes, des laxatifs stimulants ou d'autres médicaments susceptibles d'aggraver un déséquilibre électrolytique. Ne pas utiliser si vous êtes enceinte ou si vous allaitez, ou si vous essayez de concevoir."]$SQLTXT$::jsonb)) WHERE slug = $SQLTXT$woodfordia-fruticosa$SQLTXT$;
UPDATE public.herbs SET contraindications = ARRAY[$SQLTXT$Contra-Indications: Do not use this product if you are pregnant or breastfeeding.$SQLTXT$, $SQLTXT$Known Adverse Reactions: Stop use if hypersensitivity/allergy occurs.$SQLTXT$, $SQLTXT$Contra-Indications: Do not use this product if you are pregnant or breastfeeding. Do not use this product if you are taking thiazide diuretics, cardiac glycosides, corticosteroids, stimulant laxatives or other medications which may aggravate electrolyte imbalance.$SQLTXT$, $SQLTXT$Contra-Indications: If you are pregnant or breastfeeding, do not use this product.$SQLTXT$]::text[], translations = jsonb_set(coalesce(translations, '{}'::jsonb), '{fr}', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('contraindications', $SQLTXT$["Contre-indications : Ne pas utiliser ce produit si vous êtes enceinte ou si vous allaitez.", "Réactions indésirables connues : Cesser l'utilisation en cas d'hypersensibilité/allergie.", "Contre-indications : Ne pas utiliser ce produit si vous êtes enceinte ou si vous allaitez. Ne pas utiliser ce produit si vous prenez des diurétiques thiazidiques, des glycosides cardiotoniques, des corticostéroïdes, des laxatifs stimulants ou d'autres médicaments susceptibles d'aggraver un déséquilibre électrolytique.", "Contre-indications : Si vous êtes enceinte ou si vous allaitez, ne pas utiliser ce produit."]$SQLTXT$::jsonb)) WHERE slug = $SQLTXT$pleione-bulbocodioides$SQLTXT$;
UPDATE public.herbs SET contraindications = ARRAY[$SQLTXT$Contra-Indications: If you are pregnant or breast-feeding, do not use this product.$SQLTXT$, $SQLTXT$Contra-Indications: If you are pregnant or breastfeeding, do not use this product.$SQLTXT$, $SQLTXT$Contra-Indications: Do not use if you are pregnant or breastfeeding. Do not use if you are taking heart medications, corticosteroids, stimulant laxatives, or other health products that may contribute electrolyte imbalance.$SQLTXT$, $SQLTXT$Contra-Indications: If you are pregnant/breastfeeding, do not use this product.$SQLTXT$, $SQLTXT$Known Adverse Reactions: Diuretic effect may occur. Stop use if hypersensitivity/allergy occurs. Stop use if you experience insomnia, anxiety or headaches.$SQLTXT$, $SQLTXT$Contra-Indications: Do not use this product if you are pregnant or breastfeeding. Do not use this product if you are taking thiazide diuretics, cardiac glycosides, corticosteroids, stimulant laxatives or other medications which may aggravate electrolyte imbalance.$SQLTXT$]::text[], translations = jsonb_set(coalesce(translations, '{}'::jsonb), '{fr}', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('contraindications', $SQLTXT$["Contre-indications : si vous êtes enceinte ou si vous allaitez, n'utilisez pas ce produit.", "Contre-indications : n'utilisez pas si vous êtes enceinte ou si vous allaitez. N'utilisez pas si vous prenez des médicaments cardiaques, des corticostéroïdes, des laxatifs stimulants ou d'autres produits de santé susceptibles de contribuer à un déséquilibre électrolytique.", "Réactions indésirables connues : un effet diurétique peut survenir. Cessez l'utilisation en cas d'hypersensibilité ou d'allergie. Cessez l'utilisation si vous présentez de l'insomnie, de l'anxiété ou des maux de tête.", "Contre-indications : n'utilisez pas ce produit si vous êtes enceinte ou si vous allaitez. N'utilisez pas ce produit si vous prenez des diurétiques thiazidiques, des glycosides cardiotoniques, des corticostéroïdes, des laxatifs stimulants ou d'autres médicaments susceptibles d'aggraver un déséquilibre électrolytique."]$SQLTXT$::jsonb)) WHERE slug = $SQLTXT$amomum-longiligulare$SQLTXT$;
UPDATE public.herbs SET contraindications = ARRAY[$SQLTXT$Contra-Indications: If you are pregnant or breastfeeding, do not use this product.$SQLTXT$, $SQLTXT$Contra-Indications: Do not use this product if you are pregnant or breastfeeding.$SQLTXT$, $SQLTXT$Contra-Indications: Do not use if you are pregnant or breastfeeding or if you have gastric or duodenal ulcer. Do not use if you are taking blood thinners, medications that reduce stomach acid or prevent or lessen seizures.$SQLTXT$, $SQLTXT$Known Adverse Reactions: May cause mild constipation in sensitive individuals. If constipation persists, discontinue use and contact a health care practitioner. May intensify the effects and side effects of alcohol consumption.$SQLTXT$]::text[], translations = jsonb_set(coalesce(translations, '{}'::jsonb), '{fr}', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('contraindications', $SQLTXT$["Contre-indications : Si vous êtes enceinte ou si vous allaitez, ne pas utiliser ce produit.", "Contre-indications : Ne pas utiliser ce produit si vous êtes enceinte ou si vous allaitez.", "Contre-indications : Ne pas utiliser si vous êtes enceinte ou si vous allaitez ou si vous avez un ulcère gastrique ou duodénal. Ne pas utiliser si vous prenez des anticoagulants, des médicaments qui réduisent l'acidité gastrique ou qui préviennent ou atténuent les convulsions.", "Réactions indésirables connues : Peut causer une constipation légère chez les personnes sensibles. Si la constipation persiste, cesser l'utilisation et consulter un professionnel de la santé. Peut intensifier les effets et les effets indésirables de la consommation d'alcool."]$SQLTXT$::jsonb)) WHERE slug = $SQLTXT$anemone-chinensis$SQLTXT$;
UPDATE public.herbs SET contraindications = ARRAY[$SQLTXT$Contra-Indications: If you are pregnant or breastfeeding, do not use.$SQLTXT$, $SQLTXT$Known Adverse Reactions: Diuretic effect may occur. Stop use if hypersensitivity/allergy occurs. When using this product exercise caution if you drive or use machinery as you may experience drowsiness.$SQLTXT$, $SQLTXT$Contra-Indications: Do not use this product if you are pregnant or breastfeeding. Do not use this product if you have excess heat, yin-deficient fire, or bleeding caused by heat in the blood.$SQLTXT$]::text[], translations = jsonb_set(coalesce(translations, '{}'::jsonb), '{fr}', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('contraindications', $SQLTXT$["Contre-indications : Si vous êtes enceinte ou allaitez, ne pas utiliser.", "Réactions indésirables connues : Un effet diurétique peut survenir. Cesser l'utilisation en cas d'hypersensibilité ou d'allergie. Lors de l'utilisation de ce produit, faites preuve de prudence si vous conduisez ou utilisez de la machinerie, car vous pourriez ressentir de la somnolence.", "Contre-indications : Ne pas utiliser ce produit si vous êtes enceinte ou allaitez. Ne pas utiliser ce produit si vous avez une chaleur excessive, un feu par déficience de yin ou des saignements causés par la chaleur dans le sang."]$SQLTXT$::jsonb)) WHERE slug = $SQLTXT$abelmoschus-manihot$SQLTXT$;
UPDATE public.herbs SET contraindications = ARRAY[$SQLTXT$Contra-Indications: Do not use if you are attempting to conceive unless you have consulted with a health care practitioner. Do not use this product if you have an immune-compromised condition (e.g. AIDS, lymphoma, patients undergoing long-term corticosteroid treatment).$SQLTXT$, $SQLTXT$Known Adverse Reactions: Stop use if hypersensitivity/allergy occurs. Stop use if laxative effect occurs.$SQLTXT$, $SQLTXT$Contra-Indications: Do not use if you are allergic to plants of the Asteraceae/Compositae/Daisy family. If you have an immune-compromised condition (e.g. AIDS, lymphoma, patients undergoing long-term corticosteroid treatment), do not use this product.$SQLTXT$, $SQLTXT$Known Adverse Reactions: Hypersensitivity (e.g. allergy) has been known to occur; in which case, discontinue use.$SQLTXT$, $SQLTXT$Contra-Indications: Do not use if you are experiencing nausea, fever, vomiting, bloody diarrhoea or severe abdominal pain. Do not use if you have an immune-compromised condition (eg. AIDS, lymphoma, patients undergoing long-term corticosteroid treatment).$SQLTXT$, $SQLTXT$Contra-Indications: If you are pregnant or breastfeeding, do not use. Do not use this product if you have an immune-compromised condition (e.g. AIDS, lymphoma, patients undergoing long-term corticosteroid treatment).$SQLTXT$]::text[], translations = jsonb_set(coalesce(translations, '{}'::jsonb), '{fr}', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('contraindications', $SQLTXT$["Contre-indications : N'utilisez pas si vous tentez de concevoir à moins d'avoir consulté un professionnel de la santé. N'utilisez pas ce produit si vous avez une condition d'immunodépression (p. ex. SIDA, lymphome, patients sous traitement corticostéroïdien à long terme).", "Effets indésirables connus : Cessez l'utilisation en cas d'hypersensibilité/allergie. Cessez l'utilisation si un effet laxatif survient.", "Contre-indications : N'utilisez pas si vous êtes allergique aux plantes de la famille des Asteraceae/Compositae/Daisy. Si vous avez une condition d'immunodépression (p. ex. SIDA, lymphome, patients sous traitement corticostéroïdien à long terme), n'utilisez pas ce produit.", "Effets indésirables connus : Une hypersensibilité (p. ex. allergie) a été connue pour survenir ; dans ce cas, cessez l'utilisation.", "Contre-indications : N'utilisez pas si vous éprouvez des nausées, de la fièvre, des vomissements, une diarrhée sanglante ou une douleur abdominale sévère. N'utilisez pas si vous avez une condition d'immunodépression (p. ex. SIDA, lymphome, patients sous traitement corticostéroïdien à long terme).", "Contre-indications : Si vous êtes enceinte ou si vous allaitez, n'utilisez pas. N'utilisez pas ce produit si vous avez une condition d'immunodépression (p. ex. SIDA, lymphome, patients sous traitement corticostéroïdien à long terme)."]$SQLTXT$::jsonb)) WHERE slug = $SQLTXT$saccharomyces-boulardii$SQLTXT$;
UPDATE public.herbs SET contraindications = ARRAY[$SQLTXT$Contra-Indications: Do not use if you are pregnant or breastfeeding.$SQLTXT$, $SQLTXT$Known Adverse Reactions: For external use only. May irritate abraded or inflamed skin. Avoid contact with eyes. If irritation or allergic response occurs, discontinue treatment.$SQLTXT$, $SQLTXT$Contra-Indications: Do not use if you are pregnant or breastfeeding. Do not use if you have diarrhea, hemorrhagic diseases or heavy periods.$SQLTXT$, $SQLTXT$Contra-Indications: Do not eat with raw and cold food. Do not use if you are pregnant or breastfeeding.$SQLTXT$, $SQLTXT$Known Adverse Reactions: Stop use if hypersensitivity/allergy occurs.$SQLTXT$, $SQLTXT$Contra-Indications: If you are pregnant or breastfeeding, do not use this product.$SQLTXT$]::text[], translations = jsonb_set(coalesce(translations, '{}'::jsonb), '{fr}', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('contraindications', $SQLTXT$["Contre-indications : Ne pas utiliser si vous êtes enceinte ou si vous allaitez.", "Réactions indésirables connues : Pour usage externe seulement. Peut irriter la peau abrasée ou enflammée. Éviter le contact avec les yeux. En cas d'irritation ou de réaction allergique, cesser le traitement.", "Contre-indications : Ne pas utiliser si vous êtes enceinte ou si vous allaitez. Ne pas utiliser si vous avez de la diarrhée, des maladies hémorragiques ou des règles abondantes.", "Contre-indications : Ne pas consommer avec des aliments crus et froids. Ne pas utiliser si vous êtes enceinte ou si vous allaitez.", "Réactions indésirables connues : Cesser l'utilisation en cas d'hypersensibilité ou d'allergie.", "Contre-indications : Si vous êtes enceinte ou si vous allaitez, ne pas utiliser ce produit."]$SQLTXT$::jsonb)) WHERE slug = $SQLTXT$alisma-plantago-aquatica-subsp-orientale$SQLTXT$;
UPDATE public.herbs SET contraindications = ARRAY[$SQLTXT$Contra-Indications: If you are pregnant or breastfeeding, do not use.$SQLTXT$, $SQLTXT$Known Adverse Reactions: Stop use if hypersensitivity/allergy occurs.$SQLTXT$, $SQLTXT$Contra-Indications: Do not use this product if you are pregnant or breastfeeding. Do not use this product if you have Qi deficiency.$SQLTXT$, $SQLTXT$Known Adverse Reactions: Headache, dizziness, vomiting, severe abdominal pain, diarrhea, blood in the stools, tachycardia, nausea, dyspnea, and in rare cases, fever, cyanosis, anxiety, general weakness, and temporarily elevated levels of liver enzymes such as alanine transaminase known to occur.$SQLTXT$, $SQLTXT$Contra-Indications: Do not take this product if you are pregnant or breastfeeding, or during menstruation, or if you have abnormal constrictions of the gastrointestinal tract, potential or existing intestinal blockage, atonic bowel, appendicitis, inflammatory colon disease such as Crohns disease.$SQLTXT$]::text[], translations = jsonb_set(coalesce(translations, '{}'::jsonb), '{fr}', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('contraindications', $SQLTXT$["Contre-indications : Si vous êtes enceinte ou allaitez, ne pas utiliser.", "Réactions indésirables connues : Cesser l'utilisation en cas d'hypersensibilité/allergie.", "Contre-indications : Ne pas utiliser ce produit si vous êtes enceinte ou allaitez. Ne pas utiliser ce produit si vous avez une déficience du Qi.", "Réactions indésirables connues : Des cas de céphalées, vertiges, vomissements, douleurs abdominales sévères, diarrhée, présence de sang dans les selles, tachycardie, nausées, dyspnée et, dans de rares cas, fièvre, cyanose, anxiété, faiblesse générale et élévation temporaire des taux d'enzymes hépatiques telles que l'alanine transaminase sont connus pour survenir.", "Contre-indications : Ne pas prendre ce produit si vous êtes enceinte ou allaitez, ou pendant les menstruations, ou si vous avez des constrictions anormales du tractus gastro-intestinal, une occlusion intestinale potentielle ou existante, un intestin atone, une appendicite, une maladie inflammatoire du côlon telle que la maladie de Crohn."]$SQLTXT$::jsonb)) WHERE slug = $SQLTXT$ipomoea-purpurea$SQLTXT$;
UPDATE public.herbs SET contraindications = ARRAY[$SQLTXT$Contra-Indications: Do not use if you are pregnant or breastfeeding.$SQLTXT$, $SQLTXT$Contra-Indications: Do not use if pregnant or breastfeeding.$SQLTXT$, $SQLTXT$Contra-Indications: Do not use if you are pregnant, or breastfeeding.$SQLTXT$, $SQLTXT$Contra-Indications: Do not use if you are pregnant of breastfeeding.$SQLTXT$, $SQLTXT$Contra-Indications: Do not use this product if you are pregnant or breastfeeding. Do not use this product if you are taking thiazide diuretics, cardiac glycosides, corticosteroids, stimulant laxatives or other medications which may aggravate electrolyte imbalance.$SQLTXT$, $SQLTXT$Known Adverse Reactions: Diuretic effect may occur.$SQLTXT$]::text[], translations = jsonb_set(coalesce(translations, '{}'::jsonb), '{fr}', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('contraindications', $SQLTXT$["Contre-indications : Ne pas utiliser si vous êtes enceinte ou si vous allaitez.", "Contre-indications : Ne pas utiliser ce produit si vous êtes enceinte ou si vous allaitez. Ne pas utiliser ce produit si vous prenez des diurétiques thiazidiques, des glycosides cardiotoniques, des corticostéroïdes, des laxatifs stimulants ou d'autres médicaments susceptibles d'aggraver un déséquilibre électrolytique.", "Réactions indésirables connues : Un effet diurétique peut survenir."]$SQLTXT$::jsonb)) WHERE slug = $SQLTXT$anemone-altaica$SQLTXT$;
UPDATE public.herbs SET contraindications = ARRAY[$SQLTXT$Known Adverse Reactions: Hypersensitivity is known to occur, in which case, discontinue use. Discontinue use if hypersensitivity occurs such as skin rash or skin irritation.$SQLTXT$, $SQLTXT$Contra-Indications: Do not use if you are allergic to anethole or plants of the Apiaceae/Carrot family. Do not use this product if you are pregnant or breastfeeding.$SQLTXT$, $SQLTXT$Contra-Indications: Do not use if you have difficulty swallowing. Do not use if you have diabetes mellitus in which blood sugar is difficult to regulate.$SQLTXT$, $SQLTXT$Known Adverse Reactions: May cause temporary gas and/or bloating. Hypersensitivity, such as allergy, has been known to occur following inhaled and/or ingested psyllium; in which case, discontinue use.$SQLTXT$, $SQLTXT$Contra-Indications: Do not use this product if you are experiencing a sudden change in bowel habits that has persisted for more than 2 weeks, undiagnosed rectal bleeding, or failure to defaecate following the use of another laxative product.$SQLTXT$, $SQLTXT$Known Adverse Reactions: May cause temporary gas and/or bloating. Stop use if hypersensitivity/allergy occurs.$SQLTXT$]::text[], translations = jsonb_set(coalesce(translations, '{}'::jsonb), '{fr}', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('contraindications', $SQLTXT$["Réactions indésirables connues : Une hypersensibilité est connue pour survenir ; dans ce cas, cesser l'utilisation. Cesser l'utilisation si une hypersensibilité survient, telle qu'une éruption cutanée ou une irritation cutanée.", "Contre-indications : Ne pas utiliser si vous êtes allergique à l'anéthole ou aux plantes de la famille des Apiaceae/Carrot. Ne pas utiliser ce produit si vous êtes enceinte ou si vous allaitez.", "Contre-indications : Ne pas utiliser si vous avez de la difficulté à avaler. Ne pas utiliser si vous avez un diabète sucré dont la glycémie est difficile à réguler.", "Réactions indésirables connues : Peut causer des gaz et/ou des ballonnements temporaires. Une hypersensibilité, telle qu'une allergie, a été signalée après inhalation et/ou ingestion de psyllium ; dans ce cas, cesser l'utilisation.", "Contre-indications : Ne pas utiliser ce produit si vous présentez un changement soudain des habitudes intestinales persistant depuis plus de 2 semaines, un saignement rectal non diagnostiqué ou une incapacité à déféquer après l'utilisation d'un autre produit laxatif.", "Réactions indésirables connues : Peut causer des gaz et/ou des ballonnements temporaires. Cesser l'utilisation si une hypersensibilité/allergie survient."]$SQLTXT$::jsonb)) WHERE slug = $SQLTXT$plantago-afra$SQLTXT$;
UPDATE public.herbs SET contraindications = ARRAY[$SQLTXT$Contra-Indications: Do not use if you are taking health products that affect blood coagulation (e.g. blood thinners, clotting factor replacements, acetylsalicylic acid, ibuprofen, fish oils, vitamin E) as this may increase the risk of spontaneous bleeding.$SQLTXT$, $SQLTXT$Known Adverse Reactions: Some people may experience drowsiness. Exercise caution if operating heavy machinery, driving a motor vehicle or involved in activities requiring mental alertness. Hypersensitivity (e.g. allergy) has been known to occur; in which case, discontinue use.$SQLTXT$, $SQLTXT$Contra-Indications: Do not use if you are allergic to plants of the Asteraceae/Compositae/Daisy Family.$SQLTXT$, $SQLTXT$Known Adverse Reactions: Hypersensitivity/allergy is known to occur, in which case, discontinue use. Some people may experience drowsiness.$SQLTXT$]::text[], translations = jsonb_set(coalesce(translations, '{}'::jsonb), '{fr}', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('contraindications', $SQLTXT$["Contre-indications : N'utilisez pas si vous prenez des produits de santé qui affectent la coagulation sanguine (p. ex. anticoagulants, suppléments de facteurs de coagulation, acide acétylsalicylique, ibuprofène, huiles de poisson, vitamine E), car cela pourrait augmenter le risque de saignement spontané.", "Réactions indésirables connues : Certaines personnes peuvent ressentir de la somnolence. Faites preuve de prudence si vous utilisez de la machinerie lourde, conduisez un véhicule automobile ou participez à des activités exigeant de la vigilance mentale. Des cas d'hypersensibilité (p. ex. allergie) ont été signalés ; le cas échéant, cessez l'utilisation.", "Contre-indications : N'utilisez pas si vous êtes allergique aux plantes de la famille des Asteraceae/Compositae/marguerites.", "Réactions indésirables connues : Des cas d'hypersensibilité ou d'allergie sont connus ; le cas échéant, cessez l'utilisation. Certaines personnes peuvent ressentir de la somnolence."]$SQLTXT$::jsonb)) WHERE slug = $SQLTXT$passiflora-incarnata$SQLTXT$;
UPDATE public.herbs SET contraindications = ARRAY[$SQLTXT$Contra-Indications: Do not use this product if you are taking antibiotics or nitroglycerin. Do not use this product if you have a bile duct obstruction. Do not use this product if you are pregnant or breastfeeding.$SQLTXT$, $SQLTXT$Known Adverse Reactions: Stop use if gastro-intestinal disturbance and/or hypersensitivity/allergy occur.$SQLTXT$, $SQLTXT$Known Adverse Reactions: May cause temporary gas and/or bloating. Stop use if hypersensitivity/allergy occurs. May cause digestive problems. Rare, unpredictable cases of liver injury associated with green tea extract-containing products have been reported (in Canada and internationally).$SQLTXT$, $SQLTXT$Contra-Indications: Do not use if you have difficulty swallowing. Do not use this product if you are experiencing a sudden change in bowel habits that has persisted for more than 2 weeks, undiagnosed rectal bleeding, or failure to defaecate following the use of another laxative product.$SQLTXT$, $SQLTXT$Contra-Indications: Do not use this product if you are pregnant or breastfeeding. Do not use this product if you are taking health products that affect blood coagulation as this may increase the risk of spontaneous bleeding.$SQLTXT$, $SQLTXT$Known Adverse Reactions: Stop use if hypersensitivity/allergy occurs. People sensitive to nicotinic acid may experience flushing of the skin that is generally mild and transient. Some people may experience constipation, diarrhoea and/or vomiting. Do not use this product if you have milk allergy.$SQLTXT$]::text[], translations = jsonb_set(coalesce(translations, '{}'::jsonb), '{fr}', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('contraindications', $SQLTXT$["Contre-indications : Ne pas utiliser ce produit si vous prenez des antibiotiques ou de la nitroglycérine. Ne pas utiliser ce produit si vous avez une obstruction des voies biliaires. Ne pas utiliser ce produit si vous êtes enceinte ou si vous allaitez.", "Réactions indésirables connues : Cessez l'utilisation en cas de trouble gastro-intestinal et/ou d'hypersensibilité/allergie.", "Réactions indésirables connues : Peut causer des gaz et/ou des ballonnements temporaires. Cessez l'utilisation en cas d'hypersensibilité/allergie. Peut causer des problèmes digestifs. De rares cas imprévisibles de lésions hépatiques associés à des produits contenant de l'extrait de thé vert ont été signalés (au Canada et à l'international).", "Contre-indications : Ne pas utiliser si vous avez de la difficulté à avaler. Ne pas utiliser ce produit si vous présentez un changement soudain des habitudes intestinales persistant depuis plus de 2 semaines, un saignement rectal non diagnostiqué, ou une absence de défécation après l'utilisation d'un autre produit laxatif.", "Contre-indications : Ne pas utiliser ce produit si vous êtes enceinte ou si vous allaitez. Ne pas utiliser ce produit si vous prenez des produits de santé qui affectent la coagulation sanguine, car cela pourrait augmenter le risque de saignement spontané.", "Réactions indésirables connues : Cessez l'utilisation en cas d'hypersensibilité/allergie. Les personnes sensibles à l'acide nicotinique peuvent éprouver une rougeur de la peau généralement légère et transitoire. Certaines personnes peuvent éprouver de la constipation, de la diarrhée et/ou des vomissements. Ne pas utiliser ce produit si vous avez une allergie au lait."]$SQLTXT$::jsonb)) WHERE slug = $SQLTXT$rosmarinus-officinalis-l$SQLTXT$;
UPDATE public.herbs SET contraindications = ARRAY[$SQLTXT$Contra-Indications: Do not use if you have high blood pressure.$SQLTXT$, $SQLTXT$Known Adverse Reactions: Some people may experience mild gastrointestinal bloating, constipation or indigestion.$SQLTXT$, $SQLTXT$Contra-Indications: Do not use this product if you have high blood pressure.$SQLTXT$, $SQLTXT$Known Adverse Reactions: Some people may experience mild gastrointestinal bloating, constipation or indigestion. Some people may experience drowsiness. Exercise caution if operating heavy machinery, driving a motor vehicle or involved in activities requiring mental alertness.$SQLTXT$, $SQLTXT$Contra-Indications: Do not use if you have high blood pressure. Do not use if you are pregnant or breastfeeding. Do not use if you have bipolar disorder or bipolar spectrum disorder.$SQLTXT$, $SQLTXT$Known Adverse Reactions: Some people may experience mild gastrointestinal bloating, constipation or indigestion. Hypersensitivity/allergy has been known to occur. If this is the case, discontinue use.$SQLTXT$]::text[], translations = jsonb_set(coalesce(translations, '{}'::jsonb), '{fr}', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('contraindications', $SQLTXT$["Contre-indications : Ne pas utiliser si vous avez de l'hypertension artérielle.", "Réactions indésirables connues : Certaines personnes peuvent éprouver de légers ballonnements gastro-intestinaux, de la constipation ou de l'indigestion.", "Contre-indications : Ne pas utiliser ce produit si vous avez de l'hypertension artérielle.", "Réactions indésirables connues : Certaines personnes peuvent éprouver de légers ballonnements gastro-intestinaux, de la constipation ou de l'indigestion. Certaines personnes peuvent éprouver de la somnolence. Faire preuve de prudence si vous utilisez de la machinerie lourde, conduisez un véhicule automobile ou participez à des activités nécessitant de la vigilance mentale. Cesser l'utilisation en cas d'hypersensibilité.", "Contre-indications : Ne pas utiliser si vous avez de l'hypertension artérielle. Ne pas utiliser si vous êtes enceinte ou si vous allaitez. Ne pas utiliser si vous avez un trouble bipolaire ou un trouble du spectre bipolaire.", "Réactions indésirables connues : Certaines personnes peuvent éprouver de légers ballonnements gastro-intestinaux, de la constipation ou de l'indigestion. Une hypersensibilité ou une allergie a été signalée. Dans ce cas, cesser l'utilisation."]$SQLTXT$::jsonb)) WHERE slug = $SQLTXT$rhododendron-aureum$SQLTXT$;
UPDATE public.herbs SET contraindications = ARRAY[$SQLTXT$Contra-Indications: Avoid using if you have a hormone sensitive cancer or condition, such as uterine, ovarian or breast cancer, fibroids, or endometriosis.$SQLTXT$, $SQLTXT$Contra-Indications: Do not take if currently taking Warfarin or other anticoagulant medications, MAOI's, if you are pregnant or breastfeeding, if you have stomach or intestinal ulcers, if you are allergic to artichoke or other plants of the Asteraceae/Compositae/Daisy family.$SQLTXT$, $SQLTXT$Known Adverse Reactions: Some people may experience headaches. Hypersensitivity has been known to occur in which case, discontinue use.$SQLTXT$]::text[], translations = jsonb_set(coalesce(translations, '{}'::jsonb), '{fr}', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('contraindications', $SQLTXT$["Contre-indications : Éviter l'utilisation en cas de cancer ou d'affection hormono-dépendante, comme le cancer de l'utérus, des ovaires ou du sein, les fibromes ou l'endométriose.", "Contre-indications : Ne pas prendre si vous prenez actuellement de la warfarine ou d'autres anticoagulants, des IMAO, si vous êtes enceinte ou allaitez, si vous avez des ulcères gastriques ou intestinaux, si vous êtes allergique à l'artichaut ou à d'autres plantes de la famille des Asteraceae/Compositae/Daisy.", "Réactions indésirables connues : Certaines personnes peuvent ressentir des maux de tête. Une hypersensibilité a été signalée, auquel cas il faut cesser l'utilisation."]$SQLTXT$::jsonb)) WHERE slug = $SQLTXT$mentha-piperita$SQLTXT$;
UPDATE public.herbs SET contraindications = ARRAY[$SQLTXT$Known Adverse Reactions: Certain patients have noticed minor gastro-intestinal bloating. Stop use if hypersensitivity/allergy occurs.$SQLTXT$, $SQLTXT$Contra-Indications: People who have had an organ transplant and are on immunosuppressive drugs should consult their health care practitioner. This product should not be used by people with allergies to milk protein.$SQLTXT$, $SQLTXT$Contra-Indications: Do not use if you are pregnant or breastfeeding; if you have difficulty swallowing; if you have diabetes mellitus in which blood sugar is difficult to regulate.$SQLTXT$, $SQLTXT$Known Adverse Reactions: Hypersensitivity, such as an allergy, has been known to occur in rare cases; in which case, discontinue use. May cause temporary gas and/or bloating. May have laxative effects.$SQLTXT$, $SQLTXT$Known Adverse Reactions: No statement required.$SQLTXT$, $SQLTXT$Contra-Indications: Do not use if you currently have or previously had breast cancer and/or breast tumours or if you have a predisposition to breast cancer, as indicated by an abnormal mammogram and/or biopsy, or a family member with breast cancer If you are pregnant or breastfeeding, do not use.$SQLTXT$]::text[], translations = jsonb_set(coalesce(translations, '{}'::jsonb), '{fr}', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('contraindications', $SQLTXT$["Réactions indésirables connues : Certains patients ont remarqué des ballonnements gastro-intestinaux mineurs. Cessez l'utilisation en cas d'hypersensibilité ou d'allergie.", "Contre-indications : Les personnes ayant subi une transplantation d'organe et prenant des médicaments immunosuppresseurs doivent consulter leur professionnel de la santé. Ce produit ne doit pas être utilisé par les personnes allergiques aux protéines de lait.", "Contre-indications : Ne pas utiliser si vous êtes enceinte ou si vous allaitez ; si vous avez de la difficulté à avaler ; si vous avez un diabète sucré dont la glycémie est difficile à réguler.", "Réactions indésirables connues : Une hypersensibilité, telle qu'une allergie, a été signalée dans de rares cas ; le cas échéant, cessez l'utilisation. Peut causer des gaz et/ou des ballonnements temporaires. Peut avoir des effets laxatifs.", "Réactions indésirables connues : Aucune mention requise.", "Contre-indications : Ne pas utiliser si vous avez actuellement ou avez déjà eu un cancer du sein et/ou des tumeurs mammaires, ou si vous avez une prédisposition au cancer du sein, comme l'indique une mammographie et/ou une biopsie anormale, ou un membre de la famille atteint de cancer du sein. Si vous êtes enceinte ou si vous allaitez, ne pas utiliser."]$SQLTXT$::jsonb)) WHERE slug = $SQLTXT$triticum-aestivum-subsp-spelta$SQLTXT$;
UPDATE public.herbs SET contraindications = ARRAY[$SQLTXT$Contra-Indications: Do not use if you are pregnant or breastfeeding. Do not use if you are taking heart medications, corticosteroids, stimulant laxatives, or other health products that may contribute electrolyte imbalance.$SQLTXT$, $SQLTXT$Cautions and Warnings: Do not use this product if you are taking thiazide diuretics, cardiac glycosides, corticosteroids, stimulant laxatives or other medications which may aggravate electrolyte imbalance. Do not use this product if you are pregnant or breastfeeding.$SQLTXT$]::text[], translations = jsonb_set(coalesce(translations, '{}'::jsonb), '{fr}', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('contraindications', $SQLTXT$["Contre-indications : Ne pas utiliser si vous êtes enceinte ou si vous allaitez. Ne pas utiliser si vous prenez des médicaments pour le cœur, des corticostéroïdes, des laxatifs stimulants ou d'autres produits de santé susceptibles de contribuer à un déséquilibre électrolytique.", "Mises en garde et avertissements : Ne pas utiliser ce produit si vous prenez des diurétiques thiazidiques, des glycosides cardiaques, des corticostéroïdes, des laxatifs stimulants ou d'autres médicaments susceptibles d'aggraver un déséquilibre électrolytique. Ne pas utiliser ce produit si vous êtes enceinte ou si vous allaitez."]$SQLTXT$::jsonb)) WHERE slug = $SQLTXT$glycyrrhiza-inflata$SQLTXT$;
UPDATE public.herbs SET contraindications = ARRAY[$SQLTXT$Contra-Indications: If you are pregnant, do not use this product.$SQLTXT$, $SQLTXT$Contra-Indications: Do not use this product if you are pregnant or breastfeeding.$SQLTXT$, $SQLTXT$Contra-Indications: If you have an immune-compromised condition (e.g. AIDS, lymphoma, patients undergoing long-term corticosteroid treatment), do not use this product.$SQLTXT$, $SQLTXT$Known Adverse Reactions: Hypersensitivity/allergy can occur, in which case discontinue use and consult your healthcare practitioner. May cause mild gastro-intestinal discomfort (such as gas, bloating, cramps). May cause temporary gas and bloating.$SQLTXT$, $SQLTXT$Known Adverse Reactions: Stop use if gastro-intestinal disturbance and/or hypersensitivity/allergy, nausea, vomiting or diarrhoea occurs.$SQLTXT$, $SQLTXT$Contra-Indications: Consult a healthcare practitioner/health care provider/health care professional/doctor/ physician prior to use if you are pregnant or breastfeeding.$SQLTXT$]::text[], translations = jsonb_set(coalesce(translations, '{}'::jsonb), '{fr}', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('contraindications', $SQLTXT$["Contre-indications : Si vous êtes enceinte, ne pas utiliser ce produit.", "Contre-indications : Ne pas utiliser ce produit si vous êtes enceinte ou si vous allaitez.", "Contre-indications : Si vous avez un état immunodéprimé (p. ex. SIDA, lymphome, patients sous traitement corticostéroïdien à long terme), ne pas utiliser ce produit.", "Réactions indésirables connues : Une hypersensibilité/allergie peut survenir, auquel cas cessez l'utilisation et consultez votre praticien de soins de santé. Peut causer un léger inconfort gastro-intestinal (comme des gaz, des ballonnements, des crampes). Peut causer des gaz et des ballonnements temporaires.", "Réactions indésirables connues : Cessez l'utilisation si des troubles gastro-intestinaux et/ou une hypersensibilité/allergie, des nausées, des vomissements ou de la diarrhée surviennent.", "Contre-indications : Consultez un praticien de soins de santé/un fournisseur de soins de santé/un professionnel de la santé/un médecin avant l'utilisation si vous êtes enceinte ou si vous allaitez."]$SQLTXT$::jsonb)) WHERE slug = $SQLTXT$actinidia-chinensis$SQLTXT$;
UPDATE public.herbs SET contraindications = ARRAY[$SQLTXT$Contra-Indications: If you are pregnant or breastfeeding, do not use this product. Do not use if you have kidney or liver disorder, heart disease, high or low blood pressure, diabetes, or edema (swelling of hands, face and feet) or are taking products containing diuretics.$SQLTXT$, $SQLTXT$Known Adverse Reactions: Hypersensitivity (e.g. allergy) and gastrointestinal discomfort has been known to occur; in which case, discontinue use.$SQLTXT$, $SQLTXT$Contra-Indications: Do not use if you are pregnant or breastfeeding.$SQLTXT$, $SQLTXT$Known Adverse Reactions: Hypersensitivity is known to occur; in which case, discontinue use.$SQLTXT$, $SQLTXT$Contra-Indications: Do not use if you have high blood pressure or if you are allergic to plants of the Asteraceae/Compositae/Daisy family.$SQLTXT$]::text[], translations = jsonb_set(coalesce(translations, '{}'::jsonb), '{fr}', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('contraindications', $SQLTXT$["Contre-indications : Si vous êtes enceinte ou allaitez, n'utilisez pas ce produit. Ne pas utiliser si vous avez un trouble rénal ou hépatique, une maladie cardiaque, une pression artérielle élevée ou basse, du diabète, ou de l'œdème (gonflement des mains, du visage et des pieds) ou si vous prenez des produits contenant des diurétiques.", "Réactions indésirables connues : Des cas d'hypersensibilité (p. ex. allergie) et d'inconfort gastro-intestinal ont été signalés ; dans ce cas, cessez l'utilisation.", "Contre-indications : Ne pas utiliser si vous êtes enceinte ou allaitez.", "Réactions indésirables connues : Des cas d'hypersensibilité ont été signalés ; dans ce cas, cessez l'utilisation.", "Contre-indications : Ne pas utiliser si vous avez une pression artérielle élevée ou si vous êtes allergique aux plantes de la famille Asteraceae/Compositae/Daisy."]$SQLTXT$::jsonb)) WHERE slug = $SQLTXT$vaccinium-macrocarpon-aiton$SQLTXT$;
UPDATE public.herbs SET contraindications = ARRAY[$SQLTXT$Contra-Indications: Do not use this product if you are pregnant or breastfeeding.$SQLTXT$, $SQLTXT$Contra-Indications: Do not use if you are pregnant or breastfeeding.$SQLTXT$, $SQLTXT$Contra-Indications: If you are pregnant or breastfeeding, do not use this product.$SQLTXT$, $SQLTXT$Cautions and Warnings: Do not take this product if you are pregnant or nursing, or if you are allergic to any other ingredients in the product.$SQLTXT$]::text[], translations = jsonb_set(coalesce(translations, '{}'::jsonb), '{fr}', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('contraindications', $SQLTXT$["Contre-indications : Ne pas utiliser ce produit si vous êtes enceinte ou si vous allaitez.", "Contre-indications : Ne pas utiliser si vous êtes enceinte ou si vous allaitez.", "Contre-indications : Si vous êtes enceinte ou si vous allaitez, ne pas utiliser ce produit.", "Mises en garde et avertissements : Assurez-vous de boire suffisamment de liquide avant, pendant et après l'exercice. Si vous êtes enceinte et allaitez, consulter un praticien de soins de santé avant d'en faire l'usage Entreposer dans un endroit frais et sec.", "Mises en garde et avertissements : Ne pas prendre ce produit si vous êtes enceinte ou si vous allaitez, ou si vous êtes allergique à tout autre ingrédient du produit."]$SQLTXT$::jsonb)) WHERE slug = $SQLTXT$styphnolobium-japonicum$SQLTXT$;
UPDATE public.herbs SET contraindications = ARRAY[$SQLTXT$Contra-Indications: Do not use this product if you are pregnant.$SQLTXT$, $SQLTXT$Known Adverse Reactions: Stop use if hypersensitivity/allergy occurs.$SQLTXT$, $SQLTXT$Contra-Indications: If you are pregnant or breastfeeding, do not use. If you have hypokalemia, high blood pressure, kidney disorder, cardiovascular disorder, an immune-compromised condition (e.g. AIDS, lymphoma, patients undergoing long-term corticosteroid treatment), do not use.$SQLTXT$, $SQLTXT$Known Adverse Reactions: Hypersensitivity (e.g. allergy) can occur, in which case, discontinue use. Discontinue use in case of gastrointestinal upsets, such as abdominal cramps, nausea, vomiting, diarrhea.$SQLTXT$]::text[], translations = jsonb_set(coalesce(translations, '{}'::jsonb), '{fr}', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('contraindications', $SQLTXT$["Contre-indications : Ne pas utiliser ce produit si vous êtes enceinte.", "Effets indésirables connus : Cesser l'utilisation en cas d'hypersensibilité ou d'allergie.", "Contre-indications : Si vous êtes enceinte ou allaitez, ne pas utiliser. Si vous avez une hypokaliémie, une hypertension artérielle, un trouble rénal, un trouble cardiovasculaire, un état immunodéprimé (p. ex. SIDA, lymphome, patients sous corticothérapie à long terme), ne pas utiliser.", "Effets indésirables connus : Une hypersensibilité (p. ex. allergie) peut survenir, auquel cas cesser l'utilisation. Cesser l'utilisation en cas de troubles gastro-intestinaux, tels que crampes abdominales, nausées, vomissements, diarrhée."]$SQLTXT$::jsonb)) WHERE slug = $SQLTXT$prunus-salicina$SQLTXT$;
UPDATE public.herbs SET contraindications = ARRAY[$SQLTXT$Cautions and Warnings: Consult a healthcare practitioner prior to use if you are pregnant or breastfeeding, have an iron deficiency, gall stones or a bile duct obstruction, stomach ulcers or excess stomach acid, or if you have a liver disorder.$SQLTXT$, $SQLTXT$Known Adverse Reactions: Rare, unpredictable cases of liver injury associated with green-tea extract containing products have been reported.$SQLTXT$]::text[], translations = jsonb_set(coalesce(translations, '{}'::jsonb), '{fr}', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('contraindications', $SQLTXT$["Mises en garde et avertissements : Consultez un professionnel de la santé avant d'utiliser ce produit si vous êtes enceinte ou allaitez, si vous avez une carence en fer, des calculs biliaires ou une obstruction des voies biliaires, des ulcères d'estomac ou un excès d'acide gastrique, ou si vous avez un trouble hépatique.", "Réactions indésirables connues : De rares cas imprévisibles de lésions hépatiques associés à des produits contenant de l'extrait de thé vert ont été signalés."]$SQLTXT$::jsonb)) WHERE slug = $SQLTXT$bambusa-bambos$SQLTXT$;
UPDATE public.herbs SET contraindications = ARRAY[$SQLTXT$Contra-Indications: If you experience gastrointestinal tract irritation and/or discomfort (e.g. nausea and vomiting), discontinue use. Do not use if you are allergic to anethole or plants of the Apiaceae/Carrot family. Do not inhale. If you are pregnant or breastfeeding do not use this product.$SQLTXT$, $SQLTXT$Known Adverse Reactions: Hypersensitivity (e.g. allergy) has been known to occur; in which case, discontinue use. Some people may experience gastroesophageal reflux. Some people may experience drowsiness.$SQLTXT$]::text[], translations = jsonb_set(coalesce(translations, '{}'::jsonb), '{fr}', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('contraindications', $SQLTXT$["Contre-indications : Si vous éprouvez une irritation et/ou un malaise gastro-intestinal (p. ex. nausées et vomissements), cessez l'utilisation. N'utilisez pas si vous êtes allergique à l'anéthole ou aux plantes de la famille des Apiaceae/Carotte. Ne pas inhaler. Si vous êtes enceinte ou si vous allaitez, n'utilisez pas ce produit.", "Réactions indésirables connues : Une hypersensibilité (p. ex. allergie) a été signalée ; le cas échéant, cessez l'utilisation. Certaines personnes peuvent éprouver un reflux gastro-œsophagien. Certaines personnes peuvent éprouver de la somnolence."]$SQLTXT$::jsonb)) WHERE slug = $SQLTXT$eugenia-caryophyllus$SQLTXT$;
UPDATE public.herbs SET contraindications = ARRAY[$SQLTXT$Contra-Indications: If you have bipolar disorder or bipolar spectrum disorder, do not use this product.$SQLTXT$, $SQLTXT$Known Adverse Reactions: May cause a flushing, tingling and/or prickling sensation of the skin, in which case, reduce the dose. If you experience irritability or insomnia, discontinue use. Hypersensitivity/allergy is known to occur, in which case discontinue use.$SQLTXT$, $SQLTXT$Contra-Indications: Do not use this product with other potassium-containing supplements or with potassium-containing salt-substitutes.$SQLTXT$, $SQLTXT$Contra-Indications: If you are pregnant or breastfeeding, do not use this product.$SQLTXT$]::text[], translations = jsonb_set(coalesce(translations, '{}'::jsonb), '{fr}', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('contraindications', $SQLTXT$["Contre-indications : Si vous avez un trouble bipolaire ou un trouble du spectre bipolaire, ne pas utiliser ce produit.", "Réactions indésirables connues : Peut causer une sensation de bouffées de chaleur, de picotement et/ou de fourmillement de la peau ; dans ce cas, réduire la dose. Si vous éprouvez de l'irritabilité ou de l'insomnie, cesser l'utilisation. Une hypersensibilité/allergie est connue pour survenir ; dans ce cas, cesser l'utilisation.", "Contre-indications : Ne pas utiliser ce produit avec d'autres suppléments contenant du potassium ni avec des substituts de sel contenant du potassium.", "Contre-indications : Si vous êtes enceinte ou si vous allaitez, ne pas utiliser ce produit."]$SQLTXT$::jsonb)) WHERE slug = $SQLTXT$citrullus-lanatus-var-lanatus$SQLTXT$;
UPDATE public.herbs SET contraindications = ARRAY[$SQLTXT$Contra-Indications: Do not use this product if you are pregnant or breastfeeding. Do not use this product if you are pregnant or if you have hypermenorrhea/profuse menstrual flow/heavy periods.$SQLTXT$, $SQLTXT$Contra-Indications: If you are pregnant or breastfeeding, do not use this product.$SQLTXT$]::text[], translations = jsonb_set(coalesce(translations, '{}'::jsonb), '{fr}', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('contraindications', $SQLTXT$["Contre-indications : Ne pas utiliser ce produit si vous êtes enceinte ou si vous allaitez. Ne pas utiliser ce produit si vous êtes enceinte ou si vous avez une hyperménorrhée/un flux menstruel abondant/des règles abondantes.", "Contre-indications : Si vous êtes enceinte ou si vous allaitez, ne pas utiliser ce produit."]$SQLTXT$::jsonb)) WHERE slug = $SQLTXT$sambucus-chinensis$SQLTXT$;
UPDATE public.herbs SET contraindications = ARRAY[$SQLTXT$Contra-Indications: If you are pregnant or breastfeeding, do not use this product.$SQLTXT$, $SQLTXT$Known Adverse Reactions: Gastrointestinal discomfort may occur.$SQLTXT$, $SQLTXT$Contra-Indications: Do not use this product if you are pregnant or breastfeeding.$SQLTXT$, $SQLTXT$Known Adverse Reactions: Isomnia has been known to occur; in which case, discontinue use. Irritability, dizziness and/or tremor have been known to occur; in which case, discontinue use. Nausea and/or loss of appetite have been known to occur; in which case, discontinue use.$SQLTXT$]::text[], translations = jsonb_set(coalesce(translations, '{}'::jsonb), '{fr}', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('contraindications', $SQLTXT$["Contre-indications : Si vous êtes enceinte ou si vous allaitez, n'utilisez pas ce produit.", "Réactions indésirables connues : Un inconfort gastro-intestinal peut survenir.", "Contre-indications : N'utilisez pas ce produit si vous êtes enceinte ou si vous allaitez.", "Réactions indésirables connues : Des cas d'insomnie ont été signalés ; dans ce cas, cessez l'utilisation. Des cas d'irritabilité, de vertiges et/ou de tremblements ont été signalés ; dans ce cas, cessez l'utilisation. Des cas de nausées et/ou de perte d'appétit ont été signalés ; dans ce cas, cessez l'utilisation."]$SQLTXT$::jsonb)) WHERE slug = $SQLTXT$lepidium-apetalum$SQLTXT$;
UPDATE public.herbs SET contraindications = ARRAY[$SQLTXT$Contra-Indications: Do not use if you are pregnant or breastfeeding.$SQLTXT$, $SQLTXT$Contra-Indications: Do not use if you are taking anti-cancer medications, blood thinners, antidepressant medications (e.g. selective serotonin reuptake inhibitors (SSRI)), anti-HIV agents, cardiovascular medications, immunosuppressants, and/or contraceptive medications.$SQLTXT$, $SQLTXT$Contra-Indications: If you are pregnant or breastfeeding, do not use this product.$SQLTXT$]::text[], translations = jsonb_set(coalesce(translations, '{}'::jsonb), '{fr}', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('contraindications', $SQLTXT$["Contre-indications : Ne pas utiliser si vous êtes enceinte ou si vous allaitez.", "Contre-indications : Ne pas utiliser si vous prenez des médicaments anticancéreux, des anticoagulants, des antidépresseurs (p. ex. inhibiteurs sélectifs de la recapture de la sérotonine (ISRS)), des agents anti-VIH, des médicaments cardiovasculaires, des immunosuppresseurs et/ou des contraceptifs.", "Contre-indications : Si vous êtes enceinte ou si vous allaitez, ne pas utiliser ce produit."]$SQLTXT$::jsonb)) WHERE slug = $SQLTXT$nardostachys-chinensis$SQLTXT$;
UPDATE public.herbs SET contraindications = ARRAY[$SQLTXT$Contra-Indications: Do not use if you are pregnant.$SQLTXT$, $SQLTXT$Known Adverse Reactions: Hypersensitivity, such as an allergy, has been known to occur; in which case, discontinue use. Some people may experience mild gastrointestinal disturbances, nausea, restlessness and/or headaches.$SQLTXT$, $SQLTXT$Contra-Indications: Do not use if you have a seizure disorder such as epilepsy. Do not use if you are pregnant, breastfeeding or attempting to conceive.$SQLTXT$, $SQLTXT$Contra-Indications: Do not use this product if you currently have or previously had breast cancer or if you have a predisposition to breast cancer, as indicated by an abnormal mammogram and/or biopsy, or if you have a family member with breast cancer.$SQLTXT$, $SQLTXT$Known Adverse Reactions: Some people may experience drowsiness. Exercise caution if operating heavy machinery, driving a motor vehicle or involved in activities requiring mental alertness.$SQLTXT$]::text[], translations = jsonb_set(coalesce(translations, '{}'::jsonb), '{fr}', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('contraindications', $SQLTXT$["Contre-indications : Ne pas utiliser si vous êtes enceinte. Ne pas utiliser si vous prenez des médicaments anticancéreux, des anticoagulants, des antidépresseurs (p. ex. inhibiteurs sélectifs de la recapture de la sérotonine (ISRS)), des agents anti-VIH, des médicaments cardiovasculaires, des immunosuppresseurs et/ou des contraceptifs.", "Réactions indésirables connues : Une hypersensibilité, telle qu'une allergie, a été signalée ; dans ce cas, cesser l'utilisation. Certaines personnes peuvent éprouver de légers troubles gastro-intestinaux, des nausées, de l'agitation et/ou des maux de tête.", "Contre-indications : Ne pas utiliser si vous avez un trouble convulsif tel que l'épilepsie. Ne pas utiliser si vous êtes enceinte, si vous allaitez ou si vous tentez de concevoir.", "Contre-indications : Ne pas utiliser ce produit si vous avez actuellement ou avez déjà eu un cancer du sein ou si vous avez une prédisposition au cancer du sein, comme l'indique une mammographie et/ou une biopsie anormale, ou si un membre de votre famille a un cancer du sein.", "Réactions indésirables connues : Certaines personnes peuvent éprouver de la somnolence. Faire preuve de prudence si vous utilisez de la machinerie lourde, conduisez un véhicule automobile ou participez à des activités nécessitant de la vigilance mentale."]$SQLTXT$::jsonb)) WHERE slug = $SQLTXT$rheum-rhaponticum$SQLTXT$;
UPDATE public.herbs SET contraindications = ARRAY[$SQLTXT$Contra-Indications: For adult use only. Do not use if you have acute viral infection, heavy periods, haemorrhagic disease or a hormone-sensitive condition. Do not use if you are pregnant, breastfeeding, or taking blood-thinning or prescription medications.$SQLTXT$, $SQLTXT$Contra-Indications: Do not use if you are pregnant; breastfeeding; or during early stages of colds and flu.$SQLTXT$]::text[], translations = jsonb_set(coalesce(translations, '{}'::jsonb), '{fr}', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('contraindications', $SQLTXT$["Contre-indications : Pour usage adulte uniquement. N'utilisez pas si vous avez une infection virale aiguë, des règles abondantes, une maladie hémorragique ou une affection hormono-dépendante. N'utilisez pas si vous êtes enceinte, si vous allaitez ou si vous prenez des médicaments anticoagulants ou sur ordonnance. Contre-indiqué chez les personnes présentant une distension abdominale.", "Contre-indications : N'utilisez pas si vous êtes enceinte, si vous allaitez ou pendant les premiers stades du rhume et de la grippe."]$SQLTXT$::jsonb)) WHERE slug = $SQLTXT$biota-orientalis$SQLTXT$;
UPDATE public.herbs SET contraindications = ARRAY[$SQLTXT$Known Adverse Reactions: Rare, unpredictable cases of liver injury associated with green tea extract-containing products have been reported (in Canada and Internationally). People sensitive to nicotinic acid may experience flushing of the skin that is generally mild and transient.$SQLTXT$, $SQLTXT$Contra-Indications: Do not use if you are pregnant.$SQLTXT$, $SQLTXT$Contra-Indications: Do not use this product if you have an immune-compromised condition (e.g. AIDS, lymphoma, patients undergoing long-term corticosteroid treatment).$SQLTXT$, $SQLTXT$Known Adverse Reactions: Stop use if hypersensitivity/allergy occurs.$SQLTXT$, $SQLTXT$Known Adverse Reactions: Hypersensitivity has been known to occur. May cause mild gastro-intestinal discomfort (such as gas, bloating, cramps).$SQLTXT$, $SQLTXT$Contra-Indications: NOTE: This product contains Alder Buckthorn and Chinese Rhubarb powder. Read and follow directions carefully.$SQLTXT$]::text[], translations = jsonb_set(coalesce(translations, '{}'::jsonb), '{fr}', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('contraindications', $SQLTXT$["Effets indésirables connus : De rares cas imprévisibles d'atteinte hépatique associés à des produits contenant de l'extrait de thé vert ont été signalés (au Canada et à l'international). Les personnes sensibles à l'acide nicotinique peuvent présenter des bouffées vasomotrices cutanées généralement légères et transitoires.", "Contre-indications : Ne pas utiliser si vous êtes enceinte.", "Contre-indications : Ne pas utiliser ce produit si vous avez un état immunodéprimé (p. ex. SIDA, lymphome, patients sous corticothérapie à long terme).", "Effets indésirables connus : Cesser l'utilisation en cas d'hypersensibilité ou d'allergie.", "Effets indésirables connus : Des cas d'hypersensibilité ont été rapportés. Peut causer un léger inconfort gastro-intestinal (tel que des gaz, des ballonnements, des crampes).", "Contre-indications : REMARQUE : Ce produit contient de la poudre de nerprun et de rhubarbe de Chine. Lire et suivre attentivement les directives."]$SQLTXT$::jsonb)) WHERE slug = $SQLTXT$prunus-domestica$SQLTXT$;
UPDATE public.herbs SET contraindications = ARRAY[$SQLTXT$Contra-Indications: Contraindicated in protein hypersensitivity and chronic progressive infections such as tuberculosis and AIDS.$SQLTXT$, $SQLTXT$Contra-Indications: Do not use 1) if you are pregnant or breastfeeding 2) if you are allergic to plants of the Asteraceae/Compositae/Daisy family 3) if you are taking anti-cancer medications, blood thinners, antidepressant medications (e.g. selective serotonin reuptake inhibitors (SSRI)).$SQLTXT$, $SQLTXT$Known Adverse Reactions: Hypersensitivity/allergy is known to occur; in which case, discontinue use. Some people may experience drowsiness. Exercise caution if operating heavy machinery, driving a motor vehicle or involved in activities requiring mental alertness.$SQLTXT$]::text[], translations = jsonb_set(coalesce(translations, '{}'::jsonb), '{fr}', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('contraindications', $SQLTXT$["Contre-indications : Contre-indiqué en cas d'hypersensibilité aux protéines et d'infections chroniques évolutives telles que la tuberculose et le SIDA.", "Mises en garde et avertissements : * Garder hors de la portée des enfants. La quantité de fer présente dans les comprimés contenus dans l'emballage est suffisante pour causer des torts sérieux à un enfant si celui-ci devait consommer, en un seul coup, tous les comprimés de la bouteille.", "Contre-indications : Ne pas utiliser 1) si vous êtes enceinte ou si vous allaitez 2) si vous êtes allergique aux plantes de la famille des Asteraceae/Compositae/Daisy 3) si vous prenez des médicaments anticancéreux, des anticoagulants, des antidépresseurs (p. ex. les inhibiteurs sélectifs de la recapture de la sérotonine (ISRS)).", "Réactions indésirables connues : Des cas d'hypersensibilité/allergie sont connus ; dans ce cas, cesser l'utilisation. Certaines personnes peuvent ressentir de la somnolence. Faire preuve de prudence si vous conduisez de la machinerie lourde, un véhicule motorisé ou si vous participez à des activités nécessitant de la vigilance mentale.", "Contre-indications : Ne pas prendre si vous êtes enceinte ou si vous allaitez. Ne pas utiliser en cas d'allergie à la famille des astéracées ou composées (marguerite jaune). Ne pas utiliser en cas d'inflammation de la vésicule biliaire, d'obstruction du canal cholédoque ou d'occlusion intestinale.", "Mises en garde et avertissements : Consulter un praticien de soins de santé se les symptômes persistent ou s'aggravent. Consulter un praticien de soins de santé avant l'utilisation si vous souffrez de maladies rénales ou cardiaques ou si vous prenez des médicaments de prescription."]$SQLTXT$::jsonb)) WHERE slug = $SQLTXT$matricaria-recutita$SQLTXT$;
UPDATE public.herbs SET contraindications = ARRAY[$SQLTXT$Contra-Indications: If you are pregnant or breastfeeding, do not use this product. Contraindicated for those with weak stomach and spleen or diarrhea. Contraindicated for those with cough due to yin deficiency or general debility.$SQLTXT$, $SQLTXT$Known Adverse Reactions: Hypersensitivity, such as an allergy, has been known to occur; in which case, discontinue use.$SQLTXT$, $SQLTXT$Contra-Indications: If you are pregnant or breastfeeding, do not use this product. Do not use this product if you have hypokalemia, high blood pressure or a kidney or cardiovascular disorder.$SQLTXT$, $SQLTXT$Known Adverse Reactions: Stop use if you experience insomnia, anxiety or headaches.$SQLTXT$, $SQLTXT$Contra-Indications: If you are pregnant or breastfeeding, do not use this product.$SQLTXT$, $SQLTXT$Contra-Indications: Do not use this product if you are pregnant or breastfeeding.$SQLTXT$]::text[], translations = jsonb_set(coalesce(translations, '{}'::jsonb), '{fr}', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('contraindications', $SQLTXT$["Contre-indications : Si vous êtes enceinte ou si vous allaitez, ne pas utiliser ce produit. Contre-indiqué chez les personnes ayant un estomac et une rate faibles ou de la diarrhée. Contre-indiqué chez les personnes ayant une toux due à une déficience du yin ou une faiblesse générale.", "Réactions indésirables connues : Une hypersensibilité, telle qu'une allergie, a été observée ; dans ce cas, cesser l'utilisation.", "Contre-indications : Si vous êtes enceinte ou si vous allaitez, ne pas utiliser ce produit. Ne pas utiliser ce produit si vous avez une hypokaliémie, une pression artérielle élevée ou un trouble rénal ou cardiovasculaire.", "Réactions indésirables connues : Cesser l'utilisation si vous ressentez de l'insomnie, de l'anxiété ou des maux de tête.", "Contre-indications : Si vous êtes enceinte ou si vous allaitez, ne pas utiliser ce produit.", "Contre-indications : Ne pas utiliser ce produit si vous êtes enceinte ou si vous allaitez."]$SQLTXT$::jsonb)) WHERE slug = $SQLTXT$prunus-armeniaca-var-ansu$SQLTXT$;
UPDATE public.herbs SET contraindications = ARRAY[$SQLTXT$Contra-Indications: Do not use if you are taking health products that affect blood coagulation (e.g. blood thinners, clotting factor replacements, acetylsalicylic acid, ibuprofen, fish oils, vitamin E) as this may increase the risk of spontaneous bleeding.$SQLTXT$, $SQLTXT$Known Adverse Reactions: Some people may experience insomnia, anxiety, or headaches, in which case, discontinue use. May cause nausea, dry mouth and fatigue.$SQLTXT$, $SQLTXT$Contra-Indications: Do not use if you have high blood pressure. Do not use if you are taking health product that affect blood coagulation (e.g. blood thinners, clotting factor replacements, acetylsalicylic acid, ibuprofen, fish oils, vitamin E) as this may increase the risk of spontaneous bleeding.$SQLTXT$, $SQLTXT$Known Adverse Reactions: Herbs rich in saponins may cause irritation of the gastric mucous membranes and reflux.$SQLTXT$]::text[], translations = jsonb_set(coalesce(translations, '{}'::jsonb), '{fr}', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('contraindications', $SQLTXT$["Contre-indications : Ne pas utiliser si vous prenez des produits de santé qui affectent la coagulation sanguine (p. ex. anticoagulants, concentrés de facteurs de coagulation, acide acétylsalicylique, ibuprofène, huiles de poisson, vitamine E) car cela pourrait augmenter le risque de saignement spontané.", "Réactions indésirables connues : Certaines personnes peuvent éprouver de l'insomnie, de l'anxiété ou des maux de tête ; dans ce cas, cesser l'utilisation. Peut causer des nausées, une sécheresse buccale et de la fatigue.", "Contre-indications : Ne pas utiliser si vous avez une tension artérielle élevée. Ne pas utiliser si vous prenez des produits de santé qui affectent la coagulation sanguine (p. ex. anticoagulants, concentrés de facteurs de coagulation, acide acétylsalicylique, ibuprofène, huiles de poisson, vitamine E) car cela pourrait augmenter le risque de saignement spontané.", "Réactions indésirables connues : Les plantes riches en saponines peuvent causer une irritation des muqueuses gastriques et un reflux."]$SQLTXT$::jsonb)) WHERE slug = $SQLTXT$bacopa-monniera$SQLTXT$;
UPDATE public.herbs SET contraindications = ARRAY[$SQLTXT$Contra-Indications: Do not use if you 1) are pregnant or breastfeeding 2) are allergic to anethole or plants of the Apiaceae/carrot family 3) have abnormal constrictions of the gastrointestinal tract, potential or existing intestinal blockage, atonic bowel, appendicitis.$SQLTXT$, $SQLTXT$Known Adverse Reactions: Hypersensitivity has been known to occur, in which case, discontinue use.$SQLTXT$]::text[], translations = jsonb_set(coalesce(translations, '{}'::jsonb), '{fr}', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('contraindications', $SQLTXT$["Contre-indications : Ne pas utiliser si vous 1) êtes enceinte ou si vous allaitez 2) êtes allergique à l'anéthole ou aux plantes de la famille des Apiaceae/carottes 3) avez des constrictions anormales du tractus gastro-intestinal, une occlusion intestinale potentielle ou existante, un intestin atone, une appendicite.", "Effets indésirables connus : Une hypersensibilité a été signalée, auquel cas cessez l'utilisation.", "Mises en garde et avertissements : Consulter un praticien de soins de santé avant l'utilisation si vous souffrez du diabète ou d'hypokaliémie, si vous êtes sous thérapie hormonale, des diurétiques, des agents réducteurs de potassium, des inhibiteurs de MAO, si vous souffrez d'arthrite rhumatoïde.", "Contre-indications : Ne pas utiliser en cas de grossesses ou d'allaitement maternel, d'allergie à la famille des astéracées ou composées (marguerite jaune), chez les enfants de moins de 2 ans, si vous souffrez d'une maladie du rein ou du foie, d'hypertension artérielle ou d'une maladie du c¿ur.", "Effets indésirables connus : L'absorption d'alcaloïdes et d'autres drogues alcalines peut être réduite ou inhibée. Peut avoir une laxative et causer d'autres symptômes comme la transpiration, les nausées, les vomissements et l'accélération du rythme cardiaque."]$SQLTXT$::jsonb)) WHERE slug = $SQLTXT$commiphora-molmol$SQLTXT$;
UPDATE public.herbs SET contraindications = ARRAY[$SQLTXT$Contra-Indications: If you are pregnant or breastfeeding, do not use this product.$SQLTXT$, $SQLTXT$Contra-Indications: Do not use this product if you are pregnant or breastfeeding. Do not use this product if you are taking thiazide diuretics, cardiac glycosides, corticosteroids, stimulant laxatives or other medications which may aggravate electrolyte imbalance.$SQLTXT$, $SQLTXT$Contra-Indications: Do not use if you are pregnant or breastfeeding. Do not use if you are taking heart medications, corticosteroids, stimulant laxatives, or other health products that may contribute electrolyte imbalance. Do not use if you have diarrhea, hemorrhagic diseases or heavy periods.$SQLTXT$, $SQLTXT$Contra-Indications: Do not use this product if you are pregnant or breastfeeding. Do not use this product if you have heart disease, high or low blood pressure, kidney or liver disorder, diabetes or edema (swelling of hands, face and feet) or are taking products containing diuretics.$SQLTXT$, $SQLTXT$Known Adverse Reactions: Diuretic effect may occur. Stop use if hypersensitivity/allergy occurs.$SQLTXT$]::text[], translations = jsonb_set(coalesce(translations, '{}'::jsonb), '{fr}', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('contraindications', $SQLTXT$["Contre-indications : Si vous êtes enceinte ou allaitez, ne pas utiliser ce produit.", "Contre-indications : Ne pas utiliser ce produit si vous êtes enceinte ou allaitez. Ne pas utiliser ce produit si vous prenez des diurétiques thiazidiques, des glycosides cardiotoniques, des corticostéroïdes, des laxatifs stimulants ou d'autres médicaments susceptibles d'aggraver un déséquilibre électrolytique.", "Contre-indications : Ne pas utiliser si vous êtes enceinte ou allaitez. Ne pas utiliser si vous prenez des médicaments pour le cœur, des corticostéroïdes, des laxatifs stimulants ou d'autres produits de santé susceptibles de contribuer à un déséquilibre électrolytique. Ne pas utiliser si vous avez de la diarrhée, des maladies hémorragiques ou des règles abondantes.", "Contre-indications : Ne pas utiliser ce produit si vous êtes enceinte ou allaitez. Ne pas utiliser ce produit si vous avez une maladie cardiaque, une pression artérielle élevée ou basse, un trouble rénal ou hépatique, du diabète ou de l'œdème (enflure des mains, du visage et des pieds) ou si vous prenez des produits contenant des diurétiques.", "Réactions indésirables connues : Un effet diurétique peut se produire. Cesser l'utilisation en cas d'hypersensibilité ou d'allergie."]$SQLTXT$::jsonb)) WHERE slug = $SQLTXT$codonopsis-tangshen$SQLTXT$;
UPDATE public.herbs SET contraindications = ARRAY[$SQLTXT$Contra-Indications: If you are pregnant or breastfeeding, do not use this product.$SQLTXT$, $SQLTXT$Contra-Indications: Do not use this product if you are pregnant or breastfeeding. Do not use this product if you have hypokalemia, high blood pressure, or a kidney or cardiovascular disorder.$SQLTXT$]::text[], translations = jsonb_set(coalesce(translations, '{}'::jsonb), '{fr}', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('contraindications', $SQLTXT$["Contre-indications : Si vous êtes enceinte ou allaitez, n'utilisez pas ce produit.", "Contre-indications : N'utilisez pas ce produit si vous êtes enceinte ou allaitez. N'utilisez pas ce produit si vous avez une hypokaliémie, une hypertension artérielle ou un trouble rénal ou cardiovasculaire."]$SQLTXT$::jsonb)) WHERE slug = $SQLTXT$dichroa-febrifuga$SQLTXT$;
UPDATE public.herbs SET contraindications = ARRAY[$SQLTXT$Contra-Indications: If you are pregnant or breastfeeding, do not use this product. Do not use this product if you have hypokalemia or a kidney disorder.$SQLTXT$, $SQLTXT$Known Adverse Reactions: Product may cause nausea, vomiting, abdominal pain, diarrhea, bloating, rash, itchy ulcers, dry mouth, and/or dizziness.$SQLTXT$, $SQLTXT$Contra-Indications: If you are pregnant or breastfeeding, do not use this product. Contraindicated for those with weak stomach and spleen or diarrhea. Contraindicated for those with cough due to yin deficiency or general debility.$SQLTXT$, $SQLTXT$Known Adverse Reactions: Hypersensitivity, such as an allergy, has been known to occur; in which case, discontinue use.$SQLTXT$]::text[], translations = jsonb_set(coalesce(translations, '{}'::jsonb), '{fr}', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('contraindications', $SQLTXT$["Contre-indications : Si vous êtes enceinte ou allaitez, n'utilisez pas ce produit. N'utilisez pas ce produit si vous avez une hypokaliémie ou un trouble rénal.", "Réactions indésirables connues : Le produit peut causer des nausées, des vomissements, des douleurs abdominales, de la diarrhée, des ballonnements, des éruptions cutanées, des ulcères prurigineux, une sécheresse buccale et/ou des étourdissements.", "Contre-indications : Si vous êtes enceinte ou allaitez, n'utilisez pas ce produit. Contre-indiqué chez les personnes ayant un estomac et une rate faibles ou de la diarrhée. Contre-indiqué chez les personnes ayant une toux due à une déficience du yin ou une débilité générale.", "Réactions indésirables connues : Une hypersensibilité, telle qu'une allergie, a été signalée ; dans ce cas, cessez l'utilisation."]$SQLTXT$::jsonb)) WHERE slug = $SQLTXT$prunus-sibirica$SQLTXT$;
UPDATE public.herbs SET contraindications = ARRAY[$SQLTXT$Known Adverse Reactions: Some people may experience drowsiness. Exercise caution if operating heavy machinery, driving a motor vehicle or involved in activities requiring mental alertness. Stop use if hypersensitivity/allergy occurs. Diuretic effect may occur.$SQLTXT$, $SQLTXT$Contra-Indications: If you are pregnant or breastfeeding, do not use this product. Do not use if you are taking medications for depression. Do not use if you have Parkinson's disease. Do not use if you have kidney disorders, gout, gouty arthritis, and/or are susceptible to kidney stone formation.$SQLTXT$, $SQLTXT$Contra-Indications: Do not use this product if you are pregnant or breastfeeding. Do not use this product if you are taking thiazide diuretics, cardiac glycosides, corticosteroids, stimulant laxatives or other medications which may aggravate electrolyte imbalance.$SQLTXT$, $SQLTXT$Known Adverse Reactions: When using this product you may experience gastrointestinal discomfort/disturbances.$SQLTXT$, $SQLTXT$Contra-Indications: Some people may experience insomnia, anxiety, irritability or headache, in which case, discontinue use.$SQLTXT$, $SQLTXT$Known Adverse Reactions: Hypersensitivity/allergy has been known to occur, in which case, discontinue use. Diuretic effect may occur.$SQLTXT$]::text[], translations = jsonb_set(coalesce(translations, '{}'::jsonb), '{fr}', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('contraindications', $SQLTXT$["Effets indésirables connus : certaines personnes peuvent ressentir de la somnolence. Faire preuve de prudence avant de conduire un véhicule, d'utiliser de la machinerie lourde ou d'exercer des activités exigeant de la vigilance mentale. Cesser l'utilisation en cas d'hypersensibilité ou d'allergie. Un effet diurétique peut survenir.", "Contre-indications : Si vous êtes enceinte ou si vous allaitez, ne pas utiliser ce produit. Ne pas utiliser si vous prenez des médicaments contre la dépression. Ne pas utiliser si vous souffrez de la maladie de Parkinson. Ne pas utiliser si vous avez des troubles rénaux, la goutte, l'arthrite goutteuse ou si vous êtes prédisposé à la formation de calculs rénaux.", "Contre-indications : Ne pas utiliser ce produit si vous êtes enceinte ou si vous allaitez. Ne pas utiliser ce produit si vous prenez des diurétiques thiazidiques, des glycosides cardiotoniques, des corticostéroïdes, des laxatifs stimulants ou d'autres médicaments susceptibles d'aggraver un déséquilibre électrolytique.", "Effets indésirables connus : lors de l'utilisation de ce produit, vous pouvez ressentir un inconfort ou des troubles gastro-intestinaux.", "Contre-indications : certaines personnes peuvent ressentir de l'insomnie, de l'anxiété, de l'irritabilité ou des maux de tête ; dans ce cas, cesser l'utilisation.", "Effets indésirables connus : une hypersensibilité ou une allergie a été rapportée ; dans ce cas, cesser l'utilisation. Un effet diurétique peut survenir."]$SQLTXT$::jsonb)) WHERE slug = $SQLTXT$orchis-mascula$SQLTXT$;
UPDATE public.herbs SET contraindications = ARRAY[$SQLTXT$Cautions and Warnings: Do not use if pregnant or breastfeeding.$SQLTXT$, $SQLTXT$Contra-Indications: If you are pregnant or breastfeeding, do not use this product.$SQLTXT$, $SQLTXT$Known Adverse Reactions: Hypersensitivity has been known to occur.$SQLTXT$, $SQLTXT$Known Adverse Reactions: Diuretic effect may occur. Some people may experience diarrhoea. Stop use if hypersensitivity occurs. Hypersensitivity has been known to occur. May cause mild gastro-intestinal discomfort (such as gas, bloating, cramps).$SQLTXT$, $SQLTXT$Contra-Indications: Do not use if you have high blood pressure, cardiovascular conditions, kidney disorders or if you are following a low or no sodium diet.$SQLTXT$]::text[], translations = jsonb_set(coalesce(translations, '{}'::jsonb), '{fr}', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('contraindications', $SQLTXT$["Mises en garde et avertissements : Ne pas utiliser si vous êtes enceinte ou si vous allaitez.", "Contre-indications : Si vous êtes enceinte ou allaitez, n'utilisez pas ce produit.", "Réactions indésirables connues : Des cas d'hypersensibilité ont été signalés.", "Réactions indésirables connues : Un effet diurétique peut se produire. Certaines personnes peuvent présenter de la diarrhée. Cessez l'utilisation en cas d'hypersensibilité. Des cas d'hypersensibilité ont été signalés. Peut causer un inconfort gastro-intestinal léger (tel que des gaz, des ballonnements, des crampes).", "Contre-indications : N'utilisez pas ce produit si vous avez une pression artérielle élevée, des troubles cardiovasculaires, des troubles rénaux ou si vous suivez un régime pauvre ou sans sodium."]$SQLTXT$::jsonb)) WHERE slug = $SQLTXT$dunaliella-salina$SQLTXT$;
UPDATE public.herbs SET contraindications = ARRAY[$SQLTXT$Contra-Indications: Do not use, if you are pregnant or breastfeeding. Do not use if you are allergic to plants of the Asteraceae/Compositae/Daisy family. Do not use if you have difficulty swallowing.$SQLTXT$, $SQLTXT$Contra-Indications: Do not use if you are taking health products that affect blood coagulation (e.g. blood thinners, clotting factor replacements, acetylsalicylic acid, ibuprofen, fish oils, vitamin E) as this may increase the risk of spontaneous bleeding.$SQLTXT$, $SQLTXT$Contra-Indications: If you are pregnant, do not use this product. Do not use this product if you have gastrointestinal ulceration or obstruction. Do not use if you have diabetes.$SQLTXT$, $SQLTXT$Contra-Indications: Do not use if you are taking health products that affect blood coagulation (e.g. blood thinners, clotting factor replacements, acetylsalicylic acid, ibuprofen, fish oils, vitamin E) as this may increases the risk of spontaneous bleeding. If you are pregnant, do not use.$SQLTXT$, $SQLTXT$Known Adverse Reactions: If you experience symptoms of hypoglycaemia including feeling of anxiety, dizziness, tremor, sweating, nausea or headache, discontinue use.$SQLTXT$]::text[], translations = jsonb_set(coalesce(translations, '{}'::jsonb), '{fr}', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('contraindications', $SQLTXT$["Contre-indications : Ne pas utiliser si vous êtes enceinte ou allaitez. Ne pas utiliser si vous êtes allergique aux plantes de la famille des Asteraceae/Compositae/marguerites. Ne pas utiliser si vous avez de la difficulté à avaler.", "Contre-indications : Ne pas utiliser si vous prenez des produits de santé qui influent sur la coagulation sanguine (p. ex. anticoagulants, facteurs de coagulation de remplacement, acide acétylsalicylique, ibuprofène, huiles de poisson, vitamine E), car cela peut augmenter le risque de saignement spontané.", "Contre-indications : Si vous êtes enceinte, ne pas utiliser ce produit. Ne pas utiliser ce produit si vous avez une ulcération ou une obstruction gastro-intestinale. Ne pas utiliser si vous avez du diabète.", "Contre-indications : Ne pas utiliser si vous prenez des produits de santé qui influent sur la coagulation sanguine (p. ex. anticoagulants, facteurs de coagulation de remplacement, acide acétylsalicylique, ibuprofène, huiles de poisson, vitamine E), car cela peut augmenter le risque de saignement spontané. Si vous êtes enceinte, ne pas utiliser.", "Réactions indésirables connues : Si vous ressentez des symptômes d'hypoglycémie, notamment un sentiment d'anxiété, des étourdissements, des tremblements, des sueurs, des nausées ou des maux de tête, cessez l'utilisation."]$SQLTXT$::jsonb)) WHERE slug = $SQLTXT$coffea-arabica$SQLTXT$;
UPDATE public.herbs SET contraindications = ARRAY[$SQLTXT$Contra-Indications: Do not use if pregnant or breastfeeding. Do not use on broken or abraded skin. Do not use this product if you have hypokalemia, high blood pressure, or a kidney or cardiovascular disorder.$SQLTXT$, $SQLTXT$Contra-Indications: Do not use this product if you are pregnant or breastfeeding. Do not use this product if you have any type of respiratory condition. Do not inhale while blowing powder in mouth, on throat.$SQLTXT$, $SQLTXT$Known Adverse Reactions: Stop use if irritation occurs.$SQLTXT$]::text[], translations = jsonb_set(coalesce(translations, '{}'::jsonb), '{fr}', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('contraindications', $SQLTXT$["Contre-indications : Ne pas utiliser si vous êtes enceinte ou si vous allaitez. Ne pas utiliser sur une peau lésée ou abrasée. Ne pas utiliser ce produit si vous avez une hypokaliémie, une hypertension artérielle ou un trouble rénal ou cardiovasculaire.", "Contre-indications : Ne pas utiliser ce produit si vous êtes enceinte ou si vous allaitez. Ne pas utiliser ce produit si vous avez quelque type de trouble respiratoire que ce soit. Ne pas inhaler la poudre en la soufflant dans la bouche ou sur la gorge.", "Réactions indésirables connues : Cesser l'utilisation en cas d'irritation."]$SQLTXT$::jsonb)) WHERE slug = $SQLTXT$sapindus-mukorossi$SQLTXT$;
UPDATE public.herbs SET contraindications = ARRAY[$SQLTXT$Cautions and Warnings: Do not exceed recommended dose. Consult a healthcare practitioner prior to use before if you are taking prescription medications.$SQLTXT$, $SQLTXT$Contra-Indications: Do not take if you are pregnant, breastfeeding, or have a kidney condition. Do not use if you have liver or gall bladder disorders, and/or bowel obstruction. For adult use only.$SQLTXT$, $SQLTXT$Known Adverse Reactions: Discontinue use if you develop symptoms of liver trouble. May increase UV sensitivity; avoid prolonged exposure to UV during use. Gastrointestinal upset and hypersensitivity such as allergy has been known to occur in which case, discontinue use.$SQLTXT$, $SQLTXT$Contra-Indications: Do not exceed recommended dose. Keep away from children. Do not use with other diuretics.$SQLTXT$, $SQLTXT$Known Adverse Reactions: Plant pollen may cause allergic reactions. Hypersensitivity/allergy is known to occur, in which case discontinue use.$SQLTXT$]::text[], translations = jsonb_set(coalesce(translations, '{}'::jsonb), '{fr}', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('contraindications', $SQLTXT$["Mises en garde et précautions : Ne pas dépasser la dose recommandée. Consulter un praticien de soins de santé avant utilisation si vous prenez des médicaments d'ordonnance.", "Contre-indications : Ne pas prendre si vous êtes enceinte, si vous allaitez ou si vous avez une affection rénale. Ne pas utiliser si vous avez des troubles hépatiques ou de la vésicule biliaire et/ou une occlusion intestinale. Pour usage adulte uniquement.", "Réactions indésirables connues : Cesser l'utilisation si vous développez des symptômes de troubles hépatiques. Peut augmenter la sensibilité aux UV ; éviter l'exposition prolongée aux UV pendant l'utilisation. Des troubles gastro-intestinaux et une hypersensibilité telle qu'une allergie ont été signalés, auquel cas cesser l'utilisation.", "Contre-indications : Ne pas dépasser la dose recommandée. Tenir hors de portée des enfants. Ne pas utiliser avec d'autres diurétiques.", "Réactions indésirables connues : Le pollen végétal peut provoquer des réactions allergiques. Une hypersensibilité/allergie est connue pour survenir, auquel cas cesser l'utilisation."]$SQLTXT$::jsonb)) WHERE slug = $SQLTXT$agropyron-repens$SQLTXT$;
UPDATE public.herbs SET contraindications = ARRAY[$SQLTXT$Contra-Indications: Do not use this product if you are pregnant or breastfeeding.$SQLTXT$, $SQLTXT$Cautions and Warnings: Do not use if you are pregnant or breastfeeding. Person experiencing flu symptoms especially with fever should avoid consuming this product. If this product is used concurrently with other medicinal and/or health products, please consult a physician before use.$SQLTXT$, $SQLTXT$Contra-Indications: If you are pregnant or breastfeeding, do not use this product.$SQLTXT$]::text[], translations = jsonb_set(coalesce(translations, '{}'::jsonb), '{fr}', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('contraindications', $SQLTXT$["Contre-indications : Ne pas utiliser ce produit si vous êtes enceinte ou allaitez.", "Mises en garde et précautions : Ne pas utiliser si vous êtes enceinte ou allaitez. Les personnes présentant des symptômes grippaux, particulièrement avec de la fièvre, devraient éviter de consommer ce produit. Si ce produit est utilisé en même temps que d'autres produits médicinaux et/ou de santé, veuillez consulter un médecin avant l'utilisation.", "Contre-indications : Si vous êtes enceinte ou allaitez, ne pas utiliser ce produit."]$SQLTXT$::jsonb)) WHERE slug = $SQLTXT$kadsura-coccinea$SQLTXT$;
UPDATE public.herbs SET contraindications = ARRAY[$SQLTXT$Known Adverse Reactions: Rare, unpredictable cases of liver injury associated with green tea extract-containing products have been reported (in Canada and internationally).$SQLTXT$, $SQLTXT$Contra-Indications: Stop use and consult a healthcare practitioner if symptoms of digestive upset (eg. diarrhea) occur, worsen or persist beyond 3 days. Do not use this product if you have an immune compromised condition (e.g. AIDS, lymphoma, patients undergoing long-term corticosteriod treatment).$SQLTXT$, $SQLTXT$Known Adverse Reactions: May cause mild gastro-intestinal discomfort (such as gas, bloating, cramps). Stop use if hypersensitivity/allergy occurs.$SQLTXT$, $SQLTXT$Contra-Indications: If you have a milk allergy, do not use this product.$SQLTXT$, $SQLTXT$Known Adverse Reactions: Do not take if you have a known allergy or sensitivity to kiwifruit. If hypersensitivity occurs, discontinue use.$SQLTXT$, $SQLTXT$Contra-Indications: Do not use if you have an immune-compromised condition (e.g. AIDS, lymphoma, patients undergoing long-term corticosteroid treatment). Do not use this product if you are taking Tetracycline.$SQLTXT$]::text[], translations = jsonb_set(coalesce(translations, '{}'::jsonb), '{fr}', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('contraindications', $SQLTXT$["Réactions indésirables connues : De rares cas imprévisibles de lésions hépatiques associés à des produits contenant de l'extrait de thé vert ont été signalés (au Canada et à l'international).", "Contre-indications : Cessez l'utilisation et consultez un praticien de soins de santé si des symptômes de troubles digestifs (p. ex. diarrhée) surviennent, s'aggravent ou persistent au-delà de 3 jours. Ne pas utiliser ce produit si vous avez un état immunodéprimé (p. ex. SIDA, lymphome, patients sous traitement corticostéroïdien à long terme).", "Réactions indésirables connues : Peut causer un léger inconfort gastro-intestinal (comme des gaz, des ballonnements, des crampes). Cessez l'utilisation si une hypersensibilité/allergie survient.", "Contre-indications : Si vous avez une allergie au lait, ne pas utiliser ce produit.", "Réactions indésirables connues : Ne pas prendre si vous avez une allergie ou une sensibilité connue au kiwi. Si une hypersensibilité survient, cessez l'utilisation.", "Contre-indications : Ne pas utiliser si vous avez un état immunodéprimé (p. ex. SIDA, lymphome, patients sous traitement corticostéroïdien à long terme). Ne pas utiliser ce produit si vous prenez de la tétracycline."]$SQLTXT$::jsonb)) WHERE slug = $SQLTXT$actinidia-deliciosa$SQLTXT$;
UPDATE public.herbs SET contraindications = ARRAY[$SQLTXT$Contra-Indications: Do not use if pregnant or breastfeeding. Do not exceed recommended dose. Do not use if you are trying to conceive. Do not use if you have diabetes or hypoglycaemia.$SQLTXT$]::text[], translations = jsonb_set(coalesce(translations, '{}'::jsonb), '{fr}', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('contraindications', $SQLTXT$["Contre-indications : Ne pas utiliser si vous êtes enceinte ou si vous allaitez. Ne pas dépasser la dose recommandée. Ne pas utiliser si vous tentez de concevoir. Ne pas utiliser si vous avez le diabète ou une hypoglycémie."]$SQLTXT$::jsonb)) WHERE slug = $SQLTXT$erythroxylum-catuaba$SQLTXT$;
UPDATE public.herbs SET contraindications = ARRAY[$SQLTXT$Contra-Indications: Do not use if you are taking thiazide diuretics, cardiac glycosides, corticosteroids, stimulant laxatives or other medications which may aggravate electrolyte imbalance or if you have hypokalemia, high blood pressure, or a kidney or cardiovascular disorder.$SQLTXT$, $SQLTXT$Known Adverse Reactions: Some people may experience hypersensitivity/allergy, insomnia, anxiety, or headaches, in which case, discontinue use.$SQLTXT$, $SQLTXT$Contra-Indications: Do no use if you are pregnant or breastfeeding or if you are hypersensitive to caffeine or tannins.$SQLTXT$]::text[], translations = jsonb_set(coalesce(translations, '{}'::jsonb), '{fr}', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('contraindications', $SQLTXT$["Contre-indications : Ne pas utiliser si vous prenez des diurétiques thiazidiques, des glycosides cardiaques, des corticoïdes, des laxatifs stimulants ou d'autres médicaments susceptibles d'aggraver un déséquilibre électrolytique, ou si vous avez une hypokaliémie, une hypertension artérielle ou un trouble rénal ou cardiovasculaire.", "Réactions indésirables connues : certaines personnes peuvent ressentir une hypersensibilité/allergie, de l'insomnie, de l'anxiété ou des maux de tête ; dans ce cas, cessez l'utilisation.", "Contre-indications : Ne pas utiliser si vous êtes enceinte ou si vous allaitez, ou si vous êtes hypersensible à la caféine ou aux tanins."]$SQLTXT$::jsonb)) WHERE slug = $SQLTXT$atractylodes-chinensis$SQLTXT$;
UPDATE public.herbs SET contraindications = ARRAY[$SQLTXT$Contra-Indications: If you are pregnant/breastfeeding, do not use this product.$SQLTXT$, $SQLTXT$Contra-Indications: Do not use this product if you are pregnant or breastfeeding.$SQLTXT$, $SQLTXT$Contra-Indications: Do not use if you are pregnant or breastfeeding. Do not use if you are taking heart medications, corticosteroids, stimulant laxatives, or other health products that may contribute electrolyte imbalance.$SQLTXT$]::text[], translations = jsonb_set(coalesce(translations, '{}'::jsonb), '{fr}', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('contraindications', $SQLTXT$["Contre-indications : Si vous êtes enceinte/allaitante, ne pas utiliser ce produit.", "Contre-indications : Ne pas utiliser ce produit si vous êtes enceinte ou allaitez.", "Contre-indications : Ne pas utiliser si vous êtes enceinte ou allaitez. Ne pas utiliser si vous prenez des médicaments cardiaques, des corticostéroïdes, des laxatifs stimulants ou d'autres produits de santé susceptibles de contribuer à un déséquilibre électrolytique."]$SQLTXT$::jsonb)) WHERE slug = $SQLTXT$iris-domestica$SQLTXT$;
UPDATE public.herbs SET contraindications = ARRAY[$SQLTXT$Known Adverse Reactions: Hypersensitivity, such as an allergy, has been known to occur; in which case, discontinue use. Some people may experience insomnia, anxiety, or headaches, in which case, discontinue use.$SQLTXT$, $SQLTXT$Contra-Indications: If you are pregnant or breastfeeding, do not use this product. Contraindicated for those with yin deficiency, yin deficiency with heat, or qi stagnation characterized by feelings of distension and oppression.$SQLTXT$, $SQLTXT$Known Adverse Reactions: Diuretic effect may occur. Stop use if hypersensitivity/allergy occurs.$SQLTXT$, $SQLTXT$Contra-Indications: Do not use this product if you are taking thiazide diuretics, cardiac glycosides, corticosteroids, stimulant laxatives or other medications which may aggravate electrolyte imbalance.$SQLTXT$]::text[], translations = jsonb_set(coalesce(translations, '{}'::jsonb), '{fr}', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('contraindications', $SQLTXT$["Réactions indésirables connues : Une hypersensibilité, telle qu'une allergie, a été signalée ; dans ce cas, cesser l'utilisation. Certaines personnes peuvent éprouver de l'insomnie, de l'anxiété ou des maux de tête ; dans ce cas, cesser l'utilisation.", "Contre-indications : Si vous êtes enceinte ou si vous allaitez, ne pas utiliser ce produit. Contre-indiqué chez les personnes présentant une insuffisance de yin, une insuffisance de yin avec chaleur, ou une stagnation du qi caractérisée par des sensations de distension et d'oppression.", "Réactions indésirables connues : Un effet diurétique peut survenir. Cesser l'utilisation si une hypersensibilité/allergie survient.", "Contre-indications : Ne pas utiliser ce produit si vous prenez des diurétiques thiazidiques, des glycosides cardiotoniques, des corticostéroïdes, des laxatifs stimulants ou d'autres médicaments susceptibles d'aggraver un déséquilibre électrolytique."]$SQLTXT$::jsonb)) WHERE slug = $SQLTXT$plantago-depressa$SQLTXT$;
UPDATE public.herbs SET contraindications = ARRAY[$SQLTXT$Contra-Indications: Do not use this product if you are pregnant or breastfeeding. Do not use this product if you are taking thiazide diuretics, cardiac glycosides, corticosteroids, stimulant laxatives or other medications which may aggravate electrolyte imbalance.$SQLTXT$, $SQLTXT$Contra-Indications: If you are pregnant or breastfeeding, do not use this product. Do not use this product if you have hypermenorrhea/profuse menstrual flow/heavy periods.$SQLTXT$]::text[], translations = jsonb_set(coalesce(translations, '{}'::jsonb), '{fr}', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('contraindications', $SQLTXT$["Contre-indications : N'utilisez pas ce produit si vous êtes enceinte ou si vous allaitez. N'utilisez pas ce produit si vous prenez des diurétiques thiazidiques, des glycosides cardiotoniques, des corticostéroïdes, des laxatifs stimulants ou d'autres médicaments susceptibles d'aggraver un déséquilibre électrolytique.", "Contre-indications : Si vous êtes enceinte ou si vous allaitez, n'utilisez pas ce produit. N'utilisez pas ce produit si vous avez une hyperménorrhée/un flux menstruel abondant/des règles abondantes."]$SQLTXT$::jsonb)) WHERE slug = $SQLTXT$persicaria-tinctoria$SQLTXT$;
UPDATE public.herbs SET contraindications = ARRAY[$SQLTXT$Contra-Indications: Do not use if you are pregnant or breastfeeding. Do not use if you have diarrhea, hemorrhagic diseases or heavy periods.$SQLTXT$]::text[], translations = jsonb_set(coalesce(translations, '{}'::jsonb), '{fr}', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('contraindications', $SQLTXT$["Contre-indications : Ne pas utiliser si vous êtes enceinte ou si vous allaitez. Ne pas utiliser en cas de diarrhée, de maladies hémorragiques ou de règles abondantes."]$SQLTXT$::jsonb)) WHERE slug = $SQLTXT$paeonia-obovata$SQLTXT$;
UPDATE public.herbs SET contraindications = ARRAY[$SQLTXT$Known Adverse Reactions: Hypersensitivity (e.g. allergy) has been known to occur; in which case, discontinue use.$SQLTXT$, $SQLTXT$Contra-Indications: Do not use if you are pregnant or breastfeeding.$SQLTXT$, $SQLTXT$Cautions and Warnings: People sensitive to nicotinic acid may experience flushing of the skin that is generally mild and transient. Do not use if you are pregnant or breastfeeding.$SQLTXT$, $SQLTXT$Contra-Indications: Do not use if you are taking health products that affect blood coagulation (e.g. blood thinners, clotting factor replacements, acetylsalicylic acid, ibuprofen, fish oils, vitamin E) as this may increase the risk of spontaneous bleeding.$SQLTXT$]::text[], translations = jsonb_set(coalesce(translations, '{}'::jsonb), '{fr}', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('contraindications', $SQLTXT$["Effets indésirables connus : Des cas d'hypersensibilité (p. ex. allergie) ont été signalés ; le cas échéant, cesser l'utilisation.", "Contre-indications : Ne pas utiliser si vous êtes enceinte ou si vous allaitez.", "Mises en garde et précautions : Les personnes sensibles à l'acide nicotinique peuvent présenter une rougeur cutanée généralement légère et transitoire. Ne pas utiliser si vous êtes enceinte ou si vous allaitez.", "Contre-indications : Ne pas utiliser si vous prenez des produits de santé qui influent sur la coagulation sanguine (p. ex. anticoagulants, facteurs de coagulation de remplacement, acide acétylsalicylique, ibuprofène, huiles de poisson, vitamine E), car cela pourrait augmenter le risque de saignement spontané."]$SQLTXT$::jsonb)) WHERE slug = $SQLTXT$fallopia-japonica$SQLTXT$;
UPDATE public.herbs SET contraindications = ARRAY[$SQLTXT$Known Adverse Reactions: May cause digestive problems. Stop use if hypersensitivity occurs. Some people may experience drowsiness. Exercise caution if operating heavy machinery, driving a motor vehicle or involved in activities requiring mental alertness.$SQLTXT$, $SQLTXT$Contra-Indications: If you are pregnant or breastfeeding, do not use this product.Do not use if you have diarrhoea.Do not use if you have kidney or heart disorder, are taking any diuretics or any medications that may affect electrolyte balance.$SQLTXT$]::text[], translations = jsonb_set(coalesce(translations, '{}'::jsonb), '{fr}', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('contraindications', $SQLTXT$["Précautions et mises en garde : Consultez un praticien de la santé si les symptômes persistent ou s'aggravent. Consultez un praticien de la santé avant l'usage si vous êtes enceinte ou si vous allaitez.", "Réactions indésirables connues : Peut causer des problèmes digestifs. Cesser l'utilisation en cas d'hypersensibilité. Certaines personnes peuvent ressentir de la somnolence. Faire preuve de prudence avant de conduire un véhicule, d'utiliser de la machinerie lourde ou d'exercer des activités exigeant de la vigilance. Cesser l'utilisation en cas d'effet laxatif.", "Contre-indications : Si vous êtes enceinte ou si vous allaitez, ne pas utiliser ce produit. Ne pas utiliser en cas de diarrhée. Ne pas utiliser si vous avez un trouble rénal ou cardiaque, si vous prenez des diurétiques ou tout médicament susceptible d'affecter l'équilibre électrolytique."]$SQLTXT$::jsonb)) WHERE slug = $SQLTXT$saraca-indica$SQLTXT$;
UPDATE public.herbs SET contraindications = ARRAY[$SQLTXT$Contra-Indications: If you are pregnant or breastfeeding, do not use this product.$SQLTXT$, $SQLTXT$Contra-Indications: Do not use if you are pregnant of breastfeeding. Discontinue use if allergy such as itches or rash develops. Do not apply to open wound. Avoid contact with the eyes and mucous membranes. Do not tightly bandage.$SQLTXT$, $SQLTXT$Contra-Indications: If you are pregnant or breast-feeding, do not use this product.$SQLTXT$]::text[], translations = jsonb_set(coalesce(translations, '{}'::jsonb), '{fr}', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('contraindications', $SQLTXT$["Contre-indications : Si vous êtes enceinte ou allaitez, n'utilisez pas ce produit.", "Contre-indications : N'utilisez pas si vous êtes enceinte ou allaitez. Cessez l'utilisation si une allergie telle que des démangeaisons ou une éruption cutanée se développe. N'appliquez pas sur une plaie ouverte. Évitez le contact avec les yeux et les muqueuses. Ne bandez pas serré."]$SQLTXT$::jsonb)) WHERE slug = $SQLTXT$flemingia-philippinensis$SQLTXT$;
UPDATE public.herbs SET contraindications = ARRAY[$SQLTXT$Contra-Indications: If you are pregnant or breastfeeding, do not use this product. If you have distension and fullness of the chest and abdomen, vomiting from overabundant dampness, edema, hypertension, hypokalemia or congestive heart failure; do not use this product.$SQLTXT$, $SQLTXT$Known Adverse Reactions: Hypersensitivity, such as an allergy, has been known to occur; in which case, discontinue use.$SQLTXT$, $SQLTXT$Contra-Indications: Do not use if you are pregnant or breastfeeding.$SQLTXT$, $SQLTXT$Known Adverse Reactions: No Reports Known.$SQLTXT$, $SQLTXT$Contra-Indications: If you are pregnant or breastfeeding, do not use this product.$SQLTXT$]::text[], translations = jsonb_set(coalesce(translations, '{}'::jsonb), '{fr}', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('contraindications', $SQLTXT$["Contre-indications : Si vous êtes enceinte ou si vous allaitez, ne pas utiliser ce produit. Si vous avez une distension et une plénitude de la poitrine et de l'abdomen, des vomissements dus à une humidité surabondante, un œdème, une hypertension, une hypokaliémie ou une insuffisance cardiaque congestive ; ne pas utiliser ce produit.", "Réactions indésirables connues : Une hypersensibilité, telle qu'une allergie, a été signalée ; le cas échéant, cesser l'utilisation.", "Contre-indications : Ne pas utiliser si vous êtes enceinte ou si vous allaitez.", "Réactions indésirables connues : Aucun rapport connu.", "Contre-indications : Si vous êtes enceinte ou si vous allaitez, ne pas utiliser ce produit."]$SQLTXT$::jsonb)) WHERE slug = $SQLTXT$hansenia-weberbaueriana$SQLTXT$;
UPDATE public.herbs SET contraindications = ARRAY[$SQLTXT$Contra-Indications: Do not use if you are pregnant or breastfeeding.$SQLTXT$, $SQLTXT$Known Adverse Reactions: Some people may experience diarrhoea, mild gastrointestinal bloating, constipation or indigestion. Hypersensitivity, such as allergy, has been known to occur; in which case, discontinue use.$SQLTXT$, $SQLTXT$Known Adverse Reactions: Hypersensitivity, such as allergy, is known, in which case, discontinue use. May cause abdominal pain, cramps, spasms and/or diarrhea, in which case; discontinue use.$SQLTXT$, $SQLTXT$Cautions and Warnings: Keep out of the reach of children. There is enough Iron in this product to seriously harm a child. Consult a healthcare practitioner prior to use if you are taking sulfonamides.$SQLTXT$]::text[], translations = jsonb_set(coalesce(translations, '{}'::jsonb), '{fr}', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('contraindications', $SQLTXT$["Contre-indications : Ne pas utiliser si vous êtes enceinte ou si vous allaitez.", "Effets indésirables connus : Certaines personnes peuvent éprouver de la diarrhée, un léger ballonnement gastro-intestinal, de la constipation ou de l'indigestion. Une hypersensibilité, telle qu'une allergie, a été signalée ; dans ce cas, cesser l'utilisation.", "Effets indésirables connus : Une hypersensibilité, telle qu'une allergie, est connue ; dans ce cas, cesser l'utilisation. Peut causer des douleurs abdominales, des crampes, des spasmes et/ou de la diarrhée ; dans ce cas, cesser l'utilisation.", "Mises en garde et avertissements : Garder hors de la portée des enfants. Ce produit contient suffisamment de fer pour nuire gravement à un enfant. Consulter un praticien de la santé avant l'usage si vous prenez des sulfamides."]$SQLTXT$::jsonb)) WHERE slug = $SQLTXT$camellia-sinensis-l-kuntze$SQLTXT$;
UPDATE public.herbs SET contraindications = ARRAY[$SQLTXT$Known Adverse Reactions: Diuretic effect may occur. Stop use if hypersensitivity/allergy occurs. Stop use and seek medical attention immediately if you experience dizziness, confusion, muscle weakness or pain, abnormal heart beat and/or difficulty breathing.$SQLTXT$, $SQLTXT$Contra-Indications: Do not use this product if you have heart disease, high or low blood pressure, kidney or liver disorder, diabetes or edema (swelling of hands, face and feet) or are taking products containing diuretics.$SQLTXT$, $SQLTXT$Known Adverse Reactions: Stop use if hypersensitivity/allergy occur.$SQLTXT$, $SQLTXT$Contra-Indications: Do not use this product if you are pregnant or breastfeeding, or have an immune-compromised condition (e.g. AIDS, lymphoma, patients undergoing long-term corticosteroid treatment).$SQLTXT$, $SQLTXT$Contra-Indications: Do not use this product if you are pregnant or breastfeeding or have an immune-compromised condition (e.g. AIDS, lymphoma, patients undergoing long-term corticosteroid treatment).$SQLTXT$]::text[], translations = jsonb_set(coalesce(translations, '{}'::jsonb), '{fr}', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('contraindications', $SQLTXT$["Réactions indésirables connues : Un effet diurétique peut survenir. Cesser l'utilisation en cas d'hypersensibilité/allergie. Cesser l'utilisation et consulter immédiatement un médecin si vous éprouvez des étourdissements, de la confusion, une faiblesse ou des douleurs musculaires, un rythme cardiaque anormal et/ou des difficultés respiratoires.", "Contre-indications : Ne pas utiliser ce produit si vous avez une maladie cardiaque, une tension artérielle élevée ou basse, un trouble rénal ou hépatique, le diabète ou de l'œdème (enflure des mains, du visage et des pieds) ou si vous prenez des produits contenant des diurétiques.", "Réactions indésirables connues : Cesser l'utilisation en cas d'hypersensibilité/allergie.", "Contre-indications : Ne pas utiliser ce produit si vous êtes enceinte ou allaitez, ou si vous avez un état immunodéprimé (p. ex. SIDA, lymphome, patients sous traitement corticostéroïdien à long terme).", "Contre-indications : Ne pas utiliser ce produit si vous êtes enceinte ou allaitez ou si vous avez un état immunodéprimé (p. ex. SIDA, lymphome, patients sous traitement corticostéroïdien à long terme)."]$SQLTXT$::jsonb)) WHERE slug = $SQLTXT$auxenochlorella-pyrenoidosa$SQLTXT$;
UPDATE public.herbs SET contraindications = ARRAY[$SQLTXT$Known Adverse Reactions: Some people may experience drowsiness. Exercise caution if operating heavy machinery, driving a motor vehicle or involved in activities requiring mental alertness. Diuretic effect may occur. Stop use if hypersensitivity/allergy occurs.$SQLTXT$, $SQLTXT$Contra-Indications: Do not use this product if you are pregnant or have a kidney disorder.$SQLTXT$, $SQLTXT$Contra-Indications: Do not use this product if you are taking thiazide diuretics, cardiac glycosides, corticosteroids, stimulant laxatives or other medications which may aggravate electrolyte imbalance.$SQLTXT$, $SQLTXT$Contra-Indications: Do not use if pregnant or breastfeeding.$SQLTXT$, $SQLTXT$Known Adverse Reactions: Discontinue use if gastrointestinal discomfort, headache and/or skin rash appear.$SQLTXT$]::text[], translations = jsonb_set(coalesce(translations, '{}'::jsonb), '{fr}', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('contraindications', $SQLTXT$["Réactions indésirables connues : Certaines personnes peuvent ressentir de la somnolence. Faire preuve de prudence si vous conduisez un véhicule motorisé, utilisez de la machinerie lourde ou participez à des activités nécessitant de la vigilance mentale. Un effet diurétique peut se produire. Cesser l'utilisation en cas d'hypersensibilité/allergie.", "Contre-indications : Ne pas utiliser ce produit si vous êtes enceinte ou si vous avez un trouble rénal.", "Contre-indications : Ne pas utiliser ce produit si vous prenez des diurétiques thiazidiques, des glycosides cardiotoniques, des corticostéroïdes, des laxatifs stimulants ou d'autres médicaments susceptibles d'aggraver un déséquilibre électrolytique.", "Contre-indications : Ne pas utiliser si vous êtes enceinte ou si vous allaitez.", "Réactions indésirables connues : Cesser l'utilisation en cas d'inconfort gastro-intestinal, de céphalées et/ou d'éruption cutanée."]$SQLTXT$::jsonb)) WHERE slug = $SQLTXT$pluchea-lanceolata$SQLTXT$;
UPDATE public.herbs SET contraindications = ARRAY[$SQLTXT$Known Adverse Reactions: Stop use if hypersensitivity/allergy occurs. Diuretic effect may occur.$SQLTXT$, $SQLTXT$Contra-Indications: If you are pregnant or breastfeeding, do not use this product.$SQLTXT$, $SQLTXT$Contra-Indications: Do not use if you are allergic to bees or bee products.$SQLTXT$, $SQLTXT$Known Adverse Reactions: Some people may experience insomnia, anxiety, or headaches, in which case, discontinue use.$SQLTXT$, $SQLTXT$Contra-Indications: Do not use if you are pregnant or breastfeeding.$SQLTXT$]::text[], translations = jsonb_set(coalesce(translations, '{}'::jsonb), '{fr}', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('contraindications', $SQLTXT$["Effets indésirables connus : Cessez l'utilisation en cas d'hypersensibilité/allergie. Un effet diurétique peut survenir.", "Contre-indications : Si vous êtes enceinte ou allaitez, n'utilisez pas ce produit.", "Contre-indications : N'utilisez pas si vous êtes allergique aux abeilles ou aux produits de la ruche.", "Effets indésirables connus : Certaines personnes peuvent éprouver de l'insomnie, de l'anxiété ou des céphalées ; le cas échéant, cessez l'utilisation.", "Contre-indications : N'utilisez pas si vous êtes enceinte ou allaitez. N'utilisez pas si vous prenez des diurétiques thiazidiques, des glycosides cardiotoniques, des corticostéroïdes, des laxatifs stimulants ou d'autres médicaments susceptibles d'aggraver un déséquilibre électrolytique, des anticoagulants ou des fluidifiants sanguins tels que la warfarine ou le ticlopidine.", "Contre-indications : N'utilisez pas si vous êtes enceinte ou allaitez."]$SQLTXT$::jsonb)) WHERE slug = $SQLTXT$senna-tora$SQLTXT$;
UPDATE public.herbs SET contraindications = ARRAY[$SQLTXT$Contra-Indications: Do not use if you are pregnant or breastfeeding. Do not use if you or your partner are attempting to conceive. Do not use if you have an immune-compromised condition (e.g. AIDS, lymphoma, patients undergoing long-term corticosteroid treatment).$SQLTXT$, $SQLTXT$Contra-Indications: Do not use if you are pregnant or breastfeeding. Do not use if you have an immune-compromised condition (e.g. AIDS, lymphoma, patients undergoing long-term corticosteroid treatment). Do not use if you are pregnant or if you or your partner are attempting to conceive.$SQLTXT$, $SQLTXT$Contra-Indications: Do not use if you are pregnant or breastfeeding.$SQLTXT$, $SQLTXT$Known Adverse Reactions: Hypersensitivity, such as an allergy, has been known to occur in rare cases; in which case, discontinue use. Rare, unpredictable cases of liver injury associated with green tea extract-containing products have been reported (in Canada and internationally).$SQLTXT$]::text[], translations = jsonb_set(coalesce(translations, '{}'::jsonb), '{fr}', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('contraindications', $SQLTXT$["Contre-indications : Ne pas utiliser si vous êtes enceinte ou si vous allaitez. Ne pas utiliser si vous ou votre partenaire tentez de concevoir. Ne pas utiliser si vous avez un état immunodéprimé (p. ex. SIDA, lymphome, patients sous traitement corticostéroïdien à long terme).", "Contre-indications : Ne pas utiliser si vous êtes enceinte ou si vous allaitez. Ne pas utiliser si vous avez un état immunodéprimé (p. ex. SIDA, lymphome, patients sous traitement corticostéroïdien à long terme). Ne pas utiliser si vous êtes enceinte ou si vous ou votre partenaire tentez de concevoir.", "Contre-indications : Ne pas utiliser si vous êtes enceinte ou si vous allaitez.", "Réactions indésirables connues : Une hypersensibilité, telle qu'une allergie, a été signalée dans de rares cas ; dans ce cas, cesser l'utilisation. De rares cas imprévisibles de lésions hépatiques associés à des produits contenant de l'extrait de thé vert ont été signalés (au Canada et à l'international)."]$SQLTXT$::jsonb)) WHERE slug = $SQLTXT$amaranthus-cruentus$SQLTXT$;
UPDATE public.herbs SET contraindications = ARRAY[$SQLTXT$Contra-Indications: Do not use if you are pregnant or breastfeeding. Do not use if you are taking heart medications, corticosteroids, stimulant laxatives, or other health products that may contribute electrolyte imbalance.$SQLTXT$, $SQLTXT$Contra-Indications: Do not use if you are taking thiazide diuretics, cardiac glycosides, corticosteroids, stimulant laxatives or other medications which may aggravate electrolyte imbalance or if you are pregnant or breastfeeding, have hypokalemia, high blood pressure, or a kidney, liver.$SQLTXT$, $SQLTXT$Known Adverse Reactions: Stop use if hypersensitivity/allergy occurs.$SQLTXT$, $SQLTXT$Contra-Indications: Do not use this product if you are pregnant or breastfeeding. Do not use this product if you are taking thiazide diuretics, cardiac glycosides, corticosteroids, stimulant laxatives or other medications which may aggravate electrolyte imbalance.$SQLTXT$]::text[], translations = jsonb_set(coalesce(translations, '{}'::jsonb), '{fr}', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('contraindications', $SQLTXT$["Contre-indications : N'utilisez pas si vous êtes enceinte ou allaitez. N'utilisez pas si vous prenez des médicaments cardiaques, des corticostéroïdes, des laxatifs stimulants ou d'autres produits de santé susceptibles de contribuer à un déséquilibre électrolytique.", "Contre-indications : N'utilisez pas si vous prenez des diurétiques thiazidiques, des glycosides cardiotoniques, des corticostéroïdes, des laxatifs stimulants ou d'autres médicaments susceptibles d'aggraver un déséquilibre électrolytique, ou si vous êtes enceinte ou allaitez, avez une hypokaliémie, une hypertension artérielle ou un problème rénal.", "Réactions indésirables connues : Cessez l'utilisation en cas d'hypersensibilité ou d'allergie.", "Contre-indications : N'utilisez pas ce produit si vous êtes enceinte ou allaitez. N'utilisez pas ce produit si vous prenez des diurétiques thiazidiques, des glycosides cardiotoniques, des corticostéroïdes, des laxatifs stimulants ou d'autres médicaments susceptibles d'aggraver un déséquilibre électrolytique."]$SQLTXT$::jsonb)) WHERE slug = $SQLTXT$paris-polyphylla$SQLTXT$;
UPDATE public.herbs SET contraindications = ARRAY[$SQLTXT$Contra-Indications: If you are pregnant or breastfeeding, do not use this product. If you have broken, irritated, or sensitive skin, do not use this product.$SQLTXT$, $SQLTXT$Known Adverse Reactions: If you experience nausea, dizziness, headache or an allergic reaction, discontinue use.$SQLTXT$, $SQLTXT$Known Adverse Reactions: Some people may experience headaches. Stop use if hypersensitivity/allergy occurs.$SQLTXT$, $SQLTXT$Contra-Indications: Do not use this product if you have heart disease, high or low blood pressure, kidney or liver disorder, diabetes or edema (swelling of hands, face and feet) or are taking products containing diuretics. Do not use this product if you are pregnant or breastfeeding.$SQLTXT$, $SQLTXT$Known Adverse Reactions: Stop use if hypersensitivity/allergy occurs.$SQLTXT$, $SQLTXT$Contra-Indications: Do not use if you are taking health products that affect blood coagulation (e.g. blood thinners, clotting factor replacements, acetylsalicylic acid, ibuprofen, fish oils, vitamin E) as this may increase the risk of spontaneous bleeding.$SQLTXT$]::text[], translations = jsonb_set(coalesce(translations, '{}'::jsonb), '{fr}', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('contraindications', $SQLTXT$["Contre-indications : Si vous êtes enceinte ou si vous allaitez, n'utilisez pas ce produit. Si vous avez la peau lésée, irritée ou sensible, n'utilisez pas ce produit.", "Réactions indésirables connues : Si vous éprouvez des nausées, des étourdissements, des maux de tête ou une réaction allergique, cessez l'utilisation.", "Réactions indésirables connues : Certaines personnes peuvent éprouver des maux de tête. Cessez l'utilisation en cas d'hypersensibilité ou d'allergie.", "Contre-indications : N'utilisez pas ce produit si vous avez une maladie cardiaque, une pression artérielle élevée ou basse, un trouble rénal ou hépatique, le diabète ou de l'œdème (gonflement des mains, du visage et des pieds) ou si vous prenez des produits contenant des diurétiques. N'utilisez pas ce produit si vous êtes enceinte ou si vous allaitez.", "Réactions indésirables connues : Cessez l'utilisation en cas d'hypersensibilité ou d'allergie.", "Contre-indications : Ne pas utiliser si vous prenez des produits de santé qui affectent la coagulation sanguine (p. ex. anticoagulants, facteurs de coagulation de remplacement, acide acétylsalicylique, ibuprofène, huiles de poisson, vitamine E), car cela pourrait augmenter le risque de saignement spontané."]$SQLTXT$::jsonb)) WHERE slug = $SQLTXT$citrus-sinensis$SQLTXT$;
UPDATE public.herbs SET contraindications = ARRAY[$SQLTXT$Contra-Indications: Do not use if you are allergic to plants of the Asteraceae/Compositae/Daisy family. Do not use if you have a bile duct obstruction.$SQLTXT$, $SQLTXT$Known Adverse Reactions: Hypersensitivity, such as allergy, has been known to occur; in which case, discontinue use. In rare cases, some people may experience a (skin) rash. Allergic reactions can occur in people allergic to plants of the Oleacea family.$SQLTXT$]::text[], translations = jsonb_set(coalesce(translations, '{}'::jsonb), '{fr}', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('contraindications', $SQLTXT$["Contre-indications : Ne pas utiliser si vous êtes allergique aux plantes de la famille des Asteraceae/Compositae/marguerites. Ne pas utiliser en cas d'obstruction des voies biliaires.", "Effets indésirables connus : Une hypersensibilité, telle qu'une allergie, a été signalée ; dans ce cas, cessez l'utilisation. Dans de rares cas, certaines personnes peuvent présenter une éruption (cutanée). Des réactions allergiques peuvent survenir chez les personnes allergiques aux plantes de la famille des Oleaceae.", "Effets indésirables connus : Certaines personnes pourraient ressentir de la somnolence. Faire preuve de prudence si vous conduisez de la machinerie lourde ou tout autre véhicule motorisé, ou si vous devez entreprendre des activités qui requièrent de la vigilance."]$SQLTXT$::jsonb)) WHERE slug = $SQLTXT$conyza-canadensis$SQLTXT$;
UPDATE public.herbs SET contraindications = ARRAY[$SQLTXT$Known Adverse Reactions: Consumption with alcohol, other medications and/or natural health products with sedative properties is not recommended. Hypersensitivity (e.g. allergy) has been known to occur; in which case, discontinue use. Some people may experience drowsiness.$SQLTXT$, $SQLTXT$Contra-Indications: Do not use if you are pregnant or breastfeeding. Do not use if you have gastrointestinal ulcers and/or inflammation.$SQLTXT$]::text[], translations = jsonb_set(coalesce(translations, '{}'::jsonb), '{fr}', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('contraindications', $SQLTXT$["Mises en garde et avertissements : Ne pas utiliser si vous êtes enceinte. Consultez un praticien de soins de santé avant d'en faire l'usage si vous souffrez de troubles du foie, ou si des symptômes de troubles du foie se manifestent.", "Réactions indésirables connues : La consommation avec de l'alcool, d'autres médicaments et/ou des produits de santé naturels aux propriétés sédatives n'est pas recommandée. Une hypersensibilité (p. ex. allergie) a été signalée ; le cas échéant, cessez l'utilisation. Certaines personnes peuvent ressentir de la somnolence.", "Contre-indications : Ne pas utiliser si vous êtes enceinte ou si vous allaitez. Ne pas utiliser si vous avez des ulcères et/ou une inflammation gastro-intestinaux."]$SQLTXT$::jsonb)) WHERE slug = $SQLTXT$lithothamnium-calcareum$SQLTXT$;
UPDATE public.herbs SET contraindications = ARRAY[$SQLTXT$Contra-Indications: According to Traditional Chinese Medicine, do not use this product in cases of exterior excess, qi stagnation, damp obstruction, food stagnation, yin deficiency with heat signs, or skin lesions in their early stages or where there is a heat toxin.$SQLTXT$, $SQLTXT$Known Adverse Reactions: Diuretic effect may occur. Stop use if hypersensitivity/allergy occurs. Laxative may occur. Discontinue use if experience abdominal pain, cramps, spasms, or diarrhoea.$SQLTXT$, $SQLTXT$Contra-Indications: If you are pregnant or breastfeeding, do not use this product.$SQLTXT$, $SQLTXT$Contra-Indications: Do not use if pregnant or breastfeeding. Do not use if you have severe diarrhea or damp heat dysenteric disorders.$SQLTXT$]::text[], translations = jsonb_set(coalesce(translations, '{}'::jsonb), '{fr}', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('contraindications', $SQLTXT$["Contre-indications : Selon la médecine traditionnelle chinoise, ne pas utiliser ce produit en cas d'excès externe, de stagnation du qi, d'obstruction par l'humidité, de stagnation alimentaire, de vide de yin avec signes de chaleur, ou de lésions cutanées à leurs stades précoces ou en présence d'une toxine de chaleur.", "Effets indésirables connus : Un effet diurétique peut survenir. Cesser l'utilisation en cas d'hypersensibilité/allergie. Un effet laxatif peut survenir. Cesser l'utilisation en cas de douleurs abdominales, de crampes, de spasmes ou de diarrhée.", "Contre-indications : Si vous êtes enceinte ou allaitante, ne pas utiliser ce produit.", "Contre-indications : Ne pas utiliser en cas de grossesse ou d'allaitement. Ne pas utiliser en cas de diarrhée sévère ou de troubles dysentériques de type damp-heat."]$SQLTXT$::jsonb)) WHERE slug = $SQLTXT$zanthoxylum-schinifolium$SQLTXT$;
UPDATE public.herbs SET contraindications = ARRAY[$SQLTXT$Contra-Indications: Do not use if you have high blood pressure. If you have bipolar disorder or bipolar spectrum disorder, do not use this product. Do not use if you are pregnant or breastfeeding. Do not use if you have a history of systemic lupus erythematosus.$SQLTXT$, $SQLTXT$Known Adverse Reactions: If you experience irritability or insomnia, discontinue use.$SQLTXT$, $SQLTXT$Known Adverse Reactions: Diuretic effect may occur.$SQLTXT$, $SQLTXT$Contra-Indications: Do not use this product if you have high blood pressure. Do not use this product if you are pregnant, breastfeeding or have a history of systemic lupus erythematosus.$SQLTXT$]::text[], translations = jsonb_set(coalesce(translations, '{}'::jsonb), '{fr}', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('contraindications', $SQLTXT$["Contre-indications : N'utilisez pas si vous avez une pression artérielle élevée. Si vous avez un trouble bipolaire ou un trouble du spectre bipolaire, n'utilisez pas ce produit. N'utilisez pas si vous êtes enceinte ou si vous allaitez. N'utilisez pas si vous avez des antécédents de lupus érythémateux disséminé.", "Réactions indésirables connues : Si vous présentez de l'irritabilité ou de l'insomnie, cessez l'utilisation.", "Réactions indésirables connues : Un effet diurétique peut survenir.", "Contre-indications : N'utilisez pas ce produit si vous avez une pression artérielle élevée. N'utilisez pas ce produit si vous êtes enceinte, si vous allaitez ou si vous avez des antécédents de lupus érythémateux disséminé. N'utilisez pas ce produit si vous avez une maladie cardiaque, une pression artérielle élevée ou basse, un trouble rénal ou hépatique, une hypokaliémie."]$SQLTXT$::jsonb)) WHERE slug = $SQLTXT$betula-lenta$SQLTXT$;
UPDATE public.herbs SET contraindications = ARRAY[$SQLTXT$Contra-Indications: Do not take if you are pregnant or breastfeeding. Do not use if you have liver or gall bladder disorders and/or bowel obstruction. Discontinue use if you develop symptoms of liver trouble.$SQLTXT$, $SQLTXT$Known Adverse Reactions: Hypersensitivity, such as allergy, has been known to occur; in which case, discontinue use Shiitake: May cause abdominal discomfort including nausea and bloating, in which case discontinue use.$SQLTXT$, $SQLTXT$Contra-Indications: Do not use if you have impaired kidney function. Do not use if you have impaired liver function. Do not use if you are pregnant or breastfeeding. Do not use if you are allergic to the Asteraceae (daisy) family.$SQLTXT$, $SQLTXT$Known Adverse Reactions: Hypersensitivity, such as allergy, has been known to occur; in which case, discontinue use.$SQLTXT$, $SQLTXT$Contra-Indications: Do not use if you are taking antidepressants such as monoamine oxidase inhibitors (MAOIs). Do not use if you are allergic to yeast products.$SQLTXT$, $SQLTXT$Known Adverse Reactions: Hypersensitivity (e.g. allergy) can occur, in which case discontinue use and consult your healthcare practitioner. Discontinue use in case of gastrointestinal upsets, such as abdominal cramps, nausea, vomiting, diarrhea.$SQLTXT$]::text[], translations = jsonb_set(coalesce(translations, '{}'::jsonb), '{fr}', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('contraindications', $SQLTXT$["Contre-indications : Ne pas prendre si vous êtes enceinte ou si vous allaitez. Ne pas utiliser si vous souffrez de troubles hépatiques ou biliaires et/ou d'une occlusion intestinale. Cesser l'utilisation si des symptômes de trouble hépatique apparaissent.", "Réactions indésirables connues : Une hypersensibilité, telle qu'une allergie, a été signalée ; dans ce cas, cesser l'utilisation. Shiitake : Peut causer un inconfort abdominal, notamment des nausées et des ballonnements ; dans ce cas, cesser l'utilisation.", "Contre-indications : Ne pas utiliser si vous avez une fonction rénale altérée. Ne pas utiliser si vous avez une fonction hépatique altérée. Ne pas utiliser si vous êtes enceinte ou si vous allaitez. Ne pas utiliser si vous êtes allergique à la famille des Asteraceae (daisy).", "Réactions indésirables connues : Une hypersensibilité, telle qu'une allergie, a été signalée ; dans ce cas, cesser l'utilisation.", "Contre-indications : Ne pas utiliser si vous prenez des antidépresseurs tels que les inhibiteurs de la monoamine oxydase (IMAO). Ne pas utiliser si vous êtes allergique aux produits à base de levure.", "Réactions indésirables connues : Une hypersensibilité (p. ex. allergie) peut survenir ; dans ce cas, cesser l'utilisation et consulter votre praticien de la santé. Cesser l'utilisation en cas de troubles gastro-intestinaux, tels que crampes abdominales, nausées, vomissements, diarrhée."]$SQLTXT$::jsonb)) WHERE slug = $SQLTXT$raphanus-sativus-var-sativus$SQLTXT$;
UPDATE public.herbs SET contraindications = ARRAY[$SQLTXT$Known Adverse Reactions: Hypersensitivity/allergy can occur, in which case discontinue use and consult your healthcare practitioner. Some people may experience insomnia, anxiety, or headaches, in which case, discontinue use.$SQLTXT$, $SQLTXT$Contra-Indications: Do not use if you are pregnant or breastfeeding. Do not use if you have a history of systemic lupus erythematosus. If you have bipolar disorder or bipolar spectrum disorder, do not use this product. If you experience irritability or insomnia, discontinue use.$SQLTXT$, $SQLTXT$Contra-Indications: If you are pregnant or breastfeeding, do not use. If you have hypokalemia, high blood pressure, kidney disorder, cardiovascular disorder, an immune-compromised condition (e.g. AIDS, lymphoma, patients undergoing long-term corticosteroid treatment), do not use.$SQLTXT$, $SQLTXT$Contra-Indications: Grape seeds are contraindicated in patients with known hypersensitivity.$SQLTXT$, $SQLTXT$Known Adverse Reactions: Rare, unpredictable cases of liver injury associated with green tea extract-containing products have been reported (in Canada and internationally).$SQLTXT$, $SQLTXT$Known Adverse Reactions: Stop use if hypersensitivity/allergy occurs.$SQLTXT$]::text[], translations = jsonb_set(coalesce(translations, '{}'::jsonb), '{fr}', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('contraindications', $SQLTXT$["Réactions indésirables connues : Une hypersensibilité/allergie peut survenir, auquel cas il faut cesser l'utilisation et consulter un professionnel de la santé. Certaines personnes peuvent éprouver de l'insomnie, de l'anxiété ou des maux de tête, auquel cas il faut cesser l'utilisation.", "Contre-indications : Ne pas utiliser si vous êtes enceinte ou si vous allaitez. Ne pas utiliser si vous avez des antécédents de lupus érythémateux disséminé. Si vous souffrez de trouble bipolaire ou de trouble du spectre bipolaire, ne pas utiliser ce produit. Si vous éprouvez de l'irritabilité ou de l'insomnie, cessez l'utilisation.", "Contre-indications : Si vous êtes enceinte ou si vous allaitez, ne pas utiliser. Si vous avez une hypokaliémie, de l'hypertension artérielle, un trouble rénal, un trouble cardiovasculaire, un état d'immunodépression (p. ex. SIDA, lymphome, patients sous corticothérapie à long terme), ne pas utiliser.", "Contre-indications : Les pépins de raisin sont contre-indiqués chez les patients présentant une hypersensibilité connue.", "Réactions indésirables connues : Des cas rares et imprévisibles de lésions hépatiques associées à des produits contenant de l'extrait de thé vert ont été signalés (au Canada et à l'échelle internationale).", "Réactions indésirables connues : Cessez l'utilisation en cas d'hypersensibilité/allergie."]$SQLTXT$::jsonb)) WHERE slug = $SQLTXT$vitis-labrusca$SQLTXT$;
UPDATE public.herbs SET contraindications = ARRAY[$SQLTXT$Contra-Indications: Do not use if you have had a heart attack/myocardial infarction.$SQLTXT$, $SQLTXT$Known Adverse Reactions: Hypersensitivity, such as an allergy, has been known to occur; in which case, discontinue use. Some people may experience mild gastrointestinal disturbances and/or nausea.$SQLTXT$, $SQLTXT$Contra-Indications: If you are pregnant or breastfeeding, do not use. If you have heart disease, high or low blood pressure, kidney or liver disorder, diabetes or edema (swelling of hands, face and feet) or are taking products containing diuretics, do not use.$SQLTXT$, $SQLTXT$Contra-Indications: Do not use if you have liver or kidney problems.$SQLTXT$]::text[], translations = jsonb_set(coalesce(translations, '{}'::jsonb), '{fr}', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('contraindications', $SQLTXT$["Contre-indications : Ne pas utiliser si vous avez subi une crise cardiaque/un infarctus du myocarde.", "Effets indésirables connus : Une hypersensibilité, telle qu'une allergie, a été signalée ; dans ce cas, cessez l'utilisation. Certaines personnes peuvent ressentir des troubles gastro-intestinaux légers et/ou des nausées.", "Contre-indications : Si vous êtes enceinte ou si vous allaitez, ne pas utiliser. Si vous avez une maladie cardiaque, une pression artérielle élevée ou basse, un trouble rénal ou hépatique, du diabète ou de l'œdème (gonflement des mains, du visage et des pieds) ou si vous prenez des produits contenant des diurétiques, ne pas utiliser.", "Contre-indications : Ne pas utiliser si vous avez des problèmes de foie ou de reins."]$SQLTXT$::jsonb)) WHERE slug = $SQLTXT$chamaesyce-hirta$SQLTXT$;
UPDATE public.herbs SET contraindications = ARRAY[$SQLTXT$Contra-Indications: Do not use if you are pregnant or breastfeeding.$SQLTXT$, $SQLTXT$Contra-Indications: Do not use if you are pregnant or breastfeeding. Do not use if you have diarrhea, hemorrhagic diseases or heavy periods. Do not use if pupils are dilated.$SQLTXT$, $SQLTXT$Known Adverse Reactions: Stop use if hypersensitivity/allergy occurs.$SQLTXT$, $SQLTXT$Contra-Indications: If you are pregnant or breastfeeding, do not use this product.$SQLTXT$, $SQLTXT$Contra-Indications: Do not use this product if you are pregnant or breastfeeding. Do not use this product if you are pregnant or if you have hypermenorrhea/profuse menstrual flow/heavy periods. Do not use this product if you have diarrhea or hemorrhagic diseases.$SQLTXT$, $SQLTXT$Contra-Indications: According to Traditional Chinese Medicine, do not use this product in cases of exterior excess, qi stagnation, damp obstruction, food stagnation, yin deficiency with heat signs, or skin lesions in their early stages or where there is a heat toxin.$SQLTXT$]::text[], translations = jsonb_set(coalesce(translations, '{}'::jsonb), '{fr}', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('contraindications', $SQLTXT$["Contre-indications : N'utilisez pas si vous êtes enceinte ou si vous allaitez.", "Contre-indications : N'utilisez pas si vous êtes enceinte ou si vous allaitez. N'utilisez pas si vous avez de la diarrhée, des maladies hémorragiques ou des règles abondantes. N'utilisez pas si les pupilles sont dilatées.", "Réactions indésirables connues : Cessez l'utilisation en cas d'hypersensibilité/allergie.", "Contre-indications : Si vous êtes enceinte ou si vous allaitez, n'utilisez pas ce produit.", "Contre-indications : N'utilisez pas ce produit si vous êtes enceinte ou si vous allaitez. N'utilisez pas ce produit si vous êtes enceinte ou si vous avez une hyperménorrhée/des règles abondantes/des menstruations profuses. N'utilisez pas ce produit si vous avez de la diarrhée ou des maladies hémorragiques.", "Contre-indications : Selon la médecine traditionnelle chinoise, n'utilisez pas ce produit en cas d'excès extérieur, de stagnation du qi, d'obstruction par l'humidité, de stagnation alimentaire, de vide de yin avec signes de chaleur, ou de lésions cutanées à leurs stades précoces ou en présence d'une toxine de chaleur."]$SQLTXT$::jsonb)) WHERE slug = $SQLTXT$ligusticum-sinense-cv-chuanxiong$SQLTXT$;
UPDATE public.herbs SET contraindications = ARRAY[$SQLTXT$Contra-Indications: If you are pregnant or breastfeeding, do not use this product.$SQLTXT$, $SQLTXT$Contra-Indications: If you are pregnant or breastfeeding, do not use this product. Do not use this product if you have hypokalemia or a kidney disorder.$SQLTXT$, $SQLTXT$Known Adverse Reactions: Product may cause nausea, vomiting, abdominal pain, diarrhea, bloating, rash, itchy ulcers, dry mouth, and/or dizziness.$SQLTXT$]::text[], translations = jsonb_set(coalesce(translations, '{}'::jsonb), '{fr}', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('contraindications', $SQLTXT$["Contre-indications : Si vous êtes enceinte ou allaitez, n'utilisez pas ce produit.", "Contre-indications : Si vous êtes enceinte ou allaitez, n'utilisez pas ce produit. N'utilisez pas ce produit si vous souffrez d'hypokaliémie ou d'un trouble rénal.", "Réactions indésirables connues : Le produit peut causer des nausées, des vomissements, des douleurs abdominales, de la diarrhée, des ballonnements, une éruption cutanée, des ulcères prurigineux, une sécheresse buccale et/ou des étourdissements."]$SQLTXT$::jsonb)) WHERE slug = $SQLTXT$dryopteris-crassirhizoma$SQLTXT$;
UPDATE public.herbs SET contraindications = ARRAY[$SQLTXT$Contra-Indications: According to Traditional Chinese Medicine, do not use this product in cases of exterior excess, qi stagnation, damp obstruction, food stagnation, yin deficiency with heat signs, or skin lesions in their early stages or where there is a heat toxin.$SQLTXT$, $SQLTXT$Contra-Indications: If you are pregnant or breast-feeding, do not use this product.$SQLTXT$, $SQLTXT$Contra-Indications: Do not use product during pregnancy.$SQLTXT$, $SQLTXT$Contra-Indications: Do not use this product if you are pregnant or breastfeeding.$SQLTXT$, $SQLTXT$Contra-Indications: Do not use product during pregnancy and breastfeeding. Do not use if you are taking diuretics, stimulant laxatives or other medicatins which may aggravate electrolyte imbalance.$SQLTXT$]::text[], translations = jsonb_set(coalesce(translations, '{}'::jsonb), '{fr}', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('contraindications', $SQLTXT$["Contre-indications : Selon la médecine traditionnelle chinoise, ne pas utiliser ce produit en cas d'excès externe, de stagnation du qi, d'obstruction par l'humidité, de stagnation alimentaire, de vide de yin avec signes de chaleur, ou de lésions cutanées à leurs stades précoces ou en présence d'une toxine de chaleur.", "Contre-indications : Si vous êtes enceinte ou allaitez, ne pas utiliser ce produit.", "Contre-indications : Ne pas utiliser le produit pendant la grossesse.", "Contre-indications : Ne pas utiliser ce produit si vous êtes enceinte ou allaitez.", "Contre-indications : Ne pas utiliser le produit pendant la grossesse et l'allaitement. Ne pas utiliser si vous prenez des diurétiques, des laxatifs stimulants ou d'autres médicaments susceptibles d'aggraver un déséquilibre électrolytique."]$SQLTXT$::jsonb)) WHERE slug = $SQLTXT$stellaria-dichotoma-var-lanceolata$SQLTXT$;
UPDATE public.herbs SET contraindications = ARRAY[$SQLTXT$Contra-Indications: If you are experiencing a sudden change in bowel habits that has persisted for more than 2 weeks, undiagnosed rectal bleeding, or failure to defecate following the use of another laxative product, do not use this product.$SQLTXT$, $SQLTXT$Known Adverse Reactions: Hypersensitivity, such as allergy, been known to occur; in which case discontinue use.$SQLTXT$, $SQLTXT$Contra-Indications: Do not use if you are pregnant or breastfeeding.$SQLTXT$, $SQLTXT$Contra-Indications: Do not use if you are pregnant or breastfeeding. Do not use if you have high blood pressure or thiamine (vitamin B) deficiency; suffer from impaired kidney, heart and/or liver functions; or if you are taking digitalis or diuretics.$SQLTXT$]::text[], translations = jsonb_set(coalesce(translations, '{}'::jsonb), '{fr}', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('contraindications', $SQLTXT$["Contre-indications : Si vous présentez un changement soudain des habitudes intestinales persistant depuis plus de 2 semaines, des saignements rectaux non diagnostiqués ou une incapacité à déféquer après l'utilisation d'un autre laxatif, n'utilisez pas ce produit.", "Réactions indésirables connues : Une hypersensibilité, telle qu'une allergie, a été signalée ; dans ce cas, cessez l'utilisation.", "Contre-indications : N'utilisez pas si vous êtes enceinte ou si vous allaitez.", "Contre-indications : N'utilisez pas si vous êtes enceinte ou si vous allaitez. N'utilisez pas si vous avez une hypertension artérielle ou une carence en thiamine (vitamine B) ; si vous souffrez d'une insuffisance rénale, cardiaque et/ou hépatique ; ou si vous prenez de la digitaline ou des diurétiques."]$SQLTXT$::jsonb)) WHERE slug = $SQLTXT$silybum-marianum-l-gaertn$SQLTXT$;
UPDATE public.herbs SET contraindications = ARRAY[$SQLTXT$Known Adverse Reactions: Stop use if hypersensitivity/allergy occurs.$SQLTXT$, $SQLTXT$Contra-Indications: Do not use this product if you are pregnant.$SQLTXT$, $SQLTXT$Known Adverse Reactions: May cause nausea, abdominal pain, and/or diarrhea.$SQLTXT$, $SQLTXT$Known Adverse Reactions: Hypersensitivity/allergy is known to occur, in which case, discontinue use Do not use if you are allergic to plants of the Asteraceae/Compositae/Daisy family.$SQLTXT$]::text[], translations = jsonb_set(coalesce(translations, '{}'::jsonb), '{fr}', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('contraindications', $SQLTXT$["Réactions indésirables connues : Cesser l'utilisation en cas d'hypersensibilité ou d'allergie.", "Contre-indications : Ne pas utiliser ce produit si vous êtes enceinte.", "Réactions indésirables connues : Peut causer des nausées, des douleurs abdominales et/ou de la diarrhée.", "Réactions indésirables connues : Une hypersensibilité ou une allergie est connue pour survenir, auquel cas cessez l'utilisation. Ne pas utiliser si vous êtes allergique aux plantes de la famille des Asteraceae/Compositae/marguerites."]$SQLTXT$::jsonb)) WHERE slug = $SQLTXT$eruca-sativa$SQLTXT$;
UPDATE public.herbs SET contraindications = ARRAY[$SQLTXT$Contra-Indications: If you are pregnant or breastfeeding, do not use this product.$SQLTXT$, $SQLTXT$Contra-Indications: If you are pregnant or breastfeeding, do not use this product.Do not use this product if you have hypokalemia, high blood pressure, or a kidney or cardiovascular disorder.Do not use this product if you are taking thiazide diuretics, cardiac glycosides, corticosteroids.$SQLTXT$]::text[], translations = jsonb_set(coalesce(translations, '{}'::jsonb), '{fr}', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('contraindications', $SQLTXT$["Contre-indications : Si vous êtes enceinte ou allaitez, n'utilisez pas ce produit.", "Contre-indications : Si vous êtes enceinte ou allaitez, n'utilisez pas ce produit. N'utilisez pas ce produit si vous avez une hypokaliémie, une pression artérielle élevée ou un trouble rénal ou cardiovasculaire."]$SQLTXT$::jsonb)) WHERE slug = $SQLTXT$magnolia-officinalis-var-biloba$SQLTXT$;
UPDATE public.herbs SET contraindications = ARRAY[$SQLTXT$Contra-Indications: Do not use if you are pregnant. Do not use if you have acute stomach irritations, inflammation, and stomach or duodenal ulcers.$SQLTXT$, $SQLTXT$Known Adverse Reactions: Headaches, heartburn, bloating and hypersensitivity (e.g. allergy) have been known to occur; in which case, discontinue use.$SQLTXT$, $SQLTXT$Known Adverse Reactions: Stop use if hypersensitivity/allergy occurs. Some people may experience drowsiness. Exercise caution if operating heavy machinery, driving a motor vehicle or involved in activities requiring mental alertness.$SQLTXT$, $SQLTXT$Contra-Indications: Do not use if you are pregnant or breastfeeding. Do not use if you have an immune-compromised condition (e.g. AIDS, lymphoma, patients undergoing long-term corticosteroid treatment). Do not use if you or your partner are attempting to conceive.$SQLTXT$, $SQLTXT$Contra-Indications: Do not use this product if you are pregnant, breastfeeding, have a milk allergy or have an immune-compromised condition (e.g. aids, lymphoma, patients undergoing long-term corticosteroids treatment).$SQLTXT$]::text[], translations = jsonb_set(coalesce(translations, '{}'::jsonb), '{fr}', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('contraindications', $SQLTXT$["Contre-indications : Ne pas utiliser si vous êtes enceinte. Ne pas utiliser si vous souffrez d'irritations aiguës de l'estomac, d'inflammation et d'ulcères gastriques ou duodénaux.", "Réactions indésirables connues : Des maux de tête, des brûlures d'estomac, des ballonnements et une hypersensibilité (p. ex. allergie) ont été signalés ; dans ce cas, cessez l'utilisation.", "Réactions indésirables connues : Cessez l'utilisation en cas d'hypersensibilité/allergie. Certaines personnes peuvent éprouver de la somnolence. Faites preuve de prudence si vous utilisez de la machinerie lourde, conduisez un véhicule automobile ou pratiquez des activités nécessitant de la vigilance mentale.", "Contre-indications : Ne pas utiliser si vous êtes enceinte ou si vous allaitez. Ne pas utiliser si vous avez un état d'immunodépression (p. ex. SIDA, lymphome, patients sous corticothérapie à long terme). Ne pas utiliser si vous ou votre partenaire tentez de concevoir.", "Contre-indications : Ne pas utiliser ce produit si vous êtes enceinte, si vous allaitez, si vous avez une allergie au lait ou un état d'immunodépression (p. ex. SIDA, lymphome, patients sous corticothérapie à long terme)."]$SQLTXT$::jsonb)) WHERE slug = $SQLTXT$chenopodium-quinoa$SQLTXT$;
UPDATE public.herbs SET contraindications = ARRAY[$SQLTXT$Known Adverse Reactions: Stop use if hypersensitivity occurs. Stop use if hypersensitivity/allergy occurs.$SQLTXT$, $SQLTXT$Contra-Indications: Do not use if you are pregnant, breastfeeding or attempting to conceive unless you have consulted with a health care practitioner/health care provider/health care professional/doctor/physician. Do not use if you have high blood pressure.$SQLTXT$, $SQLTXT$Contra-Indications: Do not use if you are pregnant or breastfeeding. Do not use if you have a history of systemic lupus erythematosus.$SQLTXT$, $SQLTXT$Known Adverse Reactions: Hypersensitivity/allergy has been known to occur; in which case, discontinue use. Rare, unpredictable cases of liver injury associated with green tea extract-containing products have been reported (in Canada and internationally).$SQLTXT$, $SQLTXT$Contra-Indications: Do not use if you have a bile duct obstruction. Do not use if you have gallstones. Do not use if you are pregnant.$SQLTXT$, $SQLTXT$Known Adverse Reactions: Do not use if you are allergic to plants of the Asteraceae/Compositae/Daisy family. Hypersensitivity, such as an allergy, has been known to occur, in which case, discontinue use.$SQLTXT$]::text[], translations = jsonb_set(coalesce(translations, '{}'::jsonb), '{fr}', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('contraindications', $SQLTXT$["Réactions indésirables connues : Cesser l'utilisation en cas d'hypersensibilité. Cesser l'utilisation en cas d'hypersensibilité/allergie.", "Contre-indications : Ne pas utiliser si vous êtes enceinte, si vous allaitez ou si vous tentez de concevoir, sauf après consultation d'un praticien de la santé/un fournisseur de soins de santé/un professionnel de la santé/un médecin. Ne pas utiliser si vous avez une tension artérielle élevée.", "Contre-indications : Ne pas utiliser si vous êtes enceinte ou si vous allaitez. Ne pas utiliser si vous avez des antécédents de lupus érythémateux disséminé.", "Réactions indésirables connues : L'hypersensibilité/allergie a été signalée ; le cas échéant, cesser l'utilisation. De rares cas imprévisibles de lésions hépatiques associés à des produits contenant de l'extrait de thé vert ont été signalés (au Canada et à l'échelle internationale).", "Contre-indications : Ne pas utiliser si vous avez une obstruction des voies biliaires. Ne pas utiliser si vous avez des calculs biliaires. Ne pas utiliser si vous êtes enceinte.", "Réactions indésirables connues : Ne pas utiliser si vous êtes allergique aux plantes de la famille des Asteraceae/Compositae/Daisy. L'hypersensibilité, telle qu'une allergie, a été signalée ; le cas échéant, cesser l'utilisation."]$SQLTXT$::jsonb)) WHERE slug = $SQLTXT$brassica-oleracea-var-capitata$SQLTXT$;
UPDATE public.herbs SET contraindications = ARRAY[$SQLTXT$Cautions and Warnings: Do not consume during pregnancy or nursing. Do not take if experiencing nausea, vomiting or symptoms of appendicitis. Long term use may create dependence.$SQLTXT$, $SQLTXT$Contra-Indications: Do not use if pregnant or breastfeeding. Do not use if you are experiencing a sudden change in bowel habits that has persisted for more than 2 weeks, undiagnosed rectal bleeding, or failure to defecate following the use of another laxative.$SQLTXT$, $SQLTXT$Known Adverse Reactions: Allergy to plants of the Asteraceae, daisy, Leguminosae families. Hypersensitivity, such as allergy, has been known to occur, in which case discontinue use. May cause temporary gas and/or bloating.$SQLTXT$]::text[], translations = jsonb_set(coalesce(translations, '{}'::jsonb), '{fr}', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('contraindications', $SQLTXT$["Mises en garde et avertissements : Ne pas consommer pendant la grossesse ou l'allaitement. Ne pas prendre en cas de nausées, de vomissements ou de symptômes d'appendicite. L'utilisation à long terme peut créer une dépendance.", "Contre-indications : Ne pas utiliser si vous êtes enceinte ou si vous allaitez. Ne pas utiliser si vous présentez un changement soudain des habitudes intestinales persistant depuis plus de 2 semaines, un saignement rectal non diagnostiqué, ou une incapacité à déféquer après l'utilisation d'un autre laxatif.", "Réactions indésirables connues : Allergie aux plantes des familles Asteraceae, marguerite, Leguminosae. Une hypersensibilité, telle qu'une allergie, a été signalée, auquel cas il faut cesser l'utilisation. Peut causer des gaz et/ou des ballonnements temporaires."]$SQLTXT$::jsonb)) WHERE slug = $SQLTXT$plantago-psyllium$SQLTXT$;
UPDATE public.herbs SET contraindications = ARRAY[$SQLTXT$Cautions and Warnings: Conditions normales d'entreposage.$SQLTXT$, $SQLTXT$Contra-Indications: Do not use if allergic to the Asteraceae/Compositae/ Daisy family. Do not take if you are pregnant or breastfeeding.$SQLTXT$, $SQLTXT$Known Adverse Reactions: Hypersensitivity, such as allergy, has been known to occur; in which case, discontinue use.$SQLTXT$]::text[], translations = jsonb_set(coalesce(translations, '{}'::jsonb), '{fr}', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('contraindications', $SQLTXT$["Mises en garde et avertissements : Conditions normales d'entreposage.", "Mises en garde et avertissements : Ne pas utiliser si le sceau de sécurité est brisé. Garder hors de la portée des enfants. Consultez un praticien de la santé avant l`usage si vous êtes enceinte ou si vous allaitez. Consulter un praticien de la santé si les symptômes persistent ou s`aggravent après 72 heures.", "Contre-indications : Ne pas utiliser en cas d'allergie à la famille des Asteraceae/Compositae/ marguerites. Ne pas prendre si vous êtes enceinte ou si vous allaitez.", "Effets indésirables connus : Une hypersensibilité, telle qu'une allergie, a été signalée ; dans ce cas, cessez l'utilisation."]$SQLTXT$::jsonb)) WHERE slug = $SQLTXT$colocynthis-vulgaris$SQLTXT$;
UPDATE public.herbs SET contraindications = ARRAY[$SQLTXT$Contra-Indications: Do not use if you are pregnant or breastfeeding.$SQLTXT$]::text[], translations = jsonb_set(coalesce(translations, '{}'::jsonb), '{fr}', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('contraindications', $SQLTXT$["Contre-indications : Ne pas utiliser si vous êtes enceinte ou allaitez."]$SQLTXT$::jsonb)) WHERE slug = $SQLTXT$vaccinium-myrtillus-l$SQLTXT$;
UPDATE public.herbs SET contraindications = ARRAY[$SQLTXT$Contra-Indications: Do not use if you are pregnant or breastfeeding. Do not use if you have bipolar disorder or bipolar spectrum disorder. Do not use if you have had a heart attack/myocardial infarction.$SQLTXT$, $SQLTXT$Known Adverse Reactions: If you experience irritability or insomnia, discontinue use. May cause nausea, stomachpain or gastrointestinal discomfort (diarrhea), in which case discontinue use. May cause mild cases of dry mouth, bitter taste, vomiting, or abdominal pain.$SQLTXT$, $SQLTXT$Contra-Indications: Do not use if you have liver or gall bladder disorders, and/or bowel obstructions. Discontinue use if you develop symptoms of liver trouble. Do not use if you are allergic to plants of the Asteraceae/Compositae/Daisy family. Do not use if you are pregnant or breastfeeding.$SQLTXT$, $SQLTXT$Known Adverse Reactions: Hypersensitivity, such as allergy, has been known to occur; in which case, discontinue use.$SQLTXT$, $SQLTXT$Known Adverse Reactions: If you experience irritability or insomnia, discontinue use. May cause nausea, stomach pain or gastrointestinal discomfort (diarrhea), in which case discontinue use. May cause mild cases of dry mouth, bitter taste, vomiting, or abdominal pain.$SQLTXT$, $SQLTXT$Contra-Indications: Do not use this product if you are pregnant or have a kidney disorder. If you have heart disease, high or low blood pressure, liver disorder, diabetes or edema (swelling of hands, face and feet) or are taking products containing diuretics), do not use this product.$SQLTXT$]::text[], translations = jsonb_set(coalesce(translations, '{}'::jsonb), '{fr}', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('contraindications', $SQLTXT$["Contre-indications : Ne pas utiliser si vous êtes enceinte ou si vous allaitez. Ne pas utiliser si vous souffrez de trouble bipolaire ou de trouble du spectre bipolaire. Ne pas utiliser si vous avez subi une crise cardiaque/un infarctus du myocarde.", "Effets indésirables connus : Si vous ressentez de l'irritabilité ou de l'insomnie, cessez l'utilisation. Peut causer des nausées, des douleurs abdominales ou de l'inconfort gastro-intestinal (diarrhée), auquel cas cessez l'utilisation. Peut causer des cas bénins de bouche sèche, de goût amer, de vomissements ou de douleurs abdominales.", "Contre-indications : Ne pas utiliser si vous souffrez de troubles hépatiques ou vésiculaires, et/ou d'occlusions intestinales. Cessez l'utilisation si vous développez des symptômes de trouble hépatique. Ne pas utiliser si vous êtes allergique aux plantes de la famille des Asteraceae/Compositae/Marguerites. Ne pas utiliser si vous êtes enceinte ou si vous allaitez.", "Effets indésirables connus : Une hypersensibilité, telle qu'une allergie, a été signalée ; dans ce cas, cessez l'utilisation.", "Contre-indications : Ne pas utiliser ce produit si vous êtes enceinte ou si vous souffrez d'un trouble rénal. Si vous souffrez d'une maladie cardiaque, d'hypertension ou d'hypotension, d'un trouble hépatique, de diabète ou d'œdème (gonflement des mains, du visage et des pieds) ou si vous prenez des produits contenant des diurétiques, ne pas utiliser ce produit."]$SQLTXT$::jsonb)) WHERE slug = $SQLTXT$cucurbita-moschata$SQLTXT$;
UPDATE public.herbs SET contraindications = ARRAY[$SQLTXT$Contra-Indications: According to Traditional Chinese Medicine, do not use this product in cases of exterior excess, qi stagnation, damp obstruction, food stagnation, yin deficiency with heat signs, or skin lesions in their early stages or where there is a heat toxin.$SQLTXT$, $SQLTXT$Contra-Indications: Do not use if you are pregnant.$SQLTXT$, $SQLTXT$Known Adverse Reactions: Long-term use may irritate the gastric mucosa. May cause severe, watery diarrhea.$SQLTXT$, $SQLTXT$Contra-Indications: If you are pregnant or breastfeeding, do not use this product. Do not use if you have qi deficiency, no significant qi stagnation, weak stomach or an intolerance to garlic and onions.$SQLTXT$]::text[], translations = jsonb_set(coalesce(translations, '{}'::jsonb), '{fr}', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('contraindications', $SQLTXT$["Contre-indications : Selon la médecine traditionnelle chinoise, ne pas utiliser ce produit en cas d'excès externe, de stagnation du qi, d'obstruction par l'humidité, de stagnation alimentaire, de vide de yin avec signes de chaleur, ou de lésions cutanées à leurs stades précoces ou en présence d'une toxine de chaleur.", "Contre-indications : Ne pas utiliser si vous êtes enceinte.", "Réactions indésirables connues : L'utilisation à long terme peut irriter la muqueuse gastrique. Peut provoquer une diarrhée aqueuse sévère.", "Contre-indications : Si vous êtes enceinte ou allaitez, n'utilisez pas ce produit. Ne pas utiliser si vous avez un vide de qi, une absence de stagnation significative du qi, un estomac faible ou une intolérance à l'ail et aux oignons."]$SQLTXT$::jsonb)) WHERE slug = $SQLTXT$trichosanthes-rosthornii$SQLTXT$;
UPDATE public.herbs SET contraindications = ARRAY[$SQLTXT$Known Adverse Reactions: Some people may experience gastroesophageal reflux. Stop use if hypersensitivity/allergy occurs. May cause mild gastro-intestinal discomfort (such as gas, bloating, cramps).$SQLTXT$, $SQLTXT$Contra-Indications: Do not use this product if you have abnormal constrictions of the gastrointestinal tract, potential or existing intestinal blockage, atonic bowel, appendicitis, inflammatory colon disease such as Crohn's disease or ulcerative colitis, abdominal pain of unknown origin.$SQLTXT$, $SQLTXT$Contra-Indications: Do not take if pregnant or breastfeeding.$SQLTXT$, $SQLTXT$Known Adverse Reactions: People sensitive to nicotinic acid may experience flushing of the skin that is generally mild and transient. Jiao gu lan may cause drowsiness and sedation.$SQLTXT$, $SQLTXT$Contra-Indications: Do not use if pregnant or breastfeeding.$SQLTXT$, $SQLTXT$Known Adverse Reactions: If you experience nausea, dizziness, headache or an allergic reaction, discontinue use.$SQLTXT$]::text[], translations = jsonb_set(coalesce(translations, '{}'::jsonb), '{fr}', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('contraindications', $SQLTXT$["Réactions indésirables connues : Certaines personnes peuvent éprouver un reflux gastro-œsophagien. Cessez l'utilisation en cas d'hypersensibilité ou d'allergie. Peut causer un léger inconfort gastro-intestinal (tel que des gaz, des ballonnements, des crampes).", "Contre-indications : N'utilisez pas ce produit si vous avez des constrictions anormales du tractus gastro-intestinal, une occlusion intestinale potentielle ou existante, un intestin atone, une appendicite, une maladie inflammatoire du côlon telle que la maladie de Crohn ou la colite ulcéreuse, des douleurs abdominales d'origine inconnue.", "Contre-indications : Ne pas prendre si vous êtes enceinte ou si vous allaitez.", "Réactions indésirables connues : Les personnes sensibles à l'acide nicotinique peuvent éprouver des bouffées vasomotrices de la peau, généralement légères et transitoires. Le jiao gu lan peut causer de la somnolence et de la sédation.", "Contre-indications : Ne pas utiliser si vous êtes enceinte ou si vous allaitez.", "Réactions indésirables connues : Si vous éprouvez des nausées, des étourdissements, des maux de tête ou une réaction allergique, cessez l'utilisation."]$SQLTXT$::jsonb)) WHERE slug = $SQLTXT$citrus-limon$SQLTXT$;
UPDATE public.herbs SET contraindications = ARRAY[$SQLTXT$Contra-Indications: If you are pregnant or breastfeeding, do not use this product.$SQLTXT$, $SQLTXT$Contra-Indications: Contraindicated in pregnancy and breastfeeding.$SQLTXT$, $SQLTXT$Contra-Indications: Do not use during the acute phase of an infection or attack by an external pathogen.$SQLTXT$, $SQLTXT$Contra-Indications: Do not use if you are pregnant or breastfeeding. Do not use if you are taking heart medications, corticosteroids, stimulant laxatives, or other health products that may contribute electrolyte imbalance. Do not use if you have diarrhea, hemorrhagic diseases or heavy periods.$SQLTXT$]::text[], translations = jsonb_set(coalesce(translations, '{}'::jsonb), '{fr}', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('contraindications', $SQLTXT$["Contre-indications : Si vous êtes enceinte ou allaitez, n'utilisez pas ce produit.", "Contre-indications : Contre-indiqué pendant la grossesse et l'allaitement.", "Contre-indications : Ne pas utiliser pendant la phase aiguë d'une infection ou d'une attaque par un pathogène externe.", "Contre-indications : Ne pas utiliser si vous êtes enceinte ou allaitez. Ne pas utiliser si vous prenez des médicaments cardiaques, des corticostéroïdes, des laxatifs stimulants ou d'autres produits de santé susceptibles de contribuer à un déséquilibre électrolytique. Ne pas utiliser si vous avez de la diarrhée, des maladies hémorragiques ou des règles abondantes."]$SQLTXT$::jsonb)) WHERE slug = $SQLTXT$vaccaria-hispanica-subsp-hispanica$SQLTXT$;
UPDATE public.herbs SET contraindications = ARRAY[$SQLTXT$Contra-Indications: Do not use if you are pregnant or breastfeeding. Do not use if you are taking heart medications, corticosteroids, stimulant laxatives, or other health products that may contribute electrolyte imbalance.$SQLTXT$, $SQLTXT$Contra-Indications: Do not use if you are pregnant or breastfeeding.$SQLTXT$, $SQLTXT$Contra-Indications: Do not use this product if you are pregnant or breastfeeding. Do not use this product if you have excess heat, yin-deficient fire, or bleeding caused by heat in the blood.$SQLTXT$, $SQLTXT$Known Adverse Reactions: Diuretic effect may occur. Stop use if hypersensitivity/allergy occurs.$SQLTXT$, $SQLTXT$Contra-Indications: Do not use if you are pregnant or breastfeeding. Do not use if you have heart disease, high or low blood pressure, kidney or liver disorder, diabetes or edema (swelling of hands, face and feet) or are taking other products containing diuretics.$SQLTXT$, $SQLTXT$Known Adverse Reactions: Diuretic effect may occur. Stop use if hypersensitivity/allergy occurs. Stop use if you experience insomnia, anxiety or headaches.$SQLTXT$]::text[], translations = jsonb_set(coalesce(translations, '{}'::jsonb), '{fr}', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('contraindications', $SQLTXT$["Contre-indications : N'utilisez pas ce produit si vous êtes enceinte ou allaitez. N'utilisez pas si vous prenez des médicaments pour le cœur, des corticoïdes, des laxatifs stimulants ou d'autres produits de santé susceptibles de contribuer à un déséquilibre électrolytique.", "Contre-indications : N'utilisez pas si vous êtes enceinte ou allaitez.", "Contre-indications : N'utilisez pas ce produit si vous êtes enceinte ou allaitez. N'utilisez pas ce produit si vous avez une chaleur excessive, un feu par insuffisance du yin ou un saignement causé par la chaleur dans le sang.", "Réactions indésirables connues : Un effet diurétique peut se produire. Cessez l'utilisation en cas d'hypersensibilité ou d'allergie.", "Contre-indications : N'utilisez pas si vous êtes enceinte ou allaitez. N'utilisez pas si vous avez une maladie cardiaque, une pression artérielle élevée ou basse, un trouble rénal ou hépatique, un diabète ou un œdème (gonflement des mains, du visage et des pieds) ou si vous prenez d'autres produits contenant des diurétiques.", "Réactions indésirables connues : Un effet diurétique peut se produire. Cessez l'utilisation en cas d'hypersensibilité ou d'allergie. Cessez l'utilisation si vous ressentez de l'insomnie, de l'anxiété ou des maux de tête."]$SQLTXT$::jsonb)) WHERE slug = $SQLTXT$bambusa-breviflora$SQLTXT$;
UPDATE public.herbs SET contraindications = ARRAY[$SQLTXT$Contra-Indications: If you are pregnant or breastfeeding, do not use this product.$SQLTXT$, $SQLTXT$Contra-Indications: Do not use this product if you are pregnant or breastfeeding.$SQLTXT$, $SQLTXT$Contra-Indications: Do not use if you are pregnant or breastfeeding. Do not use if you are taking heart medications, corticosteroids, stimulant laxatives, or other health products that may contribute electrolyte imbalance. Do not use if you have diarrhea, hemorrhagic diseases or heavy periods.$SQLTXT$, $SQLTXT$Contra-Indications: Do not use if you are pregnant or breastfeeding. Do not use if you have diarrhea, hemorrhagic diseases or heavy periods.$SQLTXT$]::text[], translations = jsonb_set(coalesce(translations, '{}'::jsonb), '{fr}', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('contraindications', $SQLTXT$["Contre-indications : Si vous êtes enceinte ou si vous allaitez, n'utilisez pas ce produit.", "Contre-indications : N'utilisez pas ce produit si vous êtes enceinte ou si vous allaitez.", "Contre-indications : N'utilisez pas si vous êtes enceinte ou si vous allaitez. N'utilisez pas si vous prenez des médicaments pour le cœur, des corticostéroïdes, des laxatifs stimulants ou d'autres produits de santé susceptibles de contribuer à un déséquilibre électrolytique. N'utilisez pas si vous avez de la diarrhée, des maladies hémorragiques ou des règles abondantes.", "Contre-indications : N'utilisez pas si vous êtes enceinte ou si vous allaitez. N'utilisez pas si vous avez de la diarrhée, des maladies hémorragiques ou des règles abondantes."]$SQLTXT$::jsonb)) WHERE slug = $SQLTXT$ligusticum-jeholense$SQLTXT$;
UPDATE public.herbs SET contraindications = ARRAY[$SQLTXT$Contra-Indications: Do no use if you are pregnant or breastfeeding or if you are hypersensitive to caffeine or tannins.$SQLTXT$, $SQLTXT$Contra-Indications: Do not use if you are pregnant or breastfeeding, if you are allergic/hypersensitive to bee products or polen, if you have a history of systemic lupus erythematosus, if you are taking corticosteroids or cyclosporine, and/or if you have sickle cell anemia.$SQLTXT$, $SQLTXT$Contra-Indications: Do not use if you are taking thiazide diuretics, cardiac glycosides, corticosteroids, stimulant laxatives or other medications which may aggravate electrolyte imbalance or if you are pregnant or breastfeeding, have hypokalemia, high blood pressure, or a kidney, liver.$SQLTXT$]::text[], translations = jsonb_set(coalesce(translations, '{}'::jsonb), '{fr}', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('contraindications', $SQLTXT$["Contre-indications : Ne pas utiliser si vous êtes enceinte ou si vous allaitez ou si vous êtes hypersensible à la caféine ou aux tanins.", "Contre-indications : Ne pas utiliser si vous êtes enceinte ou si vous allaitez, si vous êtes allergique/hypersensible aux produits d'abeille ou au pollen, si vous avez des antécédents de lupus érythémateux disséminé, si vous prenez des corticostéroïdes ou de la cyclosporine et/ou si vous souffrez d'anémie falciforme, d'un déficit en glucose-6-phosphate.", "Contre-indications : Ne pas utiliser si vous prenez des diurétiques thiazidiques, des glycosides cardiotoniques, des corticostéroïdes, des laxatifs stimulants ou d'autres médicaments susceptibles d'aggraver un déséquilibre électrolytique, ou si vous êtes enceinte ou si vous allaitez, avez une hypokaliémie, une hypertension artérielle ou une maladie rénale."]$SQLTXT$::jsonb)) WHERE slug = $SQLTXT$cassia-tora$SQLTXT$;
UPDATE public.herbs SET contraindications = ARRAY[$SQLTXT$Contra-Indications: Do not use if you are pregnant or breastfeeding.$SQLTXT$, $SQLTXT$Contra-Indications: Do not use if you are taking; or have taken in the past two weeks monoamine oxidase (MAO) inhibitors. Do not use if you are pregnant or breastfeeding.$SQLTXT$, $SQLTXT$Known Adverse Reactions: Insomnia has been known to occur; in which case; discontinue use. Irritability; dizziness and/or tremor have been known to occur; in which case; discontinue use. Nausea and/or loss of appetite have been known to occur; in which case; discontinue use.$SQLTXT$, $SQLTXT$Contra-Indications: If you are pregnant or breastfeeding, do not use this product.$SQLTXT$]::text[], translations = jsonb_set(coalesce(translations, '{}'::jsonb), '{fr}', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('contraindications', $SQLTXT$["Contre-indications : Ne pas utiliser si vous êtes enceinte ou si vous allaitez.", "Contre-indications : Ne pas utiliser si vous prenez ou avez pris au cours des deux dernières semaines des inhibiteurs de la monoamine oxydase (MAO). Ne pas utiliser si vous êtes enceinte ou si vous allaitez.", "Effets indésirables connus : Des cas d'insomnie ont été signalés ; le cas échéant, cesser l'utilisation. Des cas d'irritabilité, de vertiges et/ou de tremblements ont été signalés ; le cas échéant, cesser l'utilisation. Des cas de nausées et/ou de perte d'appétit ont été signalés ; le cas échéant, cesser l'utilisation.", "Contre-indications : Si vous êtes enceinte ou si vous allaitez, ne pas utiliser ce produit."]$SQLTXT$::jsonb)) WHERE slug = $SQLTXT$selaginella-pulvinata$SQLTXT$;
UPDATE public.herbs SET contraindications = ARRAY[$SQLTXT$Contra-Indications: Do not use if you are pregnant or breastfeeding.$SQLTXT$, $SQLTXT$Known Adverse Reactions: Stop use if hypersensitivity/allergy occurs.$SQLTXT$, $SQLTXT$Contra-Indications: Do not use this product if you are pregnant, breastfeeding or have a history of systemic lupus erythematosus. Do not use this product if you are taking health products that affect blood coagulation as this may increase the risk of spontaneous bleeding.$SQLTXT$, $SQLTXT$Cautions and Warnings: If seal around cap is broken or missing, do not use. Consult a healthcare practitioner prior to use if you are taking blood thinners, birth control or undergoing hormone replacement therapy (HRT).$SQLTXT$]::text[], translations = jsonb_set(coalesce(translations, '{}'::jsonb), '{fr}', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('contraindications', $SQLTXT$["Contre-indications : Ne pas utiliser si vous êtes enceinte ou si vous allaitez.", "Effets indésirables connus : Cesser l'utilisation en cas d'hypersensibilité ou d'allergie.", "Contre-indications : Ne pas utiliser ce produit si vous êtes enceinte, si vous allaitez ou si vous avez des antécédents de lupus érythémateux disséminé. Ne pas utiliser ce produit si vous prenez des produits de santé qui influent sur la coagulation sanguine, car cela pourrait augmenter le risque de saignement spontané.", "Mises en garde et avertissements : Si le sceau autour du bouchon est brisé ou absent, ne pas utiliser. Consulter un professionnel de la santé avant l'utilisation si vous prenez des anticoagulants, des contraceptifs oraux ou si vous suivez une hormonothérapie substitutive (HTS)."]$SQLTXT$::jsonb)) WHERE slug = $SQLTXT$medicago-sativa-l$SQLTXT$;
UPDATE public.herbs SET contraindications = ARRAY[$SQLTXT$Known Adverse Reactions: Rare, unpredictable cases of liver injury associated with green tea extract-containing products have been reported (in Canada and internationally). Diuretic effect may occur. May cause temporary gas and/or bloating. Stop use if hypersensitivity/allergy occurs.$SQLTXT$, $SQLTXT$Contra-Indications: Do not use this product if you are pregnant, breastfeeding or have a history of systemic lupus erythematosus. Do not use if you have difficulty swallowing.$SQLTXT$, $SQLTXT$Contra-Indications: Do not use if you are pregnant.$SQLTXT$, $SQLTXT$Known Adverse Reactions: Stop use if hypersensitivity/allergy occur. When using this product diuretic effect may occur. When using this product you may experience temporary gas and bloating.$SQLTXT$, $SQLTXT$Known Adverse Reactions: Stop use if hypersensitivity/allergy occurs. Some people may experience drowsiness. Exercise caution if operating heavy machinery, driving a motor vehicle or involved in activities requiring mental alertness.$SQLTXT$, $SQLTXT$Contra-Indications: Do not use this product if you are taking antibiotics or nitroglycerin. Do not use this product if you have bipolar disorder or bipolar spectrum disorder. Do not use if you are pregnant or breastfeeding.$SQLTXT$]::text[], translations = jsonb_set(coalesce(translations, '{}'::jsonb), '{fr}', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('contraindications', $SQLTXT$["Effets indésirables connus : De rares cas imprévisibles de lésions hépatiques associées à des produits contenant de l'extrait de thé vert ont été signalés (au Canada et à l'international). Un effet diurétique peut survenir. Peut causer des gaz et/ou des ballonnements temporaires. Cessez l'utilisation si une hypersensibilité/allergie survient.", "Contre-indications : N'utilisez pas ce produit si vous êtes enceinte, si vous allaitez ou si vous avez des antécédents de lupus érythémateux disséminé. N'utilisez pas si vous avez des difficultés à avaler.", "Contre-indications : N'utilisez pas si vous êtes enceinte.", "Effets indésirables connus : Cessez l'utilisation en cas d'hypersensibilité/allergie. Lors de l'utilisation de ce produit, un effet diurétique peut survenir. Lors de l'utilisation de ce produit, vous pourriez éprouver des gaz et des ballonnements temporaires.", "Effets indésirables connus : Cessez l'utilisation en cas d'hypersensibilité/allergie. Certaines personnes peuvent éprouver de la somnolence. Soyez prudent si vous utilisez de la machinerie lourde, conduisez un véhicule à moteur ou participez à des activités nécessitant de la vigilance mentale.", "Contre-indications : N'utilisez pas ce produit si vous prenez des antibiotiques ou de la nitroglycérine. N'utilisez pas ce produit si vous avez un trouble bipolaire ou un trouble du spectre bipolaire. N'utilisez pas si vous êtes enceinte ou si vous allaitez."]$SQLTXT$::jsonb)) WHERE slug = $SQLTXT$rubus-plicatus$SQLTXT$;
UPDATE public.herbs SET contraindications = ARRAY[$SQLTXT$Contra-Indications: Do not use if you are taking thiazide diuretics, cardiac glycosides, corticosteroids, stimulant laxatives or other medications which may aggravate electrolyte imbalance or if you are pregnant or breastfeeding, have hypokalemia, high blood pressure, or a kidney, liver.$SQLTXT$, $SQLTXT$Known Adverse Reactions: Hypersensitivity (e.g. allergy) has been known to occur; in which case, discontinue use.$SQLTXT$]::text[], translations = jsonb_set(coalesce(translations, '{}'::jsonb), '{fr}', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('contraindications', $SQLTXT$["Contre-indications : Ne pas utiliser si vous prenez des diurétiques thiazidiques, des glycosides cardiaques, des corticostéroïdes, des laxatifs stimulants ou d'autres médicaments susceptibles d'aggraver un déséquilibre électrolytique, ou si vous êtes enceinte ou allaitez, avez une hypokaliémie, une pression artérielle élevée, ou un trouble rénal.", "Réactions indésirables connues : L'hypersensibilité (p. ex. allergie) est reconnue comme pouvant survenir ; auquel cas, cessez l'utilisation."]$SQLTXT$::jsonb)) WHERE slug = $SQLTXT$citrus-wilsonii$SQLTXT$;
UPDATE public.herbs SET contraindications = ARRAY[$SQLTXT$Cautions and Warnings: If an allergic or allergy like reaction occurs, discontinue use. Discontinue use and consult your health care practitioner if any adverse reactions occur. Pregnant or lactating women should not take any supplements unless recommended by a health care practitioner.$SQLTXT$, $SQLTXT$Contra-Indications: People with a known allergy to seafood, or tomato should not take Imedeen Time Perfection.$SQLTXT$]::text[], translations = jsonb_set(coalesce(translations, '{}'::jsonb), '{fr}', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('contraindications', $SQLTXT$["Mises en garde et avertissements : En cas de réaction allergique ou de type allergique, cessez l'utilisation. Cessez l'utilisation et consultez votre professionnel de la santé si des réactions indésirables surviennent. Les femmes enceintes ou qui allaitent ne devraient pas prendre de suppléments à moins qu'ils soient recommandés par un professionnel de la santé.", "Contre-indications : Les personnes ayant une allergie connue aux fruits de mer ou à la tomate ne devraient pas prendre Imedeen Time Perfection."]$SQLTXT$::jsonb)) WHERE slug = $SQLTXT$lycopersicum-esculentum$SQLTXT$;
UPDATE public.herbs SET contraindications = ARRAY[$SQLTXT$Contra-Indications: Do not use if you are allergic to plants of the Asteraceae/Compositae/Daisy family. Do not use this product if you are taking antibiotics or nitroglycerin. Do not use if you are pregnant.$SQLTXT$, $SQLTXT$Known Adverse Reactions: Some people may experience drowsiness. Exercise caution if operating heavy machinery, driving a motor vehicle or involved in activities requiring mental alertness. May cause temporary gas and/or bloating. Stop use if hypersensitivity/allergy occurs.$SQLTXT$, $SQLTXT$Contra-Indications: Do not use this product if you are pregnant, breastfeeding or have a history of systemic lupus erythematosus.$SQLTXT$]::text[], translations = jsonb_set(coalesce(translations, '{}'::jsonb), '{fr}', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('contraindications', $SQLTXT$["Contre-indications : Ne pas utiliser si vous êtes allergique aux plantes de la famille des Asteraceae/Compositae/Daisy. Ne pas utiliser ce produit si vous prenez des antibiotiques ou de la nitroglycérine. Ne pas utiliser si vous êtes enceinte.", "Réactions indésirables connues : Certaines personnes peuvent ressentir de la somnolence. Faire preuve de prudence si vous utilisez de la machinerie lourde, conduisez un véhicule à moteur ou participez à des activités nécessitant de la vigilance mentale. Peut causer des gaz et/ou des ballonnements temporaires. Cesser l'utilisation en cas d'hypersensibilité/allergie.", "Contre-indications : Ne pas utiliser ce produit si vous êtes enceinte, si vous allaitez ou si vous avez des antécédents de lupus érythémateux disséminé."]$SQLTXT$::jsonb)) WHERE slug = $SQLTXT$capsicum-annuum-var-annuum$SQLTXT$;
UPDATE public.herbs SET contraindications = ARRAY[$SQLTXT$Contra-Indications: Do not use if you are pregnant of breastfeeding. Discontinue use if allergy such as itches or rash develops. Do not apply to open wound. Avoid contact with the eyes and mucous membranes. Do not tightly bandage.$SQLTXT$, $SQLTXT$Contra-Indications: If you are pregnant or breastfeeding, do not use this product.$SQLTXT$]::text[], translations = jsonb_set(coalesce(translations, '{}'::jsonb), '{fr}', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('contraindications', $SQLTXT$["Contre-indications : Ne pas utiliser si vous êtes enceinte ou si vous allaitez. Cesser l'utilisation si une allergie telle que des démangeaisons ou une éruption cutanée se développe. Ne pas appliquer sur une plaie ouverte. Éviter le contact avec les yeux et les muqueuses. Ne pas bander serré.", "Contre-indications : Si vous êtes enceinte ou si vous allaitez, ne pas utiliser ce produit."]$SQLTXT$::jsonb)) WHERE slug = $SQLTXT$piper-wallichii$SQLTXT$;
UPDATE public.herbs SET contraindications = ARRAY[$SQLTXT$Known Adverse Reactions: May cause nausea, abdominal pain, and/or diarrhea.$SQLTXT$, $SQLTXT$Contra-Indications: Do not use this product with other potassium-containing supplements or with potassium-containing salt-substitutes. Do not use if you are pregnant or breastfeeding. Do not use this product if you have had a heart attack/myocardial infarction.$SQLTXT$, $SQLTXT$Known Adverse Reactions: Rare, unpredictable cases of liver injury associated with green tea extract-containing products have been reported. Stop use if gastrointestinal discomfort occurs.$SQLTXT$, $SQLTXT$Known Adverse Reactions: Stop use if hypersensitivity occurs.$SQLTXT$, $SQLTXT$Known Adverse Reactions: Hypersensitivity has been known to occur. Rare, unpredictable cases of liver injury associated with green tea extract-containing products have been reported (in Canada and internationally).$SQLTXT$, $SQLTXT$Contra-Indications: If you have an immune-compromised condition (e.g. AIDS, lymphoma, patients undergoing long-term corticosteroid treatment), do not use this product. Do not use this product if you are pregnant or breastfeeding or if you have a history of systemic lupus erythematosus.$SQLTXT$]::text[], translations = jsonb_set(coalesce(translations, '{}'::jsonb), '{fr}', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('contraindications', $SQLTXT$["Réactions indésirables connues : Peut causer des nausées, des douleurs abdominales et/ou de la diarrhée.", "Contre-indications : Ne pas utiliser ce produit avec d'autres suppléments contenant du potassium ou avec des substituts de sel contenant du potassium. Ne pas utiliser si vous êtes enceinte ou si vous allaitez. Ne pas utiliser ce produit si vous avez subi une crise cardiaque/un infarctus du myocarde.", "Réactions indésirables connues : De rares cas imprévisibles de lésions hépatiques associés à des produits contenant de l'extrait de thé vert ont été signalés. Cesser l'utilisation en cas d'inconfort gastro-intestinal.", "Réactions indésirables connues : Cesser l'utilisation en cas d'hypersensibilité.", "Réactions indésirables connues : L'hypersensibilité a été signalée. De rares cas imprévisibles de lésions hépatiques associés à des produits contenant de l'extrait de thé vert ont été signalés (au Canada et à l'échelle internationale).", "Contre-indications : Si vous avez un état immunodéprimé (p. ex. SIDA, lymphome, patients sous traitement corticostéroïdien à long terme), ne pas utiliser ce produit. Ne pas utiliser ce produit si vous êtes enceinte ou si vous allaitez ou si vous avez des antécédents de lupus érythémateux disséminé."]$SQLTXT$::jsonb)) WHERE slug = $SQLTXT$brassica-oleracea-var-italica$SQLTXT$;
UPDATE public.herbs SET contraindications = ARRAY[$SQLTXT$Cautions and Warnings: For external use only. Avoid contact with eyes, mucous membranes; if this happens, rinse thoroughly with water. Avoid exposure of applied area to the sun. Hypersensitivity, rash and /or burning discomfort have been known to occur; in which case, discontinue use.$SQLTXT$, $SQLTXT$Contra-Indications: If you are pregnant or breastfeeding, do not use this product.$SQLTXT$, $SQLTXT$Contra-Indications: Do not use if you are pregnant or breastfeeding. Do not use if you have diarrhea, hemorrhagic diseases or heavy periods.$SQLTXT$]::text[], translations = jsonb_set(coalesce(translations, '{}'::jsonb), '{fr}', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('contraindications', $SQLTXT$["Mises en garde et précautions : Pour usage externe seulement. Éviter le contact avec les yeux et les muqueuses ; si cela se produit, rincer abondamment à l'eau. Éviter l'exposition de la zone traitée au soleil. Une hypersensibilité, une éruption cutanée ou un inconfort de type brûlure ont été rapportés ; dans ce cas, cesser l'utilisation.", "Contre-indications : Si vous êtes enceinte ou si vous allaitez, ne pas utiliser ce produit.", "Contre-indications : Ne pas utiliser si vous êtes enceinte ou si vous allaitez. Ne pas utiliser si vous avez de la diarrhée, des maladies hémorragiques ou des règles abondantes."]$SQLTXT$::jsonb)) WHERE slug = $SQLTXT$taraxacum-sinicum$SQLTXT$;
UPDATE public.herbs SET contraindications = ARRAY[$SQLTXT$Known Adverse Reactions: Adverse events occurring in less than 1% of cases include flatulence, constipation, and thirst. In some cases (rarely), pruritus, rash, angioedema may occur. In some cases (very rarely), anaphylactic reaction may occur.$SQLTXT$]::text[], translations = jsonb_set(coalesce(translations, '{}'::jsonb), '{fr}', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('contraindications', $SQLTXT$["Effets indésirables connus : Les événements indésirables survenant dans moins de 1 % des cas incluent les flatulences, la constipation et la soif. Dans certains cas (rarement), un prurit, une éruption cutanée ou un œdème de Quincke peuvent survenir. Dans certains cas (très rarement), une réaction anaphylactique peut survenir."]$SQLTXT$::jsonb)) WHERE slug = $SQLTXT$saccharomyces-boulardii-lyo$SQLTXT$;
