UPDATE public.herbs SET contraindications = ARRAY[$SQLTXT$Contra-Indications: Do not use this product if you are pregnant or breastfeeding.$SQLTXT$, $SQLTXT$Known Adverse Reactions: Rare, unpredictable cases of liver injury associated with green tea extract-containing products have been reported (in Canada and internationally).$SQLTXT$, $SQLTXT$Contra-Indications: If you are pregnant or breastfeeding, do not use.$SQLTXT$, $SQLTXT$Known Adverse Reactions: Stop use if you experience insomnia, anxiety or headaches.$SQLTXT$, $SQLTXT$Contra-Indications: Do not use this product if you are pregnant or breastfeeding. Do not use this product if you are taking health products that affect blood coagulation as this may increase the risk of spontaneous bleeding.$SQLTXT$, $SQLTXT$Known Adverse Reactions: Stop use if hypersensitivity/allergy occurs.$SQLTXT$]::text[], translations = jsonb_set(coalesce(translations, '{}'::jsonb), '{fr}', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('contraindications', $SQLTXT$["Contre-indications : Ne pas utiliser ce produit si vous êtes enceinte ou si vous allaitez.", "Réactions indésirables connues : Des cas rares et imprévisibles de lésions hépatiques associés à des produits contenant de l'extrait de thé vert ont été signalés (au Canada et à l'international).", "Contre-indications : Si vous êtes enceinte ou si vous allaitez, ne pas utiliser.", "Réactions indésirables connues : Cessez l'utilisation si vous présentez de l'insomnie, de l'anxiété ou des maux de tête.", "Contre-indications : Ne pas utiliser ce produit si vous êtes enceinte ou si vous allaitez. Ne pas utiliser ce produit si vous prenez des produits de santé qui affectent la coagulation sanguine, car cela pourrait augmenter le risque de saignements spontanés.", "Réactions indésirables connues : Cessez l'utilisation en cas d'hypersensibilité ou d'allergie."]$SQLTXT$::jsonb)) WHERE slug = $SQLTXT$paecilomyces-hepiali$SQLTXT$;
