UPDATE public.herbs SET contraindications = ARRAY[$SQLTXT$Known Adverse Reactions: Stop use if hypersensitivity/allergy occur. Diuretic effect may occur.$SQLTXT$, $SQLTXT$Known Adverse Reactions: Hypersensitivity (e.g. allergy) can occur, in which case, discontinue use.$SQLTXT$, $SQLTXT$Known Adverse Reactions: Diuretic effect may occur. Stop use if hypersensitivity/allergy occurs.$SQLTXT$, $SQLTXT$Contra-Indications: Do not use if you are pregnant.$SQLTXT$, $SQLTXT$Known Adverse Reactions: Hypersensitivity (e.g. allergy) can occur, in which case, discontinue use. Discontinue use in case of gastrointestinal upsets, such as abdominal cramps, nausea, vomiting, diarrhea. Diuretic effect may occur.$SQLTXT$]::text[], translations = jsonb_set(coalesce(translations, '{}'::jsonb), '{fr}', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('contraindications', $SQLTXT$["Réactions indésirables connues : Cesser l'utilisation en cas d'hypersensibilité ou d'allergie. Un effet diurétique peut survenir.", "Réactions indésirables connues : Une hypersensibilité (p. ex. allergie) peut survenir, auquel cas il faut cesser l'utilisation.", "Réactions indésirables connues : Un effet diurétique peut survenir. Cesser l'utilisation en cas d'hypersensibilité ou d'allergie.", "Contre-indications : Ne pas utiliser si vous êtes enceinte.", "Réactions indésirables connues : Une hypersensibilité (p. ex. allergie) peut survenir, auquel cas il faut cesser l'utilisation. Cesser l'utilisation en cas de troubles gastro-intestinaux, tels que crampes abdominales, nausées, vomissements, diarrhée. Un effet diurétique peut survenir."]$SQLTXT$::jsonb)) WHERE slug = $SQLTXT$sambucus-nigra-subsp-nigra$SQLTXT$;
