UPDATE public.herb_faqs SET answer = $SQLTXT$Contra-Indications: If you are pregnant or breastfeeding, do not use this product. Contra-Indications: Do not use this product if you are pregnant or breastfeeding. Contra-Indications: Do not use if you are pregnant or breastfeeding or if you have gastric or duodenal ulcer. Do not use if you are taking blood thinners, medications that reduce stomach acid or prevent or lessen seizures. These cautions come from the product labels and monographs attached to this entry.$SQLTXT$, translations = coalesce(translations, '{}'::jsonb) || jsonb_build_object('fr', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('answer', $SQLTXT$"Contre-indications : Si vous êtes enceinte ou si vous allaitez, ne pas utiliser ce produit. Contre-indications : Ne pas utiliser ce produit si vous êtes enceinte ou si vous allaitez. Contre-indications : Ne pas utiliser si vous êtes enceinte ou si vous allaitez ou si vous avez un ulcère gastrique ou duodénal. Ne pas utiliser si vous prenez des anticoagulants, des médicaments qui réduisent l'acidité gastrique ou qui préviennent ou atténuent les convulsions. Ces mises en garde proviennent des étiquettes et des monographies rattachées à cette fiche."$SQLTXT$::jsonb)) WHERE id = $SQLTXT$f1c8bf48-66e2-4394-ab51-02fe952049a8$SQLTXT$::uuid;
