UPDATE public.herb_faqs SET answer = $SQLTXT$Contra-Indications: Do not use if pregnant or breastfeeding. Do not exceed recommended dose. Do not use if you are trying to conceive. Do not use if you have diabetes or hypoglycaemia. These cautions come from the product labels and monographs attached to this entry.$SQLTXT$, translations = coalesce(translations, '{}'::jsonb) || jsonb_build_object('fr', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('answer', $SQLTXT$"Contre-indications : Ne pas utiliser si vous êtes enceinte ou si vous allaitez. Ne pas dépasser la dose recommandée. Ne pas utiliser si vous tentez de concevoir. Ne pas utiliser si vous avez le diabète ou une hypoglycémie. Ces mises en garde proviennent des étiquettes et des monographies rattachées à cette fiche."$SQLTXT$::jsonb)) WHERE id = $SQLTXT$49602267-07b2-4003-a454-edc4cd679e75$SQLTXT$::uuid;
UPDATE public.herb_faqs SET answer = $SQLTXT$Contra-Indications: If you experience gastrointestinal tract irritation and/or discomfort (e.g. nausea and vomiting), discontinue use. Do not use if you are allergic to anethole or plants of the Apiaceae/Carrot family. Do not inhale. If you are pregnant or breastfeeding do not use this product. Known Adverse Reactions: Hypersensitivity (e.g. allergy) has been known to occur; in which case, discontinue use. Some people may experience gastroesophageal reflux. Some people may experience drowsiness. These cautions come from the product labels and monographs attached to this entry.$SQLTXT$, translations = coalesce(translations, '{}'::jsonb) || jsonb_build_object('fr', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('answer', $SQLTXT$"Contre-indications : Si vous éprouvez une irritation et/ou un malaise gastro-intestinal (p. ex. nausées et vomissements), cessez l'utilisation. N'utilisez pas si vous êtes allergique à l'anéthole ou aux plantes de la famille des Apiaceae/Carotte. Ne pas inhaler. Si vous êtes enceinte ou si vous allaitez, n'utilisez pas ce produit. Réactions indésirables connues : Une hypersensibilité (p. ex. allergie) a été signalée ; le cas échéant, cessez l'utilisation. Certaines personnes peuvent éprouver un reflux gastro-œsophagien. Certaines personnes peuvent éprouver de la somnolence. Ces mises en garde proviennent des étiquettes et des monographies rattachées à cette fiche."$SQLTXT$::jsonb)) WHERE id = $SQLTXT$eada5af3-4434-4dc3-b4b3-9a5ff5bd219d$SQLTXT$::uuid;
UPDATE public.herb_faqs SET answer = $SQLTXT$Contra-Indications: Do not use if you are pregnant, breastfeeding or attempting to conceive unless you have consulted with a health care practitioner. Do not use if you have alllergies to Asteraceae/Compositae (Daisy family). Contra-Indications: Do not use if you are pregnant or breastfeeding. Do not use if you have an allergy to Asteraceae/ Compositae (daisy) family. Do not use if you have a bile duct obstruction. Known Adverse Reactions: Some people may experience drowsiness. Exercise caution if operating heavy machinery, driving a motor vehicle or involved in activities requiring mental alertness. Hypersensitivity/allergy is known to occur, in which case, discontinue use. These cautions come from the product labels and monographs attached to this entry.$SQLTXT$, translations = coalesce(translations, '{}'::jsonb) || jsonb_build_object('fr', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('answer', $SQLTXT$"Contre-indications : Ne pas utiliser si vous êtes enceinte, si vous allaitez ou si vous tentez de concevoir, à moins d'avoir consulté un professionnel de la santé. Ne pas utiliser si vous avez des allergies aux Asteraceae/Compositae (famille des marguerites). Contre-indications : Ne pas utiliser si vous êtes enceinte ou si vous allaitez. Ne pas utiliser si vous avez une allergie à la famille des Asteraceae/Compositae (marguerites). Ne pas utiliser si vous avez une obstruction des voies biliaires. Effets indésirables connus : Certaines personnes peuvent ressentir de la somnolence. Faites preuve de prudence si vous utilisez de la machinerie lourde, si vous conduisez un véhicule automobile ou si vous participez à des activités exigeant de la vigilance mentale. Une hypersensibilité/allergie est connue pour survenir, auquel cas cessez l'utilisation. Ces mises en garde proviennent des étiquettes et des monographies rattachées à cette fiche."$SQLTXT$::jsonb)) WHERE id = $SQLTXT$56a7dfe6-2eb3-4929-a63c-7c1bf85b3012$SQLTXT$::uuid;
UPDATE public.herb_faqs SET answer = $SQLTXT$Contra-Indications: Do not use this product if you have hypokalemia, high blood pressure, or a kidney or cardiovascular disorder. Contra-Indications: If you are pregnant or breastfeeding, do not use this product. Contra-Indications: Do not use if you are pregnant or breastfeeding. Do not use if you are taking heart medications, corticosteroids, stimulant laxatives, or other health products that may contribute electrolyte imbalance. These cautions come from the product labels and monographs attached to this entry.$SQLTXT$, translations = coalesce(translations, '{}'::jsonb) || jsonb_build_object('fr', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('answer', $SQLTXT$"Contre-indications : N'utilisez pas ce produit si vous avez une hypokaliémie, une pression artérielle élevée ou un trouble rénal ou cardiovasculaire. Contre-indications : Si vous êtes enceinte ou allaitez, n'utilisez pas ce produit. Contre-indications : N'utilisez pas si vous êtes enceinte ou allaitez. N'utilisez pas si vous prenez des médicaments pour le cœur, des corticoïdes, des laxatifs stimulants ou d'autres produits de santé susceptibles de contribuer à un déséquilibre électrolytique. Ces mises en garde proviennent des étiquettes et des monographies rattachées à cette fiche."$SQLTXT$::jsonb)) WHERE id = $SQLTXT$71379ebb-a485-4696-a3d3-b6b0dad5ba6f$SQLTXT$::uuid;
UPDATE public.herb_faqs SET answer = $SQLTXT$Known Adverse Reactions: Hypersensitivity has been known to occur. Rare, unpredictable cases of liver injury associated with green tea extract-containing products have been reported (in Canada and internationally). Stop use if you experience irritability or insomnia. Contra-Indications: Do not use this product if you have high blood pressure. Do not use this product if you have bipolar disorder or bipolar spectrum disorder. Do not use this product if you are pregnant or breastfeeding. Contra-Indications: Do not use this product if you have an immune-compromised condition (e.g. AIDS, lymphoma, patients undergoing long-term corticosteroid treatment). These cautions come from the product labels and monographs attached to this entry.$SQLTXT$, translations = coalesce(translations, '{}'::jsonb) || jsonb_build_object('fr', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('answer', $SQLTXT$"Effets indésirables connus : Une hypersensibilité a été signalée. Des cas rares et imprévisibles de lésions hépatiques associés à des produits contenant de l'extrait de thé vert ont été rapportés (au Canada et à l'international). Cessez l'utilisation si vous ressentez de l'irritabilité ou de l'insomnie. Contre-indications : Ne pas utiliser ce produit si vous avez de l'hypertension artérielle. Ne pas utiliser ce produit si vous avez un trouble bipolaire ou un trouble du spectre bipolaire. Ne pas utiliser ce produit si vous êtes enceinte ou si vous allaitez. Contre-indications : Ne pas utiliser ce produit si vous avez une immunodépression (p. ex. SIDA, lymphome, patients sous corticothérapie à long terme). Ces mises en garde proviennent des étiquettes et des monographies rattachées à cette fiche."$SQLTXT$::jsonb)) WHERE id = $SQLTXT$a3c2de8f-16c5-4beb-b2e5-643be04c22ce$SQLTXT$::uuid;
UPDATE public.herb_faqs SET answer = $SQLTXT$Known Adverse Reactions: Hypersensitivity (e.g. allergy) can occur, in which case, discontinue use. Discontinue use in case of gastrointestinal upsets, such as abdominal cramps, nausea, vomiting, diarrhea. Contra-Indications: Do not use if you are pregnant or breastfeeding. Do not use if you have a seizure disorder (e.g. epilepsy). Do not use if you have a history of systemic lupus erythematosus. Known Adverse Reactions: Rare, unpredictable cases of liver injury associated with green tea extract-containing products have been reported (in Canada and internationally). These cautions come from the product labels and monographs attached to this entry.$SQLTXT$, translations = coalesce(translations, '{}'::jsonb) || jsonb_build_object('fr', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('answer', $SQLTXT$"Réactions indésirables connues : Une hypersensibilité (p. ex. allergie) peut survenir, auquel cas cessez l'utilisation. Cessez l'utilisation en cas de troubles gastro-intestinaux, tels que crampes abdominales, nausées, vomissements, diarrhée. Contre-indications : N'utilisez pas si vous êtes enceinte ou allaitez. N'utilisez pas si vous avez un trouble convulsif (p. ex. épilepsie). N'utilisez pas si vous avez des antécédents de lupus érythémateux disséminé. Réactions indésirables connues : De rares cas imprévisibles de lésions hépatiques associés à des produits contenant de l'extrait de thé vert ont été signalés (au Canada et à l'échelle internationale). Ces mises en garde proviennent des étiquettes et des monographies rattachées à cette fiche."$SQLTXT$::jsonb)) WHERE id = $SQLTXT$daed9a29-1da6-430b-886e-b873a195b079$SQLTXT$::uuid;
UPDATE public.herb_faqs SET answer = $SQLTXT$Contra-Indications: Avoid using if you have a hormone sensitive cancer or condition, such as uterine, ovarian or breast cancer, fibroids, or endometriosis. Contra-Indications: Do not take if currently taking Warfarin or other anticoagulant medications, MAOI's, if you are pregnant or breastfeeding, if you have stomach or intestinal ulcers, if you are allergic to artichoke or other plants of the Asteraceae/Compositae/Daisy family. Known Adverse Reactions: Some people may experience headaches. Hypersensitivity has been known to occur in which case, discontinue use. These cautions come from the product labels and monographs attached to this entry.$SQLTXT$, translations = coalesce(translations, '{}'::jsonb) || jsonb_build_object('fr', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('answer', $SQLTXT$"Contre-indications : Éviter l'utilisation en cas de cancer ou d'affection hormono-dépendante, comme le cancer de l'utérus, des ovaires ou du sein, les fibromes ou l'endométriose. Contre-indications : Ne pas prendre si vous prenez actuellement de la warfarine ou d'autres anticoagulants, des IMAO, si vous êtes enceinte ou allaitez, si vous avez des ulcères gastriques ou intestinaux, si vous êtes allergique à l'artichaut ou à d'autres plantes de la famille des Asteraceae/Compositae/Daisy. Réactions indésirables connues : Certaines personnes peuvent ressentir des maux de tête. Une hypersensibilité a été signalée, auquel cas il faut cesser l'utilisation. Ces mises en garde proviennent des étiquettes et des monographies rattachées à cette fiche."$SQLTXT$::jsonb)) WHERE id = $SQLTXT$e1a8d76f-58e5-4327-9a2f-e56c206969ef$SQLTXT$::uuid;
UPDATE public.herb_faqs SET answer = $SQLTXT$Known Adverse Reactions: Diuretic effect may occur. Contra-Indications: Do not use this product if you are taking thiazide diuretics, cardiac glycosides, corticosteroids, stimulant laxatives or other medications which may aggravate electrolyte imbalance. Do not use if you are pregnant or breastfeeding, or if you are trying to conceive. These cautions come from the product labels and monographs attached to this entry.$SQLTXT$, translations = coalesce(translations, '{}'::jsonb) || jsonb_build_object('fr', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('answer', $SQLTXT$"Effets indésirables connus : Un effet diurétique peut survenir. Contre-indications : Ne pas utiliser ce produit si vous prenez des diurétiques thiazidiques, des glycosides cardiotoniques, des corticostéroïdes, des laxatifs stimulants ou d'autres médicaments susceptibles d'aggraver un déséquilibre électrolytique. Ne pas utiliser si vous êtes enceinte ou si vous allaitez, ou si vous essayez de concevoir. Ces mises en garde proviennent des étiquettes et des monographies rattachées à cette fiche."$SQLTXT$::jsonb)) WHERE id = $SQLTXT$eeb42459-511c-4b83-9531-bc054582ffc0$SQLTXT$::uuid;
UPDATE public.herb_faqs SET answer = $SQLTXT$Contra-Indications: Do not use if you are pregnant or breastfeeding. Do not use if you have a heart condition or a blood clotting disorder, or if you are taking anticoagulants or immune suppressant. Do not use if you have liver or gallbladder disorders or if you develop symptoms of liver trouble. Known Adverse Reactions: Hypersensitivity (e.g. allergy) has been known to occur; in which case, discontinue use. Contra-Indications: Do not use if you are pregnant or breastfeeding. Do not use if you are allergic to anethole or plants of the Apiaceae/Carrot family. Do not use if you have liver or gall bladder disorders. These cautions come from the product labels and monographs attached to this entry.$SQLTXT$, translations = coalesce(translations, '{}'::jsonb) || jsonb_build_object('fr', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('answer', $SQLTXT$"Contre-indications : N'utilisez pas si vous êtes enceinte ou si vous allaitez. N'utilisez pas si vous avez un trouble cardiaque ou un trouble de la coagulation, ou si vous prenez des anticoagulants ou des immunosuppresseurs. N'utilisez pas si vous avez des troubles hépatiques ou biliaires ou si vous développez des symptômes de trouble hépatique. Réactions indésirables connues : Des cas d'hypersensibilité (p. ex. allergie) ont été signalés ; le cas échéant, cessez l'utilisation. Contre-indications : N'utilisez pas si vous êtes enceinte ou si vous allaitez. N'utilisez pas si vous êtes allergique à l'anéthole ou aux plantes de la famille des Apiaceae/Carottes. N'utilisez pas si vous avez des troubles hépatiques ou biliaires. Ces mises en garde proviennent des étiquettes et des monographies rattachées à cette fiche."$SQLTXT$::jsonb)) WHERE id = $SQLTXT$c921ec4d-f6ad-48c4-b83e-37a835f0d4ee$SQLTXT$::uuid;
UPDATE public.herb_faqs SET answer = $SQLTXT$Known Adverse Reactions: When using this product diuretic effect may occur. Stop use if hypersensitivity/allergy occurs. Contra-Indications: Do not use if you have high blood pressure. Do not use if you are having a surgery. Do not use if you are taking blood thinners or other health products that affect blood coagulation. Do not use if you are pregnant or breastfeeding. Do not use if you have a bile duct obstruction. Contra-Indications: According to Traditional Chinese Medicine, do not use this product in cases of exterior excess, qi stagnation, damp obstruction, food stagnation, yin deficiency with heat signs, or skin lesions in their early stages or where there is a heat toxin. These cautions come from the product labels and monographs attached to this entry.$SQLTXT$, translations = coalesce(translations, '{}'::jsonb) || jsonb_build_object('fr', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('answer', $SQLTXT$"Réactions indésirables connues : L'utilisation de ce produit peut provoquer un effet diurétique. Cesser l'utilisation en cas d'hypersensibilité/allergie. Contre-indications : Ne pas utiliser si vous avez une tension artérielle élevée. Ne pas utiliser si vous subissez une intervention chirurgicale. Ne pas utiliser si vous prenez des anticoagulants ou d'autres produits de santé qui affectent la coagulation sanguine. Ne pas utiliser si vous êtes enceinte ou si vous allaitez. Ne pas utiliser si vous avez une obstruction des voies biliaires. Contre-indications : Selon la médecine traditionnelle chinoise, ne pas utiliser ce produit en cas d'excès externe, de stagnation du qi, d'obstruction par l'humidité, de stagnation alimentaire, de vide de yin avec signes de chaleur, ou de lésions cutanées à leurs stades précoces ou en présence d'une toxine de chaleur. Ces mises en garde proviennent des étiquettes et des monographies rattachées à cette fiche."$SQLTXT$::jsonb)) WHERE id = $SQLTXT$c242f639-81ff-4325-bc24-aed25f13fc5b$SQLTXT$::uuid;
UPDATE public.herb_faqs SET answer = $SQLTXT$Known Adverse Reactions: May cause nausea, abdominal pain, and/or diarrhea. Contra-Indications: Do not use this product with other potassium-containing supplements or with potassium-containing salt-substitutes. Do not use if you are pregnant or breastfeeding. Do not use this product if you have had a heart attack/myocardial infarction. Known Adverse Reactions: Rare, unpredictable cases of liver injury associated with green tea extract-containing products have been reported. Stop use if gastrointestinal discomfort occurs. These cautions come from the product labels and monographs attached to this entry.$SQLTXT$, translations = coalesce(translations, '{}'::jsonb) || jsonb_build_object('fr', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('answer', $SQLTXT$"Réactions indésirables connues : Peut causer des nausées, des douleurs abdominales et/ou de la diarrhée. Contre-indications : Ne pas utiliser ce produit avec d'autres suppléments contenant du potassium ou avec des substituts de sel contenant du potassium. Ne pas utiliser si vous êtes enceinte ou si vous allaitez. Ne pas utiliser ce produit si vous avez subi une crise cardiaque/un infarctus du myocarde. Réactions indésirables connues : De rares cas imprévisibles de lésions hépatiques associés à des produits contenant de l'extrait de thé vert ont été signalés. Cesser l'utilisation en cas d'inconfort gastro-intestinal. Ces mises en garde proviennent des étiquettes et des monographies rattachées à cette fiche."$SQLTXT$::jsonb)) WHERE id = $SQLTXT$08418754-04f7-41df-8a58-cbf64845aab1$SQLTXT$::uuid;
UPDATE public.herb_faqs SET answer = $SQLTXT$Known Adverse Reactions: Stop use if hypersensitivity occurs. Stop use if hypersensitivity/allergy occurs. Contra-Indications: Do not use if you are pregnant, breastfeeding or attempting to conceive unless you have consulted with a health care practitioner/health care provider/health care professional/doctor/physician. Do not use if you have high blood pressure. Contra-Indications: Do not use if you are pregnant or breastfeeding. Do not use if you have a history of systemic lupus erythematosus. These cautions come from the product labels and monographs attached to this entry.$SQLTXT$, translations = coalesce(translations, '{}'::jsonb) || jsonb_build_object('fr', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('answer', $SQLTXT$"Réactions indésirables connues : Cesser l'utilisation en cas d'hypersensibilité. Cesser l'utilisation en cas d'hypersensibilité/allergie. Contre-indications : Ne pas utiliser si vous êtes enceinte, si vous allaitez ou si vous tentez de concevoir, sauf après consultation d'un praticien de la santé/un fournisseur de soins de santé/un professionnel de la santé/un médecin. Ne pas utiliser si vous avez une tension artérielle élevée. Contre-indications : Ne pas utiliser si vous êtes enceinte ou si vous allaitez. Ne pas utiliser si vous avez des antécédents de lupus érythémateux disséminé. Ces mises en garde proviennent des étiquettes et des monographies rattachées à cette fiche."$SQLTXT$::jsonb)) WHERE id = $SQLTXT$fab68289-43b1-4f33-aa6a-c586b8c7842a$SQLTXT$::uuid;
UPDATE public.herb_faqs SET answer = $SQLTXT$Contra-Indications: Do not use if you are pregnant or breastfeeding. Known Adverse Reactions: Laxative effect may occur, in which case, discontinue use. Hypersensitivity, such as an allergy, has been known to occur; in which case, discontinue use. Allergic reactions can occur in people allergic to plants of the Oleacea family, Arecaeae family or acai. Known Adverse Reactions: Some people may experience mild gastrointestinal disturbances. These cautions come from the product labels and monographs attached to this entry.$SQLTXT$, translations = coalesce(translations, '{}'::jsonb) || jsonb_build_object('fr', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('answer', $SQLTXT$"Contre-indications : Ne pas utiliser si vous êtes enceinte ou si vous allaitez. Réactions indésirables connues : Un effet laxatif peut se produire, auquel cas cessez l'utilisation. Une hypersensibilité, telle qu'une allergie, a été signalée ; dans ce cas, cessez l'utilisation. Des réactions allergiques peuvent survenir chez les personnes allergiques aux plantes de la famille des Oleacea, de la famille des Arecaeae ou à l'açaï. Réactions indésirables connues : Certaines personnes peuvent éprouver de légers troubles gastro-intestinaux. Ces mises en garde proviennent des étiquettes et des monographies rattachées à cette fiche."$SQLTXT$::jsonb)) WHERE id = $SQLTXT$2867827a-15b6-4de5-949c-ce639944c9eb$SQLTXT$::uuid;
UPDATE public.herb_faqs SET answer = $SQLTXT$Known Adverse Reactions: Stop use if hypersensitivity/allergy occurs. Rare, unpredictable cases of liver injury associated with green tea extract-containing products have been reported (in Canada and internationally). Contra-Indications: According to Traditional Chinese Medicine, do not use this product in cases of exterior excess, qi stagnation, damp obstruction, food stagnation, yin deficiency with heat signs, or skin lesions in their early stages or where there is a heat toxin. Contra-Indications: If you have an immune-compromised condition (e.g. AIDS, lymphoma, patients undergoing long-term corticosteroid treatment), do not use this product. Do not use if you are allergic to Anatole, to plants of Apiceae/Carrot family. These cautions come from the product labels and monographs attached to this entry.$SQLTXT$, translations = coalesce(translations, '{}'::jsonb) || jsonb_build_object('fr', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('answer', $SQLTXT$"Réactions indésirables connues : Cesser l'utilisation en cas d'hypersensibilité/allergie. De rares cas imprévisibles de lésions hépatiques associés à des produits contenant de l'extrait de thé vert ont été signalés (au Canada et à l'international). Contre-indications : Selon la médecine traditionnelle chinoise, ne pas utiliser ce produit en cas d'excès externe, de stagnation du qi, d'obstruction par l'humidité, de stagnation alimentaire, de vide de yin avec signes de chaleur, ou de lésions cutanées à leurs stades précoces ou en présence de toxine de chaleur. Contre-indications : Si vous avez un état immunodéprimé (p. ex. SIDA, lymphome, patients sous corticothérapie à long terme), ne pas utiliser ce produit. Ne pas utiliser si vous êtes allergique à l'Anatole, aux plantes de la famille des Apiaceae/Carotte. Ces mises en garde proviennent des étiquettes et des monographies rattachées à cette fiche."$SQLTXT$::jsonb)) WHERE id = $SQLTXT$b1eafbbc-8492-4ea0-ba75-1830e8d9f68e$SQLTXT$::uuid;
UPDATE public.herb_faqs SET answer = $SQLTXT$Known Adverse Reactions: Hypersensitivity (e.g. allergy) has been known to occur; in which case discontinue use. Zinc supplementation can cause copper deficiency. Contra-Indications: Do not use if you are allergic to plants of the Asteraceae/Compositae/Daisy family. If you have an immune-compromised condition (e.g. AIDS, lymphoma, patients undergoing long-term corticosteroid treatment), do not use this product. Do not use if you have stomach ulcers. These cautions come from the product labels and monographs attached to this entry.$SQLTXT$, translations = coalesce(translations, '{}'::jsonb) || jsonb_build_object('fr', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('answer', $SQLTXT$"Réactions indésirables connues : Une hypersensibilité (p. ex. allergie) a été signalée ; dans ce cas, cesser l'utilisation. La supplémentation en zinc peut causer une carence en cuivre. Contre-indications : Ne pas utiliser si vous êtes allergique aux plantes de la famille des Asteraceae/Compositae/Marguerite. Si vous avez un état immunodéprimé (p. ex. SIDA, lymphome, patients sous corticothérapie à long terme), ne pas utiliser ce produit. Ne pas utiliser si vous avez des ulcères d'estomac. Ces mises en garde proviennent des étiquettes et des monographies rattachées à cette fiche."$SQLTXT$::jsonb)) WHERE id = $SQLTXT$9c88ca10-435f-4de2-9d1e-7a651115c025$SQLTXT$::uuid;
UPDATE public.herb_faqs SET answer = $SQLTXT$Contra-Indications: Do not use if you are allergic to plants of the Asteraceae/Compositae/Daisy family. Do not use this product if you are taking antibiotics or nitroglycerin. Do not use if you are pregnant. Known Adverse Reactions: Some people may experience drowsiness. Exercise caution if operating heavy machinery, driving a motor vehicle or involved in activities requiring mental alertness. May cause temporary gas and/or bloating. Stop use if hypersensitivity/allergy occurs. Contra-Indications: Do not use this product if you are pregnant, breastfeeding or have a history of systemic lupus erythematosus. These cautions come from the product labels and monographs attached to this entry.$SQLTXT$, translations = coalesce(translations, '{}'::jsonb) || jsonb_build_object('fr', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('answer', $SQLTXT$"Contre-indications : Ne pas utiliser si vous êtes allergique aux plantes de la famille des Asteraceae/Compositae/Daisy. Ne pas utiliser ce produit si vous prenez des antibiotiques ou de la nitroglycérine. Ne pas utiliser si vous êtes enceinte. Réactions indésirables connues : Certaines personnes peuvent ressentir de la somnolence. Faire preuve de prudence si vous utilisez de la machinerie lourde, conduisez un véhicule à moteur ou participez à des activités nécessitant de la vigilance mentale. Peut causer des gaz et/ou des ballonnements temporaires. Cesser l'utilisation en cas d'hypersensibilité/allergie. Contre-indications : Ne pas utiliser ce produit si vous êtes enceinte, si vous allaitez ou si vous avez des antécédents de lupus érythémateux disséminé. Ces mises en garde proviennent des étiquettes et des monographies rattachées à cette fiche."$SQLTXT$::jsonb)) WHERE id = $SQLTXT$59b34511-3793-426a-9ad1-4806fd3bf221$SQLTXT$::uuid;
UPDATE public.herb_faqs SET answer = $SQLTXT$Contra-Indications: Do not use if you are pregnant or breastfeeding and/or you have abnormal constrictions of the gastrointestinal tract, potential or existing intestinal blockage, atonic bowel, appendicitis, inflammatory colon disease such as Crohn's disease or ulcerative colitis. Known Adverse Reactions: Hypersensitivity is known to occur, in which case, discontinue use. Contra-Indications: Do not use if pregnant or breastfeeding. These cautions come from the product labels and monographs attached to this entry.$SQLTXT$, translations = coalesce(translations, '{}'::jsonb) || jsonb_build_object('fr', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('answer', $SQLTXT$"Contre-indications : Ne pas utiliser si vous êtes enceinte ou si vous allaitez et/ou si vous présentez des constrictions anormales du tractus gastro-intestinal, une occlusion intestinale potentielle ou existante, un intestin atone, une appendicite, une maladie inflammatoire du côlon telle que la maladie de Crohn ou la colite ulcéreuse. Réactions indésirables connues : Une hypersensibilité est connue pour survenir, auquel cas il faut cesser l'utilisation. Contre-indications : Ne pas utiliser si vous êtes enceinte ou si vous allaitez. Ces mises en garde proviennent des étiquettes et des monographies rattachées à cette fiche."$SQLTXT$::jsonb)) WHERE id = $SQLTXT$4e1dfb04-a836-4309-8bed-d2c7ca9a5106$SQLTXT$::uuid;
UPDATE public.herb_faqs SET answer = $SQLTXT$Contra-Indications: Do no use if you are pregnant or breastfeeding or if you are hypersensitive to caffeine or tannins. Contra-Indications: Do not use if you are pregnant or breastfeeding, if you are allergic/hypersensitive to bee products or polen, if you have a history of systemic lupus erythematosus, if you are taking corticosteroids or cyclosporine, and/or if you have sickle cell anemia. Contra-Indications: Do not use if you are taking thiazide diuretics, cardiac glycosides, corticosteroids, stimulant laxatives or other medications which may aggravate electrolyte imbalance or if you are pregnant or breastfeeding, have hypokalemia, high blood pressure, or a kidney, liver. These cautions come from the product labels and monographs attached to this entry.$SQLTXT$, translations = coalesce(translations, '{}'::jsonb) || jsonb_build_object('fr', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('answer', $SQLTXT$"Contre-indications : Ne pas utiliser si vous êtes enceinte ou si vous allaitez ou si vous êtes hypersensible à la caféine ou aux tanins. Contre-indications : Ne pas utiliser si vous êtes enceinte ou si vous allaitez, si vous êtes allergique/hypersensible aux produits d'abeille ou au pollen, si vous avez des antécédents de lupus érythémateux disséminé, si vous prenez des corticostéroïdes ou de la cyclosporine et/ou si vous souffrez d'anémie falciforme, d'un déficit en glucose-6-phosphate. Contre-indications : Ne pas utiliser si vous prenez des diurétiques thiazidiques, des glycosides cardiotoniques, des corticostéroïdes, des laxatifs stimulants ou d'autres médicaments susceptibles d'aggraver un déséquilibre électrolytique, ou si vous êtes enceinte ou si vous allaitez, avez une hypokaliémie, une hypertension artérielle ou une maladie rénale. Ces mises en garde proviennent des étiquettes et des monographies rattachées à cette fiche."$SQLTXT$::jsonb)) WHERE id = $SQLTXT$fdce99f4-9dd3-4622-b0ff-0cfad25a07c8$SQLTXT$::uuid;
UPDATE public.herb_faqs SET answer = $SQLTXT$Contra-Indications: Do not use if you are pregnant or breastfeeding. Known Adverse Reactions: People sensitive to nicotinic acid may experience flushing of the skin that is generally mild and transient. Hypersensitivity (e.g. allergy) has been known to occur; in which case, discontinue use. Contra-Indications: Hypersensitivity (e.g. allergy) has been known to occur; in which case, discontinue use. These cautions come from the product labels and monographs attached to this entry.$SQLTXT$, translations = coalesce(translations, '{}'::jsonb) || jsonb_build_object('fr', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('answer', $SQLTXT$"Contre-indications : Ne pas utiliser si vous êtes enceinte ou si vous allaitez. Réactions indésirables connues : Les personnes sensibles à l'acide nicotinique peuvent éprouver un flushing cutané généralement léger et transitoire. Une hypersensibilité (p. ex. allergie) a été signalée ; dans ce cas, cessez l'utilisation. Contre-indications : Une hypersensibilité (p. ex. allergie) a été signalée ; dans ce cas, cessez l'utilisation. Ces mises en garde proviennent des étiquettes et des monographies rattachées à cette fiche."$SQLTXT$::jsonb)) WHERE id = $SQLTXT$36aa7bc9-73ad-441d-812e-339ee35924ee$SQLTXT$::uuid;
UPDATE public.herb_faqs SET answer = $SQLTXT$Contra-Indications: Do not use, if you are pregnant or breastfeeding. Do not use if you are allergic to plants of the Asteraceae/Compositae/Daisy family. Do not use if you have difficulty swallowing. Contra-Indications: Do not use if you are taking health products that affect blood coagulation (e.g. blood thinners, clotting factor replacements, acetylsalicylic acid, ibuprofen, fish oils, vitamin E) as this may increase the risk of spontaneous bleeding. Contra-Indications: If you are pregnant, do not use this product. Do not use this product if you have gastrointestinal ulceration or obstruction. Do not use if you have diabetes. These cautions come from the product labels and monographs attached to this entry.$SQLTXT$, translations = coalesce(translations, '{}'::jsonb) || jsonb_build_object('fr', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('answer', $SQLTXT$"Contre-indications : Ne pas utiliser si vous êtes enceinte ou allaitez. Ne pas utiliser si vous êtes allergique aux plantes de la famille des Asteraceae/Compositae/marguerites. Ne pas utiliser si vous avez de la difficulté à avaler. Contre-indications : Ne pas utiliser si vous prenez des produits de santé qui influent sur la coagulation sanguine (p. ex. anticoagulants, facteurs de coagulation de remplacement, acide acétylsalicylique, ibuprofène, huiles de poisson, vitamine E), car cela peut augmenter le risque de saignement spontané. Contre-indications : Si vous êtes enceinte, ne pas utiliser ce produit. Ne pas utiliser ce produit si vous avez une ulcération ou une obstruction gastro-intestinale. Ne pas utiliser si vous avez du diabète. Ces mises en garde proviennent des étiquettes et des monographies rattachées à cette fiche."$SQLTXT$::jsonb)) WHERE id = $SQLTXT$bcc76659-d091-4eb4-b396-dd057e6c84e7$SQLTXT$::uuid;
UPDATE public.herb_faqs SET answer = $SQLTXT$Contra-Indications: If you have bipolar disorder or bipolar spectrum disorder, do not use this product. Known Adverse Reactions: May cause a flushing, tingling and/or prickling sensation of the skin, in which case, reduce the dose. If you experience irritability or insomnia, discontinue use. Hypersensitivity/allergy is known to occur, in which case discontinue use. Contra-Indications: Do not use this product with other potassium-containing supplements or with potassium-containing salt-substitutes. These cautions come from the product labels and monographs attached to this entry.$SQLTXT$, translations = coalesce(translations, '{}'::jsonb) || jsonb_build_object('fr', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('answer', $SQLTXT$"Contre-indications : Si vous avez un trouble bipolaire ou un trouble du spectre bipolaire, ne pas utiliser ce produit. Réactions indésirables connues : Peut causer une sensation de bouffées de chaleur, de picotement et/ou de fourmillement de la peau ; dans ce cas, réduire la dose. Si vous éprouvez de l'irritabilité ou de l'insomnie, cesser l'utilisation. Une hypersensibilité/allergie est connue pour survenir ; dans ce cas, cesser l'utilisation. Contre-indications : Ne pas utiliser ce produit avec d'autres suppléments contenant du potassium ni avec des substituts de sel contenant du potassium. Ces mises en garde proviennent des étiquettes et des monographies rattachées à cette fiche."$SQLTXT$::jsonb)) WHERE id = $SQLTXT$c54f9f5c-e5fc-4908-8543-27132a583c85$SQLTXT$::uuid;
UPDATE public.herb_faqs SET answer = $SQLTXT$Known Adverse Reactions: Some people may experience gastroesophageal reflux. Stop use if hypersensitivity/allergy occurs. May cause mild gastro-intestinal discomfort (such as gas, bloating, cramps). Contra-Indications: Do not use this product if you have abnormal constrictions of the gastrointestinal tract, potential or existing intestinal blockage, atonic bowel, appendicitis, inflammatory colon disease such as Crohn's disease or ulcerative colitis, abdominal pain of unknown origin. Contra-Indications: Do not take if pregnant or breastfeeding. These cautions come from the product labels and monographs attached to this entry.$SQLTXT$, translations = coalesce(translations, '{}'::jsonb) || jsonb_build_object('fr', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('answer', $SQLTXT$"Réactions indésirables connues : Certaines personnes peuvent éprouver un reflux gastro-œsophagien. Cessez l'utilisation en cas d'hypersensibilité ou d'allergie. Peut causer un léger inconfort gastro-intestinal (tel que des gaz, des ballonnements, des crampes). Contre-indications : N'utilisez pas ce produit si vous avez des constrictions anormales du tractus gastro-intestinal, une occlusion intestinale potentielle ou existante, un intestin atone, une appendicite, une maladie inflammatoire du côlon telle que la maladie de Crohn ou la colite ulcéreuse, des douleurs abdominales d'origine inconnue. Contre-indications : Ne pas prendre si vous êtes enceinte ou si vous allaitez. Ces mises en garde proviennent des étiquettes et des monographies rattachées à cette fiche."$SQLTXT$::jsonb)) WHERE id = $SQLTXT$a2607615-7bab-4074-b1e3-e6ea6842240e$SQLTXT$::uuid;
UPDATE public.herb_faqs SET answer = $SQLTXT$Contra-Indications: Do not use if you are taking thiazide diuretics, cardiac glycosides, corticosteroids, stimulant laxatives or other medications which may aggravate electrolyte imbalance or if you are pregnant or breastfeeding, have hypokalemia, high blood pressure, or a kidney, liver. Known Adverse Reactions: Hypersensitivity (e.g. allergy) has been known to occur; in which case, discontinue use. These cautions come from the product labels and monographs attached to this entry.$SQLTXT$, translations = coalesce(translations, '{}'::jsonb) || jsonb_build_object('fr', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('answer', $SQLTXT$"Réactions indésirables connues : L'hypersensibilité (p. ex. allergie) est reconnue comme pouvant survenir ; auquel cas, cessez l'utilisation. Ces mises en garde proviennent des étiquettes et des monographies rattachées à cette fiche."$SQLTXT$::jsonb)) WHERE id = $SQLTXT$1be59d93-aafe-438f-8b12-d5eabddf0bcc$SQLTXT$::uuid;
UPDATE public.herb_faqs SET answer = $SQLTXT$Contra-Indications: If you are pregnant or breastfeeding, do not use this product. Contra-Indications: Do not use this product if you are pregnant or breastfeeding. Do not use this product if you are taking thiazide diuretics, cardiac glycosides, corticosteroids, stimulant laxatives or other medications which may aggravate electrolyte imbalance. Contra-Indications: Do not use if you are pregnant or breastfeeding. Do not use if you are taking heart medications, corticosteroids, stimulant laxatives, or other health products that may contribute electrolyte imbalance. Do not use if you have diarrhea, hemorrhagic diseases or heavy periods. These cautions come from the product labels and monographs attached to this entry.$SQLTXT$, translations = coalesce(translations, '{}'::jsonb) || jsonb_build_object('fr', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('answer', $SQLTXT$"Contre-indications : Si vous êtes enceinte ou allaitez, ne pas utiliser ce produit. Contre-indications : Ne pas utiliser ce produit si vous êtes enceinte ou allaitez. Ne pas utiliser ce produit si vous prenez des diurétiques thiazidiques, des glycosides cardiotoniques, des corticostéroïdes, des laxatifs stimulants ou d'autres médicaments susceptibles d'aggraver un déséquilibre électrolytique. Contre-indications : Ne pas utiliser si vous êtes enceinte ou allaitez. Ne pas utiliser si vous prenez des médicaments pour le cœur, des corticostéroïdes, des laxatifs stimulants ou d'autres produits de santé susceptibles de contribuer à un déséquilibre électrolytique. Ne pas utiliser si vous avez de la diarrhée, des maladies hémorragiques ou des règles abondantes. Ces mises en garde proviennent des étiquettes et des monographies rattachées à cette fiche."$SQLTXT$::jsonb)) WHERE id = $SQLTXT$da9b31fc-1511-4ac3-beae-5ca23e64c38b$SQLTXT$::uuid;
UPDATE public.herb_faqs SET answer = $SQLTXT$Contra-Indications: Do not use if you have an allergy to Asteraceae/ Compositae/Daisy family. Contra-Indications: Do not use if you are pregnant or breastfeeding. Do not use if you or your partner are attempting to conceive. Do not use if you have an immune-compromised condition (e.g. AIDS, lymphoma, patients undergoing long-term corticosteroid treatment). These cautions come from the product labels and monographs attached to this entry.$SQLTXT$, translations = coalesce(translations, '{}'::jsonb) || jsonb_build_object('fr', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('answer', $SQLTXT$"Contre-indications : Ne pas utiliser si vous êtes allergique à la famille des Astéracées/Composées/Marguerites. Contre-indications : Ne pas utiliser si vous êtes enceinte ou si vous allaitez. Ne pas utiliser si vous ou votre partenaire tentez de concevoir. Ne pas utiliser si vous avez un état d'immunodépression (p. ex. SIDA, lymphome, patients suivant un traitement prolongé aux corticostéroïdes). Ces mises en garde proviennent des étiquettes et des monographies rattachées à cette fiche."$SQLTXT$::jsonb)) WHERE id = $SQLTXT$0aae6019-60d5-41c9-b7b4-d009d0c4e3ec$SQLTXT$::uuid;
UPDATE public.herb_faqs SET answer = $SQLTXT$Contra-Indications: Do not use if you are experiencing a sudden change in bowel habits that has persisted for more than 2 weeks, undiagnosed rectal bleeding, or failure to defecate following the use of another laxative product. Known Adverse Reactions: Hypersensitivity, such as allergy, has been known to occur following inhaled and/or ingested psyllium; in which case, discontinue use. May cause temporary gas and/or bloating. Cautions and Warnings: Do not use if you have an allergy to any of the ingredients. Ask a doctor or pharmacist before use if you are pregnant or breastfeeding. Stop use and ask a doctor if symptoms do not improve or worsen. These cautions come from the product labels and monographs attached to this entry.$SQLTXT$, translations = coalesce(translations, '{}'::jsonb) || jsonb_build_object('fr', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('answer', $SQLTXT$"Contre-indications : N'utilisez pas ce produit si vous présentez un changement soudain des habitudes intestinales persistant depuis plus de 2 semaines, des saignements rectaux non diagnostiqués ou une incapacité à déféquer après l'utilisation d'un autre laxatif. Effets indésirables connus : Une hypersensibilité, telle qu'une allergie, a été signalée après l'inhalation et/ou l'ingestion de psyllium; le cas échéant, cessez l'utilisation. Peut causer des gaz et/ou des ballonnements temporaires. Mises en garde et précautions : N'utilisez pas ce produit si vous êtes allergique à l'un des ingrédients. Consultez un médecin ou un pharmacien avant l'utilisation si vous êtes enceinte ou si vous allaitez. Cessez l'utilisation et consultez un médecin si les symptômes ne s'améliorent pas ou s'aggravent. Ces mises en garde proviennent des étiquettes et des monographies rattachées à cette fiche."$SQLTXT$::jsonb)) WHERE id = $SQLTXT$810dc91d-eecb-4f2a-b81c-c73565db5cc9$SQLTXT$::uuid;
UPDATE public.herb_faqs SET answer = $SQLTXT$Contra-Indications: Do not use if you are pregnant or breastfeeding. Do not use if you are taking heart medications, corticosteroids, stimulant laxatives, or other health products that may contribute electrolyte imbalance. Cautions and Warnings: Do not use this product if you are taking thiazide diuretics, cardiac glycosides, corticosteroids, stimulant laxatives or other medications which may aggravate electrolyte imbalance. Do not use this product if you are pregnant or breastfeeding. These cautions come from the product labels and monographs attached to this entry.$SQLTXT$, translations = coalesce(translations, '{}'::jsonb) || jsonb_build_object('fr', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('answer', $SQLTXT$"Contre-indications : Ne pas utiliser si vous êtes enceinte ou si vous allaitez. Ne pas utiliser si vous prenez des médicaments pour le cœur, des corticostéroïdes, des laxatifs stimulants ou d'autres produits de santé susceptibles de contribuer à un déséquilibre électrolytique. Mises en garde et avertissements : Ne pas utiliser ce produit si vous prenez des diurétiques thiazidiques, des glycosides cardiaques, des corticostéroïdes, des laxatifs stimulants ou d'autres médicaments susceptibles d'aggraver un déséquilibre électrolytique. Ne pas utiliser ce produit si vous êtes enceinte ou si vous allaitez. Ces mises en garde proviennent des étiquettes et des monographies rattachées à cette fiche."$SQLTXT$::jsonb)) WHERE id = $SQLTXT$8d7dea72-fcae-41f8-8023-d33ba5a35fe4$SQLTXT$::uuid;
UPDATE public.herb_faqs SET answer = $SQLTXT$Contra-Indications: If you are pregnant or breastfeeding, do not use this product. If you have distension and fullness of the chest and abdomen, vomiting from overabundant dampness, edema, hypertension, hypokalemia or congestive heart failure; do not use this product. Known Adverse Reactions: Hypersensitivity, such as an allergy, has been known to occur; in which case, discontinue use. Contra-Indications: Do not use if you are pregnant or breastfeeding. These cautions come from the product labels and monographs attached to this entry.$SQLTXT$, translations = coalesce(translations, '{}'::jsonb) || jsonb_build_object('fr', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('answer', $SQLTXT$"Contre-indications : Si vous êtes enceinte ou si vous allaitez, ne pas utiliser ce produit. Si vous avez une distension et une plénitude de la poitrine et de l'abdomen, des vomissements dus à une humidité surabondante, un œdème, une hypertension, une hypokaliémie ou une insuffisance cardiaque congestive ; ne pas utiliser ce produit. Réactions indésirables connues : Une hypersensibilité, telle qu'une allergie, a été signalée ; le cas échéant, cesser l'utilisation. Contre-indications : Ne pas utiliser si vous êtes enceinte ou si vous allaitez. Ces mises en garde proviennent des étiquettes et des monographies rattachées à cette fiche."$SQLTXT$::jsonb)) WHERE id = $SQLTXT$6f4b902b-e3de-492b-b36f-93c8d72f3683$SQLTXT$::uuid;
UPDATE public.herb_faqs SET answer = $SQLTXT$Contra-Indications: If you are pregnant/breastfeeding, do not use this product. Contra-Indications: Do not use this product if you are pregnant or breastfeeding. Contra-Indications: Do not use if you are pregnant or breastfeeding. Do not use if you are taking heart medications, corticosteroids, stimulant laxatives, or other health products that may contribute electrolyte imbalance. These cautions come from the product labels and monographs attached to this entry.$SQLTXT$, translations = coalesce(translations, '{}'::jsonb) || jsonb_build_object('fr', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('answer', $SQLTXT$"Contre-indications : Si vous êtes enceinte/allaitante, ne pas utiliser ce produit. Contre-indications : Ne pas utiliser ce produit si vous êtes enceinte ou allaitez. Contre-indications : Ne pas utiliser si vous êtes enceinte ou allaitez. Ne pas utiliser si vous prenez des médicaments cardiaques, des corticostéroïdes, des laxatifs stimulants ou d'autres produits de santé susceptibles de contribuer à un déséquilibre électrolytique. Ces mises en garde proviennent des étiquettes et des monographies rattachées à cette fiche."$SQLTXT$::jsonb)) WHERE id = $SQLTXT$73d003ad-ff9c-481a-8d77-ad204ed8ef68$SQLTXT$::uuid;
UPDATE public.herb_faqs SET answer = $SQLTXT$Contra-Indications: Do not use this product if you have high blood pressure or a heart condition. Do not use if you are pregnant or breastfeeding. Known Adverse Reactions: Stop use if you experience irritability, insomnia, anxiety or headaches. Some people may experience drowsiness. Exercise caution if operating heavy machinery, driving a motor vehicle or involved in activities requiring mental alertness. These cautions come from the product labels and monographs attached to this entry.$SQLTXT$, translations = coalesce(translations, '{}'::jsonb) || jsonb_build_object('fr', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('answer', $SQLTXT$"Contre-indications : Ne pas utiliser ce produit si vous avez une hypertension artérielle ou un trouble cardiaque. Ne pas utiliser si vous êtes enceinte ou si vous allaitez. Contre-indications : Ne pas utiliser ce produit si vous êtes enceinte, si vous avez un trouble bipolaire, un trouble du spectre bipolaire, une hypokaliémie, une hypertension artérielle, un trouble rénal ou cardiovasculaire, ou si vous prenez des diurétiques thiazidiques, des glycosides cardiaques, des corticostéroïdes. Réactions indésirables connues : Cesser l'utilisation si vous éprouvez de l'irritabilité, de l'insomnie, de l'anxiété ou des maux de tête. Certaines personnes peuvent éprouver de la somnolence. Faire preuve de prudence si vous utilisez de la machinerie lourde, conduisez un véhicule automobile ou participez à des activités nécessitant de la vigilance mentale. Ces mises en garde proviennent des étiquettes et des monographies rattachées à cette fiche."$SQLTXT$::jsonb)) WHERE id = $SQLTXT$1372ef90-182f-4f90-b163-3b714e741265$SQLTXT$::uuid;
UPDATE public.herb_faqs SET answer = $SQLTXT$Contra-Indications: Do not use if you are allergic to plants of the Umbelliferae/Apiaceae (carrot, celery) family. Do not use if you are pregnant or breastfeeding. Known Adverse Reactions: Hypersensitivity/allergy is known to occur, in which case, discontinue use. Celery seed may increase UV light sensitivity; limit excess exposure to ultraviolet rays (e.g. sunbathing or tanning salons) for prolong periods while using this product. Contra-Indications: Do not use if you are pregnant or breastfeeding. These cautions come from the product labels and monographs attached to this entry.$SQLTXT$, translations = coalesce(translations, '{}'::jsonb) || jsonb_build_object('fr', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('answer', $SQLTXT$"Contre-indications : Ne pas utiliser si vous êtes allergique aux plantes de la famille des Ombellifères/Apiacées (carotte, céleri). Ne pas utiliser si vous êtes enceinte ou si vous allaitez. Réactions indésirables connues : Une hypersensibilité/allergie est connue pour survenir, auquel cas il faut cesser l'utilisation. La graine de céleri peut augmenter la sensibilité aux rayons UV ; limiter l'exposition excessive aux rayons ultraviolets (p. ex. bains de soleil ou salons de bronzage) pendant des périodes prolongées lors de l'utilisation de ce produit. Contre-indications : Ne pas utiliser si vous êtes enceinte ou si vous allaitez. Ces mises en garde proviennent des étiquettes et des monographies rattachées à cette fiche."$SQLTXT$::jsonb)) WHERE id = $SQLTXT$c600c5e9-eb57-425c-85ae-7fd617b5b88d$SQLTXT$::uuid;
UPDATE public.herb_faqs SET answer = $SQLTXT$Known Adverse Reactions: Some people may experience drowsiness. Exercise caution if operating heavy machinery, driving a motor vehicle or involved in activities requiring mental alertness. Stop use if hypersensitivity/allergy occurs. Diuretic effect may occur. Contra-Indications: If you are pregnant or breastfeeding, do not use this product. Do not use if you are taking medications for depression. Do not use if you have Parkinson's disease. Do not use if you have kidney disorders, gout, gouty arthritis, and/or are susceptible to kidney stone formation. Contra-Indications: Do not use this product if you are pregnant or breastfeeding. Do not use this product if you are taking thiazide diuretics, cardiac glycosides, corticosteroids, stimulant laxatives or other medications which may aggravate electrolyte imbalance. These cautions come from the product labels and monographs attached to this entry.$SQLTXT$, translations = coalesce(translations, '{}'::jsonb) || jsonb_build_object('fr', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('answer', $SQLTXT$"Effets indésirables connus : certaines personnes peuvent ressentir de la somnolence. Faire preuve de prudence avant de conduire un véhicule, d'utiliser de la machinerie lourde ou d'exercer des activités exigeant de la vigilance mentale. Cesser l'utilisation en cas d'hypersensibilité ou d'allergie. Un effet diurétique peut survenir. Contre-indications : Si vous êtes enceinte ou si vous allaitez, ne pas utiliser ce produit. Ne pas utiliser si vous prenez des médicaments contre la dépression. Ne pas utiliser si vous souffrez de la maladie de Parkinson. Ne pas utiliser si vous avez des troubles rénaux, la goutte, l'arthrite goutteuse ou si vous êtes prédisposé à la formation de calculs rénaux. Contre-indications : Ne pas utiliser ce produit si vous êtes enceinte ou si vous allaitez. Ne pas utiliser ce produit si vous prenez des diurétiques thiazidiques, des glycosides cardiotoniques, des corticostéroïdes, des laxatifs stimulants ou d'autres médicaments susceptibles d'aggraver un déséquilibre électrolytique. Ces mises en garde proviennent des étiquettes et des monographies rattachées à cette fiche."$SQLTXT$::jsonb)) WHERE id = $SQLTXT$f61bb42e-5f47-4c3d-bbae-22e626d19975$SQLTXT$::uuid;
UPDATE public.herb_faqs SET answer = $SQLTXT$Contra-Indications: Do not use this product if you are pregnant or breastfeeding. Known Adverse Reactions: Rare, unpredictable cases of liver injury associated with green tea extract-containing products have been reported (in Canada and internationally). Contra-Indications: If you are pregnant or breastfeeding, do not use. These cautions come from the product labels and monographs attached to this entry.$SQLTXT$, translations = coalesce(translations, '{}'::jsonb) || jsonb_build_object('fr', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('answer', $SQLTXT$"Contre-indications : Ne pas utiliser ce produit si vous êtes enceinte ou si vous allaitez. Réactions indésirables connues : Des cas rares et imprévisibles de lésions hépatiques associés à des produits contenant de l'extrait de thé vert ont été signalés (au Canada et à l'international). Contre-indications : Si vous êtes enceinte ou si vous allaitez, ne pas utiliser. Ces mises en garde proviennent des étiquettes et des monographies rattachées à cette fiche."$SQLTXT$::jsonb)) WHERE id = $SQLTXT$546018f4-6aa2-41f1-903f-ec05cdf7afbe$SQLTXT$::uuid;
UPDATE public.herb_faqs SET answer = $SQLTXT$Contra-Indications: Do not use if you are pregnant or breastfeeding. Contra-Indications: Do not use if you are pregnant or breastfeeding. Do not use if you are taking heart medications, corticosteroids, stimulant laxatives, or other health products that may contribute electrolyte imbalance. Do not use if you have diarrhea, hemorrhagic diseases or heavy periods. Contra-Indications: If you are pregnant or breastfeeding, do not use this product. These cautions come from the product labels and monographs attached to this entry.$SQLTXT$, translations = coalesce(translations, '{}'::jsonb) || jsonb_build_object('fr', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('answer', $SQLTXT$"Contre-indications : Ne pas utiliser si vous êtes enceinte ou si vous allaitez. Contre-indications : Ne pas utiliser si vous êtes enceinte ou si vous allaitez. Ne pas utiliser si vous prenez des médicaments pour le cœur, des corticostéroïdes, des laxatifs stimulants ou d'autres produits de santé susceptibles de contribuer à un déséquilibre électrolytique. Ne pas utiliser en cas de diarrhée, de maladies hémorragiques ou de règles abondantes. Contre-indications : Si vous êtes enceinte ou si vous allaitez, ne pas utiliser ce produit. Ces mises en garde proviennent des étiquettes et des monographies rattachées à cette fiche."$SQLTXT$::jsonb)) WHERE id = $SQLTXT$16d417f4-6170-43de-b802-4ff112384259$SQLTXT$::uuid;
UPDATE public.herb_faqs SET answer = $SQLTXT$Contra-Indications: Do not use if you are pregnant or breastfeeding. Do not use if you are taking heart medications, corticosteroids, stimulant laxatives, or other health products that may contribute electrolyte imbalance. Contra-Indications: Do not use if you are taking thiazide diuretics, cardiac glycosides, corticosteroids, stimulant laxatives or other medications which may aggravate electrolyte imbalance or if you are pregnant or breastfeeding, have hypokalemia, high blood pressure, or a kidney, liver. Known Adverse Reactions: Stop use if hypersensitivity/allergy occurs. These cautions come from the product labels and monographs attached to this entry.$SQLTXT$, translations = coalesce(translations, '{}'::jsonb) || jsonb_build_object('fr', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('answer', $SQLTXT$"Contre-indications : N'utilisez pas si vous êtes enceinte ou allaitez. N'utilisez pas si vous prenez des médicaments cardiaques, des corticostéroïdes, des laxatifs stimulants ou d'autres produits de santé susceptibles de contribuer à un déséquilibre électrolytique. Réactions indésirables connues : Cessez l'utilisation en cas d'hypersensibilité ou d'allergie. Ces mises en garde proviennent des étiquettes et des monographies rattachées à cette fiche."$SQLTXT$::jsonb)) WHERE id = $SQLTXT$05ff7780-9c56-4b8d-93e9-8fa1a9578a64$SQLTXT$::uuid;
UPDATE public.herb_faqs SET answer = $SQLTXT$Contra-Indications: Do not use if you are taking health products that affect blood coagulation (e.g. blood thinners, clotting factor replacements, acetylsalicylic acid, ibuprofen, fish oils, vitamin E) as this may increase the risk of spontaneous bleeding. Known Adverse Reactions: Some people may experience drowsiness. Exercise caution if operating heavy machinery, driving a motor vehicle or involved in activities requiring mental alertness. Hypersensitivity (e.g. allergy) has been known to occur; in which case, discontinue use. Contra-Indications: Do not use if you are allergic to plants of the Asteraceae/Compositae/Daisy Family. These cautions come from the product labels and monographs attached to this entry.$SQLTXT$, translations = coalesce(translations, '{}'::jsonb) || jsonb_build_object('fr', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('answer', $SQLTXT$"Contre-indications : N'utilisez pas si vous prenez des produits de santé qui affectent la coagulation sanguine (p. ex. anticoagulants, suppléments de facteurs de coagulation, acide acétylsalicylique, ibuprofène, huiles de poisson, vitamine E), car cela pourrait augmenter le risque de saignement spontané. Réactions indésirables connues : Certaines personnes peuvent ressentir de la somnolence. Faites preuve de prudence si vous utilisez de la machinerie lourde, conduisez un véhicule automobile ou participez à des activités exigeant de la vigilance mentale. Des cas d'hypersensibilité (p. ex. allergie) ont été signalés ; le cas échéant, cessez l'utilisation. Contre-indications : N'utilisez pas si vous êtes allergique aux plantes de la famille des Asteraceae/Compositae/marguerites. Ces mises en garde proviennent des étiquettes et des monographies rattachées à cette fiche."$SQLTXT$::jsonb)) WHERE id = $SQLTXT$a7528c7d-0fa0-4e5b-9aa2-b10fe087218d$SQLTXT$::uuid;
UPDATE public.herb_faqs SET answer = $SQLTXT$Contra-Indications: Do not use this product if you are pregnant or breastfeeding. Do not use this product if you are taking thiazide diuretics, cardiac glycosides, corticosteroids, stimulant laxatives or other medications which may aggravate electrolyte imbalance. Contra-Indications: If you are pregnant or breastfeeding, do not use this product. Do not use this product if you have hypermenorrhea/profuse menstrual flow/heavy periods. These cautions come from the product labels and monographs attached to this entry.$SQLTXT$, translations = coalesce(translations, '{}'::jsonb) || jsonb_build_object('fr', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('answer', $SQLTXT$"Contre-indications : N'utilisez pas ce produit si vous êtes enceinte ou si vous allaitez. N'utilisez pas ce produit si vous prenez des diurétiques thiazidiques, des glycosides cardiotoniques, des corticostéroïdes, des laxatifs stimulants ou d'autres médicaments susceptibles d'aggraver un déséquilibre électrolytique. Contre-indications : Si vous êtes enceinte ou si vous allaitez, n'utilisez pas ce produit. N'utilisez pas ce produit si vous avez une hyperménorrhée/un flux menstruel abondant/des règles abondantes. Ces mises en garde proviennent des étiquettes et des monographies rattachées à cette fiche."$SQLTXT$::jsonb)) WHERE id = $SQLTXT$9eaa71a8-a35f-4d17-bbd2-7398a1c796b6$SQLTXT$::uuid;
UPDATE public.herb_faqs SET answer = $SQLTXT$Known Adverse Reactions: Stop use if hypersensitivity/allergy, nausea, vomiting or diarrhoea occurs. Stop use if rash, difficulty breathing, hypersensitivity and/or severe allergy occur. Do not use if you are allergic to plants of the Asteraceae/Compositae/Daisy family. Contra-Indications: Do not use if you are pregnant. Known Adverse Reactions: Do not use if you are allergic to plants of the Asteraceae/Compositae/Daisy family. Hypersensitivity, such as allergy, has been known to occur; in which case, discontinue use immediately. Some people may experience sore mouth, mouth ulcers and/or gastrointestinal discomfort. These cautions come from the product labels and monographs attached to this entry.$SQLTXT$, translations = coalesce(translations, '{}'::jsonb) || jsonb_build_object('fr', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('answer', $SQLTXT$"Effets indésirables connus : Cesser l'utilisation en cas d'hypersensibilité ou d'allergie, de nausées, de vomissements ou de diarrhée. Cesser l'utilisation en cas d'éruption cutanée, de difficultés respiratoires, d'hypersensibilité ou d'allergie grave. Ne pas utiliser si vous êtes allergique aux plantes de la famille des Asteraceae/Compositae/Daisy. Contre-indications : Ne pas utiliser si vous êtes enceinte. Effets indésirables connus : Ne pas utiliser si vous êtes allergique aux plantes de la famille des Asteraceae/Compositae/Daisy. Une hypersensibilité, telle qu'une allergie, a été rapportée ; dans ce cas, cesser immédiatement l'utilisation. Certaines personnes peuvent ressentir une irritation buccale, des ulcères buccaux ou un inconfort gastro-intestinal. Ces mises en garde proviennent des étiquettes et des monographies rattachées à cette fiche."$SQLTXT$::jsonb)) WHERE id = $SQLTXT$9b9d20f2-93ea-4b9e-9cb3-5748ff563a2a$SQLTXT$::uuid;
UPDATE public.herb_faqs SET answer = $SQLTXT$Contra-Indications: Do not use if you are pregnant or breastfeeding. Contra-Indications: Do not use if you are pregnant. Do not use if you are taking health products that affect blood coagulation (e.g. blood thinners, clotting factor replacements, acetylsalicylic acid, ibuprofen, fish oils, vitamin E) as this may increase the risk of spontaneous bleeding. Contra-Indications: Do not use this product if you are pregnant or breastfeeding. Do not use if you have cardiovascular disease rick factors (e.g. high blood pressure, high cholesterol and/or triglycerides) or glaucoma. These cautions come from the product labels and monographs attached to this entry.$SQLTXT$, translations = coalesce(translations, '{}'::jsonb) || jsonb_build_object('fr', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('answer', $SQLTXT$"Contre-indications : Ne pas utiliser si vous êtes enceinte ou si vous allaitez. Contre-indications : Ne pas utiliser si vous êtes enceinte. Ne pas utiliser si vous prenez des produits de santé qui affectent la coagulation sanguine (p. ex. anticoagulants, concentrés de facteurs de coagulation, acide acétylsalicylique, ibuprofène, huiles de poisson, vitamine E), car cela pourrait augmenter le risque de saignement spontané. Contre-indications : Ne pas utiliser ce produit si vous êtes enceinte ou si vous allaitez. Ne pas utiliser si vous présentez des facteurs de risque de maladie cardiovasculaire (p. ex. hypertension artérielle, cholestérol et/ou triglycérides élevés) ou un glaucome. Ces mises en garde proviennent des étiquettes et des monographies rattachées à cette fiche."$SQLTXT$::jsonb)) WHERE id = $SQLTXT$c6c4e22f-f5be-4f14-95ee-f27875b8664f$SQLTXT$::uuid;
UPDATE public.herb_faqs SET answer = $SQLTXT$Contra-Indications: Do not use if you are pregnant or breastfeeding. Do not use if you have persistant or acute abdominal discomfort, intestinal obstruction or inflammation. Do not take if you are using cardiac glycosides, thiazide diuretics, corticoadrenal steroids or licorice root. Known Adverse Reactions: May discolour urine. May cause abdominal pain and/or spasms and/or diarrhea. Hypersensitivity (i.e., allergy) is known to occur, in which case discontinue use. Some people may experience headaches. Contra-Indications: Do not use during pregnancy or breast feeding. These cautions come from the product labels and monographs attached to this entry.$SQLTXT$, translations = coalesce(translations, '{}'::jsonb) || jsonb_build_object('fr', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('answer', $SQLTXT$"Contre-indications : Ne pas utiliser si vous êtes enceinte ou si vous allaitez. Ne pas utiliser si vous avez un inconfort abdominal persistant ou aigu, une occlusion ou une inflammation intestinale. Ne pas prendre si vous utilisez des glycosides cardiotoniques, des diurétiques thiazidiques, des corticostéroïdes surrénaliens ou de la racine de réglisse. Effets indésirables connus : Peut colorer l'urine. Peut causer des douleurs abdominales et/ou des spasmes et/ou de la diarrhée. Une hypersensibilité (c.-à-d. une allergie) est connue pour survenir, auquel cas cessez l'utilisation. Certaines personnes peuvent éprouver des maux de tête. Contre-indications : Ne pas utiliser pendant la grossesse ou l'allaitement. Ces mises en garde proviennent des étiquettes et des monographies rattachées à cette fiche."$SQLTXT$::jsonb)) WHERE id = $SQLTXT$d95db52f-7959-47df-97cd-bd88aa998698$SQLTXT$::uuid;
UPDATE public.herb_faqs SET answer = $SQLTXT$Known Adverse Reactions: Hypersensitivity is known to occur, in which case, discontinue use. Discontinue use if hypersensitivity occurs such as skin rash or skin irritation. Contra-Indications: Do not use if you are allergic to anethole or plants of the Apiaceae/Carrot family. Do not use this product if you are pregnant or breastfeeding. Contra-Indications: Do not use if you have difficulty swallowing. Do not use if you have diabetes mellitus in which blood sugar is difficult to regulate. These cautions come from the product labels and monographs attached to this entry.$SQLTXT$, translations = coalesce(translations, '{}'::jsonb) || jsonb_build_object('fr', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('answer', $SQLTXT$"Réactions indésirables connues : Une hypersensibilité est connue pour survenir ; dans ce cas, cesser l'utilisation. Cesser l'utilisation si une hypersensibilité survient, telle qu'une éruption cutanée ou une irritation cutanée. Contre-indications : Ne pas utiliser si vous êtes allergique à l'anéthole ou aux plantes de la famille des Apiaceae/Carrot. Ne pas utiliser ce produit si vous êtes enceinte ou si vous allaitez. Contre-indications : Ne pas utiliser si vous avez de la difficulté à avaler. Ne pas utiliser si vous avez un diabète sucré dont la glycémie est difficile à réguler. Ces mises en garde proviennent des étiquettes et des monographies rattachées à cette fiche."$SQLTXT$::jsonb)) WHERE id = $SQLTXT$f0b7e801-8fbe-4052-8772-2b97ab2fdd65$SQLTXT$::uuid;
UPDATE public.herb_faqs SET answer = $SQLTXT$Known Adverse Reactions: Hypersensitivity, such as an allergy, has been known to occur; in which case, discontinue use. Some people may experience insomnia, anxiety, or headaches, in which case, discontinue use. Contra-Indications: If you are pregnant or breastfeeding, do not use this product. Contraindicated for those with yin deficiency, yin deficiency with heat, or qi stagnation characterized by feelings of distension and oppression. Known Adverse Reactions: Diuretic effect may occur. Stop use if hypersensitivity/allergy occurs. These cautions come from the product labels and monographs attached to this entry.$SQLTXT$, translations = coalesce(translations, '{}'::jsonb) || jsonb_build_object('fr', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('answer', $SQLTXT$"Réactions indésirables connues : Une hypersensibilité, telle qu'une allergie, a été signalée ; dans ce cas, cesser l'utilisation. Certaines personnes peuvent éprouver de l'insomnie, de l'anxiété ou des maux de tête ; dans ce cas, cesser l'utilisation. Contre-indications : Si vous êtes enceinte ou si vous allaitez, ne pas utiliser ce produit. Contre-indiqué chez les personnes présentant une insuffisance de yin, une insuffisance de yin avec chaleur, ou une stagnation du qi caractérisée par des sensations de distension et d'oppression. Réactions indésirables connues : Un effet diurétique peut survenir. Cesser l'utilisation si une hypersensibilité/allergie survient. Ces mises en garde proviennent des étiquettes et des monographies rattachées à cette fiche."$SQLTXT$::jsonb)) WHERE id = $SQLTXT$e9c56c93-b1fe-430c-9e8f-e41b2972a57a$SQLTXT$::uuid;
UPDATE public.herb_faqs SET answer = $SQLTXT$Known Adverse Reactions: Hypersensitivity has been known to occur. May cause mild gastro-intestinal discomfort (such as gas, bloating, cramps). Known Adverse Reactions: May cause temporary gas and/or bloating. Stop use if hypersensitivity/allergy occurs. Contra-Indications: Do not use this product if you are experiencing a sudden change in bowel habits that has persisted for more than 2 weeks, undiagnosed rectal bleeding, or failure to defaecate following the use of another laxative product. These cautions come from the product labels and monographs attached to this entry.$SQLTXT$, translations = coalesce(translations, '{}'::jsonb) || jsonb_build_object('fr', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('answer', $SQLTXT$"Réactions indésirables connues : Une hypersensibilité a été signalée. Peut causer un léger inconfort gastro-intestinal (tel que des gaz, des ballonnements, des crampes). Réactions indésirables connues : Peut causer des gaz et/ou des ballonnements temporaires. Cesser l'utilisation si une hypersensibilité/allergie survient. Contre-indications : Ne pas utiliser ce produit si vous présentez un changement soudain des habitudes intestinales persistant depuis plus de 2 semaines, un saignement rectal non diagnostiqué ou une incapacité à déféquer après l'utilisation d'un autre produit laxatif. Ces mises en garde proviennent des étiquettes et des monographies rattachées à cette fiche."$SQLTXT$::jsonb)) WHERE id = $SQLTXT$c955fee1-7160-4fd1-88f2-89c2c901272b$SQLTXT$::uuid;
UPDATE public.herb_faqs SET answer = $SQLTXT$Cautions and Warnings: Do not consume during pregnancy or nursing. Do not take if experiencing nausea, vomiting or symptoms of appendicitis. Long term use may create dependence. Contra-Indications: Do not use if pregnant or breastfeeding. Do not use if you are experiencing a sudden change in bowel habits that has persisted for more than 2 weeks, undiagnosed rectal bleeding, or failure to defecate following the use of another laxative. Known Adverse Reactions: Allergy to plants of the Asteraceae, daisy, Leguminosae families. Hypersensitivity, such as allergy, has been known to occur, in which case discontinue use. May cause temporary gas and/or bloating. These cautions come from the product labels and monographs attached to this entry.$SQLTXT$, translations = coalesce(translations, '{}'::jsonb) || jsonb_build_object('fr', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('answer', $SQLTXT$"Mises en garde et avertissements : Ne pas consommer pendant la grossesse ou l'allaitement. Ne pas prendre en cas de nausées, de vomissements ou de symptômes d'appendicite. L'utilisation à long terme peut créer une dépendance. Contre-indications : Ne pas utiliser si vous êtes enceinte ou si vous allaitez. Ne pas utiliser si vous présentez un changement soudain des habitudes intestinales persistant depuis plus de 2 semaines, un saignement rectal non diagnostiqué, ou une incapacité à déféquer après l'utilisation d'un autre laxatif. Réactions indésirables connues : Allergie aux plantes des familles Asteraceae, marguerite, Leguminosae. Une hypersensibilité, telle qu'une allergie, a été signalée, auquel cas il faut cesser l'utilisation. Peut causer des gaz et/ou des ballonnements temporaires. Ces mises en garde proviennent des étiquettes et des monographies rattachées à cette fiche."$SQLTXT$::jsonb)) WHERE id = $SQLTXT$53987b69-0475-4cbb-ab27-076de43d7760$SQLTXT$::uuid;
UPDATE public.herb_faqs SET answer = $SQLTXT$Contra-Indications: Do not use this product if you are pregnant or breastfeeding. Known Adverse Reactions: Stop use if hypersensitivity/allergy occurs. Contra-Indications: Do not use this product if you are pregnant or breastfeeding. Do not use this product if you are taking thiazide diuretics, cardiac glycosides, corticosteroids, stimulant laxatives or other medications which may aggravate electrolyte imbalance. These cautions come from the product labels and monographs attached to this entry.$SQLTXT$, translations = coalesce(translations, '{}'::jsonb) || jsonb_build_object('fr', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('answer', $SQLTXT$"Contre-indications : Ne pas utiliser ce produit si vous êtes enceinte ou si vous allaitez. Réactions indésirables connues : Cesser l'utilisation en cas d'hypersensibilité/allergie. Contre-indications : Ne pas utiliser ce produit si vous êtes enceinte ou si vous allaitez. Ne pas utiliser ce produit si vous prenez des diurétiques thiazidiques, des glycosides cardiotoniques, des corticostéroïdes, des laxatifs stimulants ou d'autres médicaments susceptibles d'aggraver un déséquilibre électrolytique. Ces mises en garde proviennent des étiquettes et des monographies rattachées à cette fiche."$SQLTXT$::jsonb)) WHERE id = $SQLTXT$9964fefc-4453-45d1-ace9-4b458a8f17e5$SQLTXT$::uuid;
UPDATE public.herb_faqs SET answer = $SQLTXT$Known Adverse Reactions: Some people may experience drowsiness. Exercise caution if operating heavy machinery, driving a motor vehicle or involved in activities requiring mental alertness. Diuretic effect may occur. Stop use if hypersensitivity/allergy occurs. Contra-Indications: Do not use this product if you are pregnant or have a kidney disorder. Contra-Indications: Do not use this product if you are taking thiazide diuretics, cardiac glycosides, corticosteroids, stimulant laxatives or other medications which may aggravate electrolyte imbalance. These cautions come from the product labels and monographs attached to this entry.$SQLTXT$, translations = coalesce(translations, '{}'::jsonb) || jsonb_build_object('fr', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('answer', $SQLTXT$"Réactions indésirables connues : Certaines personnes peuvent ressentir de la somnolence. Faire preuve de prudence si vous conduisez un véhicule motorisé, utilisez de la machinerie lourde ou participez à des activités nécessitant de la vigilance mentale. Un effet diurétique peut se produire. Cesser l'utilisation en cas d'hypersensibilité/allergie. Contre-indications : Ne pas utiliser ce produit si vous prenez des diurétiques thiazidiques, des glycosides cardiotoniques, des corticostéroïdes, des laxatifs stimulants ou d'autres médicaments susceptibles d'aggraver un déséquilibre électrolytique. Ces mises en garde proviennent des étiquettes et des monographies rattachées à cette fiche."$SQLTXT$::jsonb)) WHERE id = $SQLTXT$7a292ebf-3dcd-4eab-8d65-0b2213248b85$SQLTXT$::uuid;
UPDATE public.herb_faqs SET answer = $SQLTXT$Contra-Indications: If you are pregnant or breastfeeding, do not use this product. Contraindicated for those with weak stomach and spleen or diarrhea. Contraindicated for those with cough due to yin deficiency or general debility. Known Adverse Reactions: Hypersensitivity, such as an allergy, has been known to occur; in which case, discontinue use. Contra-Indications: If you are pregnant or breastfeeding, do not use this product. Do not use this product if you have hypokalemia, high blood pressure or a kidney or cardiovascular disorder. These cautions come from the product labels and monographs attached to this entry.$SQLTXT$, translations = coalesce(translations, '{}'::jsonb) || jsonb_build_object('fr', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('answer', $SQLTXT$"Contre-indications : Si vous êtes enceinte ou si vous allaitez, ne pas utiliser ce produit. Contre-indiqué chez les personnes ayant un estomac et une rate faibles ou de la diarrhée. Contre-indiqué chez les personnes ayant une toux due à une déficience du yin ou une faiblesse générale. Réactions indésirables connues : Une hypersensibilité, telle qu'une allergie, a été observée ; dans ce cas, cesser l'utilisation. Contre-indications : Si vous êtes enceinte ou si vous allaitez, ne pas utiliser ce produit. Ne pas utiliser ce produit si vous avez une hypokaliémie, une pression artérielle élevée ou un trouble rénal ou cardiovasculaire. Ces mises en garde proviennent des étiquettes et des monographies rattachées à cette fiche."$SQLTXT$::jsonb)) WHERE id = $SQLTXT$99af7e33-fd62-4e50-bc5a-4b5129c2b86c$SQLTXT$::uuid;
UPDATE public.herb_faqs SET answer = $SQLTXT$Known Adverse Reactions: Rare, unpredictable cases of liver injury associated with green tea extract-containing products have been reported (in Canada and Internationally). People sensitive to nicotinic acid may experience flushing of the skin that is generally mild and transient. Contra-Indications: Do not use if you are pregnant. Contra-Indications: Do not use this product if you have an immune-compromised condition (e.g. AIDS, lymphoma, patients undergoing long-term corticosteroid treatment). These cautions come from the product labels and monographs attached to this entry.$SQLTXT$, translations = coalesce(translations, '{}'::jsonb) || jsonb_build_object('fr', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('answer', $SQLTXT$"Effets indésirables connus : De rares cas imprévisibles d'atteinte hépatique associés à des produits contenant de l'extrait de thé vert ont été signalés (au Canada et à l'international). Les personnes sensibles à l'acide nicotinique peuvent présenter des bouffées vasomotrices cutanées généralement légères et transitoires. Contre-indications : Ne pas utiliser si vous êtes enceinte. Contre-indications : Ne pas utiliser ce produit si vous avez un état immunodéprimé (p. ex. SIDA, lymphome, patients sous corticothérapie à long terme). Ces mises en garde proviennent des étiquettes et des monographies rattachées à cette fiche."$SQLTXT$::jsonb)) WHERE id = $SQLTXT$9cd19b8d-3b3c-41bd-9478-364ebd1b2a01$SQLTXT$::uuid;
UPDATE public.herb_faqs SET answer = $SQLTXT$Contra-Indications: If you are pregnant or breastfeeding, do not use this product. Do not use this product if you have hypokalemia or a kidney disorder. Known Adverse Reactions: Product may cause nausea, vomiting, abdominal pain, diarrhea, bloating, rash, itchy ulcers, dry mouth, and/or dizziness. Contra-Indications: If you are pregnant or breastfeeding, do not use this product. Contraindicated for those with weak stomach and spleen or diarrhea. Contraindicated for those with cough due to yin deficiency or general debility. These cautions come from the product labels and monographs attached to this entry.$SQLTXT$, translations = coalesce(translations, '{}'::jsonb) || jsonb_build_object('fr', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('answer', $SQLTXT$"Contre-indications : Si vous êtes enceinte ou allaitez, n'utilisez pas ce produit. Réactions indésirables connues : Le produit peut causer des nausées, des vomissements, des douleurs abdominales, de la diarrhée, des ballonnements, des éruptions cutanées, des ulcères prurigineux, une sécheresse buccale et/ou des étourdissements. Contre-indications : Si vous êtes enceinte ou allaitez, n'utilisez pas ce produit. Contre-indiqué chez les personnes ayant un estomac et une rate faibles ou de la diarrhée. Contre-indiqué chez les personnes ayant une toux due à une déficience du yin ou une débilité générale. Ces mises en garde proviennent des étiquettes et des monographies rattachées à cette fiche."$SQLTXT$::jsonb)) WHERE id = $SQLTXT$9cb2f89d-c089-4245-b37a-25796a8af5be$SQLTXT$::uuid;
UPDATE public.herb_faqs SET answer = $SQLTXT$Contra-Indications: Do not use this product if you are pregnant. Known Adverse Reactions: Stop use if hypersensitivity/allergy occurs. Contra-Indications: If you are pregnant or breastfeeding, do not use. If you have hypokalemia, high blood pressure, kidney disorder, cardiovascular disorder, an immune-compromised condition (e.g. AIDS, lymphoma, patients undergoing long-term corticosteroid treatment), do not use. These cautions come from the product labels and monographs attached to this entry.$SQLTXT$, translations = coalesce(translations, '{}'::jsonb) || jsonb_build_object('fr', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('answer', $SQLTXT$"Contre-indications : Ne pas utiliser ce produit si vous êtes enceinte. Effets indésirables connus : Cesser l'utilisation en cas d'hypersensibilité ou d'allergie. Contre-indications : Si vous êtes enceinte ou allaitez, ne pas utiliser. Si vous avez une hypokaliémie, une hypertension artérielle, un trouble rénal, un trouble cardiovasculaire, un état immunodéprimé (p. ex. SIDA, lymphome, patients sous corticothérapie à long terme), ne pas utiliser. Ces mises en garde proviennent des étiquettes et des monographies rattachées à cette fiche."$SQLTXT$::jsonb)) WHERE id = $SQLTXT$1600efed-e5e5-49c2-b2b2-bb8de7ee53aa$SQLTXT$::uuid;
UPDATE public.herb_faqs SET answer = $SQLTXT$Cautions and Warnings: For external use only. Avoid contact with eyes, mucous membranes; if this happens, rinse thoroughly with water. Avoid exposure of applied area to the sun. Hypersensitivity, rash and /or burning discomfort have been known to occur; in which case, discontinue use. Contra-Indications: If you are pregnant or breastfeeding, do not use this product. Contra-Indications: Do not use if you are pregnant or breastfeeding. Do not use if you have diarrhea, hemorrhagic diseases or heavy periods. These cautions come from the product labels and monographs attached to this entry.$SQLTXT$, translations = coalesce(translations, '{}'::jsonb) || jsonb_build_object('fr', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('answer', $SQLTXT$"Mises en garde et précautions : Pour usage externe seulement. Éviter le contact avec les yeux et les muqueuses ; si cela se produit, rincer abondamment à l'eau. Éviter l'exposition de la zone traitée au soleil. Une hypersensibilité, une éruption cutanée ou un inconfort de type brûlure ont été rapportés ; dans ce cas, cesser l'utilisation. Contre-indications : Si vous êtes enceinte ou si vous allaitez, ne pas utiliser ce produit. Contre-indications : Ne pas utiliser si vous êtes enceinte ou si vous allaitez. Ne pas utiliser si vous avez de la diarrhée, des maladies hémorragiques ou des règles abondantes. Ces mises en garde proviennent des étiquettes et des monographies rattachées à cette fiche."$SQLTXT$::jsonb)) WHERE id = $SQLTXT$9f47b485-36f7-4522-8c50-47f5488a64ad$SQLTXT$::uuid;
UPDATE public.herb_faqs SET answer = $SQLTXT$Contra-Indications: According to Traditional Chinese Medicine, do not use this product in cases of exterior excess, qi stagnation, damp obstruction, food stagnation, yin deficiency with heat signs, or skin lesions in their early stages or where there is a heat toxin. Contra-Indications: Do not use if you are pregnant. Known Adverse Reactions: Long-term use may irritate the gastric mucosa. May cause severe, watery diarrhea. These cautions come from the product labels and monographs attached to this entry.$SQLTXT$, translations = coalesce(translations, '{}'::jsonb) || jsonb_build_object('fr', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('answer', $SQLTXT$"Contre-indications : Selon la médecine traditionnelle chinoise, ne pas utiliser ce produit en cas d'excès externe, de stagnation du qi, d'obstruction par l'humidité, de stagnation alimentaire, de vide de yin avec signes de chaleur, ou de lésions cutanées à leurs stades précoces ou en présence d'une toxine de chaleur. Contre-indications : Ne pas utiliser si vous êtes enceinte. Réactions indésirables connues : L'utilisation à long terme peut irriter la muqueuse gastrique. Peut provoquer une diarrhée aqueuse sévère. Ces mises en garde proviennent des étiquettes et des monographies rattachées à cette fiche."$SQLTXT$::jsonb)) WHERE id = $SQLTXT$c4a5fdea-d660-43b3-bd19-e6a5988d6831$SQLTXT$::uuid;
UPDATE public.herb_faqs SET answer = $SQLTXT$Known Adverse Reactions: Certain patients have noticed minor gastro-intestinal bloating. Stop use if hypersensitivity/allergy occurs. Contra-Indications: People who have had an organ transplant and are on immunosuppressive drugs should consult their health care practitioner. This product should not be used by people with allergies to milk protein. Contra-Indications: Do not use if you are pregnant or breastfeeding; if you have difficulty swallowing; if you have diabetes mellitus in which blood sugar is difficult to regulate. These cautions come from the product labels and monographs attached to this entry.$SQLTXT$, translations = coalesce(translations, '{}'::jsonb) || jsonb_build_object('fr', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('answer', $SQLTXT$"Réactions indésirables connues : Certains patients ont remarqué des ballonnements gastro-intestinaux mineurs. Cessez l'utilisation en cas d'hypersensibilité ou d'allergie. Contre-indications : Les personnes ayant subi une transplantation d'organe et prenant des médicaments immunosuppresseurs doivent consulter leur professionnel de la santé. Ce produit ne doit pas être utilisé par les personnes allergiques aux protéines de lait. Contre-indications : Ne pas utiliser si vous êtes enceinte ou si vous allaitez ; si vous avez de la difficulté à avaler ; si vous avez un diabète sucré dont la glycémie est difficile à réguler. Ces mises en garde proviennent des étiquettes et des monographies rattachées à cette fiche."$SQLTXT$::jsonb)) WHERE id = $SQLTXT$060f339f-6060-4cb6-9b41-da9753f2fb0b$SQLTXT$::uuid;
UPDATE public.herb_faqs SET answer = $SQLTXT$Contra-Indications: Do not use if you are pregnant or breastfeeding; if you have difficulty swallowing; if you have diabetes mellitus in which blood sugar is difficult to regulate. Known Adverse Reactions: Hypersensitivity, such as an allergy, has been known to occur in rare cases; in which case, discontinue use. May cause temporary gas and/or bloating. May have laxative effects. Known Adverse Reactions: No statement required. These cautions come from the product labels and monographs attached to this entry.$SQLTXT$, translations = coalesce(translations, '{}'::jsonb) || jsonb_build_object('fr', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('answer', $SQLTXT$"Contre-indications : Ne pas utiliser si vous êtes enceinte ou si vous allaitez ; si vous avez de la difficulté à avaler ; si vous avez un diabète sucré dont la glycémie est difficile à réguler. Réactions indésirables connues : Une hypersensibilité, telle qu'une allergie, a été signalée dans de rares cas ; le cas échéant, cessez l'utilisation. Peut causer des gaz et/ou des ballonnements temporaires. Peut avoir des effets laxatifs. Réactions indésirables connues : Aucune mention requise. Ces mises en garde proviennent des étiquettes et des monographies rattachées à cette fiche."$SQLTXT$::jsonb)) WHERE id = $SQLTXT$d97dd5d4-f76d-4bf0-8973-01003ab99b9d$SQLTXT$::uuid;
UPDATE public.herb_faqs SET answer = $SQLTXT$Contra-Indications: Do not take this product if you are pregnant or breastfeeding. Do not use if you have hypokalemia, high blood pressure, liver or gall bladder or kidney or cardiovascular disorders, diabetes or edema (swelling of hands, face and feet). Known Adverse Reactions: Hypersensitivity is known to occur, in which case discontinue use. Known Adverse Reactions: Hypersensitivity, such as an allergy, has been known to occur; in which case, discontinue use. These cautions come from the product labels and monographs attached to this entry.$SQLTXT$, translations = coalesce(translations, '{}'::jsonb) || jsonb_build_object('fr', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('answer', $SQLTXT$"Contre-indications : Ne prenez pas ce produit si vous êtes enceinte ou si vous allaitez. Ne pas utiliser si vous avez une hypokaliémie, une hypertension artérielle, des troubles hépatiques, biliaires, rénaux ou cardiovasculaires, du diabète ou de l'œdème (enflure des mains, du visage et des pieds). Réactions indésirables connues : Une hypersensibilité est connue pour survenir, auquel cas cessez l'utilisation. Réactions indésirables connues : Une hypersensibilité, telle qu'une allergie, est connue pour survenir ; auquel cas, cessez l'utilisation. Ces mises en garde proviennent des étiquettes et des monographies rattachées à cette fiche."$SQLTXT$::jsonb)) WHERE id = $SQLTXT$0cde0028-2a68-460d-abc8-1f99ee0cf404$SQLTXT$::uuid;
UPDATE public.herb_faqs SET answer = $SQLTXT$Contra-Indications: If you are pregnant or breastfeeding, do not use this product. Do not use if you have kidney or liver disorder, heart disease, high or low blood pressure, diabetes, or edema (swelling of hands, face and feet) or are taking products containing diuretics. Known Adverse Reactions: Hypersensitivity (e.g. allergy) and gastrointestinal discomfort has been known to occur; in which case, discontinue use. Contra-Indications: Do not use if you are pregnant or breastfeeding. These cautions come from the product labels and monographs attached to this entry.$SQLTXT$, translations = coalesce(translations, '{}'::jsonb) || jsonb_build_object('fr', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('answer', $SQLTXT$"Contre-indications : Si vous êtes enceinte ou allaitez, n'utilisez pas ce produit. Ne pas utiliser si vous avez un trouble rénal ou hépatique, une maladie cardiaque, une pression artérielle élevée ou basse, du diabète, ou de l'œdème (gonflement des mains, du visage et des pieds) ou si vous prenez des produits contenant des diurétiques. Réactions indésirables connues : Des cas d'hypersensibilité (p. ex. allergie) et d'inconfort gastro-intestinal ont été signalés ; dans ce cas, cessez l'utilisation. Contre-indications : Ne pas utiliser si vous êtes enceinte ou allaitez. Ces mises en garde proviennent des étiquettes et des monographies rattachées à cette fiche."$SQLTXT$::jsonb)) WHERE id = $SQLTXT$62cb24b0-14f8-4d04-a1cf-8a740f5a73e9$SQLTXT$::uuid;
UPDATE public.herb_faqs SET answer = $SQLTXT$Cautions and Warnings: Consult a health care/ TCM practitioner prior to use if you are taking anticoagulants or antiplatelet medications. Use with caution in individuals with stomach deficiencies; Consult a health care or TCM practitioner prior to use if you have gastric or peptic ulcers. Contra-Indications: Contraindicated in cases of spleen deficiency. Do not use in cases of heat from deficiency. Do not use if you are pregnant or breastfeeding. Do not take if you have loose stools. Do not use if you have a yin or qi deficiency or seminal emission due to deficiency cold. Known Adverse Reactions: Hypersensitivity ie: allergy is known to occur in which case discontinue use. These cautions come from the product labels and monographs attached to this entry.$SQLTXT$, translations = coalesce(translations, '{}'::jsonb) || jsonb_build_object('fr', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('answer', $SQLTXT$"Mises en garde et avertissements : Consulter un professionnel de la santé ou un praticien de MTC avant utilisation si vous prenez des anticoagulants ou des antiplaquettaires. Utiliser avec prudence chez les personnes présentant des insuffisances gastriques ; consulter un professionnel de la santé ou un praticien de MTC avant utilisation si vous avez des ulcères gastriques ou peptiques. Contre-indications : Contre-indiqué en cas de vide de la rate. Ne pas utiliser en cas de chaleur issue d'un vide. Ne pas utiliser si vous êtes enceinte ou si vous allaitez. Ne pas prendre en cas de selles molles. Ne pas utiliser en cas de vide de yin ou de qi ou d'émission séminale due à un vide-froid. Effets indésirables connus : Une hypersensibilité, c'est-à-dire une allergie, peut survenir ; dans ce cas, cesser l'utilisation. Ces mises en garde proviennent des étiquettes et des monographies rattachées à cette fiche."$SQLTXT$::jsonb)) WHERE id = $SQLTXT$6d4cc017-890f-446d-bdfc-be059df423db$SQLTXT$::uuid;
UPDATE public.herb_faqs SET answer = $SQLTXT$Contra-Indications: Do not use if you are taking health products that affect blood coagulation (e.g. blood thinners, clotting factor replacements, acetysalicylic acid, ibuprofen, fish oils, Vitamin E) as this may increase the risk of spontaneous bleeding. Contra-Indications: Do not use if you are allergic to plants of the Asteraceae/Compositae/Daisy family. Contra-Indications: Do not use if you are taking health products that affect blood coagulation (e.g. blood thinners, clotting factor replacements, acetylsalicylic acid, ibuprofen, fish oils, vitamin E) as this may increase the risk of spontaneous blooding. If you are pregnant do not use. These cautions come from the product labels and monographs attached to this entry.$SQLTXT$, translations = coalesce(translations, '{}'::jsonb) || jsonb_build_object('fr', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('answer', $SQLTXT$"Contre-indications : Ne pas utiliser si vous prenez des produits de santé qui influent sur la coagulation sanguine (p. ex. anticoagulants, suppléments de facteurs de coagulation, acide acétylsalicylique, ibuprofène, huiles de poisson, vitamine E), car cela pourrait augmenter le risque de saignement spontané. Contre-indications : Ne pas utiliser si vous êtes allergique aux plantes de la famille des Asteraceae/Compositae/Daisy. Contre-indications : Ne pas utiliser si vous prenez des produits de santé qui influent sur la coagulation sanguine (p. ex. anticoagulants, suppléments de facteurs de coagulation, acide acétylsalicylique, ibuprofène, huiles de poisson, vitamine E), car cela pourrait augmenter le risque de saignement spontané. Si vous êtes enceinte, ne pas utiliser. Ces mises en garde proviennent des étiquettes et des monographies rattachées à cette fiche."$SQLTXT$::jsonb)) WHERE id = $SQLTXT$0922412c-4c22-4670-ac36-5c82774f8b5e$SQLTXT$::uuid;
UPDATE public.herb_faqs SET answer = $SQLTXT$Known Adverse Reactions: Hypersensitivity/allergy can occur, in which case discontinue use and consult your healthcare practitioner. Some people may experience insomnia, anxiety, or headaches, in which case, discontinue use. Contra-Indications: Do not use if you are pregnant or breastfeeding. Do not use if you have a history of systemic lupus erythematosus. If you have bipolar disorder or bipolar spectrum disorder, do not use this product. If you experience irritability or insomnia, discontinue use. Contra-Indications: If you are pregnant or breastfeeding, do not use. If you have hypokalemia, high blood pressure, kidney disorder, cardiovascular disorder, an immune-compromised condition (e.g. AIDS, lymphoma, patients undergoing long-term corticosteroid treatment), do not use. These cautions come from the product labels and monographs attached to this entry.$SQLTXT$, translations = coalesce(translations, '{}'::jsonb) || jsonb_build_object('fr', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('answer', $SQLTXT$"Réactions indésirables connues : Une hypersensibilité/allergie peut survenir, auquel cas il faut cesser l'utilisation et consulter un professionnel de la santé. Certaines personnes peuvent éprouver de l'insomnie, de l'anxiété ou des maux de tête, auquel cas il faut cesser l'utilisation. Contre-indications : Ne pas utiliser si vous êtes enceinte ou si vous allaitez. Ne pas utiliser si vous avez des antécédents de lupus érythémateux disséminé. Si vous souffrez de trouble bipolaire ou de trouble du spectre bipolaire, ne pas utiliser ce produit. Si vous éprouvez de l'irritabilité ou de l'insomnie, cessez l'utilisation. Contre-indications : Si vous êtes enceinte ou si vous allaitez, ne pas utiliser. Si vous avez une hypokaliémie, de l'hypertension artérielle, un trouble rénal, un trouble cardiovasculaire, un état d'immunodépression (p. ex. SIDA, lymphome, patients sous corticothérapie à long terme), ne pas utiliser. Ces mises en garde proviennent des étiquettes et des monographies rattachées à cette fiche."$SQLTXT$::jsonb)) WHERE id = $SQLTXT$562a42e9-1358-4deb-80c5-185385cf6953$SQLTXT$::uuid;
UPDATE public.herb_faqs SET answer = $SQLTXT$Contra-Indications: Do not use if you have liver or gall bladder disorders, and/or bowel obstruction. If seal around cap is broken or missing, do not use. Do not use if you are allergic to plants of the Asteraceae/Compositae/Daisy family. Do not use if you are pregnant or breastfeeding. Known Adverse Reactions: Discontinue use if you develop symptoms of liver trouble. Hypersensitivity, such as allergy, has been known to occur, in which case discontinue use. These cautions come from the product labels and monographs attached to this entry.$SQLTXT$, translations = coalesce(translations, '{}'::jsonb) || jsonb_build_object('fr', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('answer', $SQLTXT$"Contre-indications : Ne pas utiliser si vous avez des troubles hépatiques ou biliaires et/ou une occlusion intestinale. Si le sceau autour du bouchon est brisé ou manquant, ne pas utiliser. Ne pas utiliser si vous êtes allergique aux plantes de la famille des Asteraceae/Compositae/Daisy. Ne pas utiliser si vous êtes enceinte ou si vous allaitez. Réactions indésirables connues : Cesser l'utilisation si vous développez des symptômes de trouble hépatique. Une hypersensibilité, telle qu'une allergie, a été signalée, auquel cas cesser l'utilisation. Ces mises en garde proviennent des étiquettes et des monographies rattachées à cette fiche."$SQLTXT$::jsonb)) WHERE id = $SQLTXT$b50378e0-1683-48fa-b6dc-09d8d5bca136$SQLTXT$::uuid;
UPDATE public.herb_faqs SET answer = $SQLTXT$Known Adverse Reactions: Some people may experience drowsiness. Exercise caution if operating heavy machinery, driving a motor vehicle or involved in activities requiring mental alertness. Contra-Indications: Do not use this product if you are pregnant or breastfeeding. Cautions and Warnings: Hypersensitivity, such as an allergy, has been known to occur; in which case, discontinue use. These cautions come from the product labels and monographs attached to this entry.$SQLTXT$, translations = coalesce(translations, '{}'::jsonb) || jsonb_build_object('fr', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('answer', $SQLTXT$"Réactions indésirables connues : Certaines personnes peuvent ressentir de la somnolence. Faire preuve de prudence si vous utilisez de la machinerie lourde, conduisez un véhicule automobile ou pratiquez des activités nécessitant de la vigilance mentale. Des inconforts gastro-intestinaux (c.-à-d. Contre-indications : Ne pas utiliser ce produit si vous êtes enceinte ou si vous allaitez. Mises en garde et avertissements : Une hypersensibilité, telle qu'une allergie, a été signalée ; dans ce cas, cesser l'utilisation. Ces mises en garde proviennent des étiquettes et des monographies rattachées à cette fiche."$SQLTXT$::jsonb)) WHERE id = $SQLTXT$268ad336-31f1-47b5-89e1-69ee1d9ffe9f$SQLTXT$::uuid;
UPDATE public.herb_faqs SET answer = $SQLTXT$Contra-Indications: According to Traditional Chinese Medicine, do not use this product in cases of exterior excess, qi stagnation, damp obstruction, food stagnation, yin deficiency with heat signs, or skin lesions in their early stages or where there is a heat toxin. Known Adverse Reactions: Diuretic effect may occur. Stop use if hypersensitivity/allergy occurs. Laxative may occur. Discontinue use if experience abdominal pain, cramps, spasms, or diarrhoea. Contra-Indications: If you are pregnant or breastfeeding, do not use this product. These cautions come from the product labels and monographs attached to this entry.$SQLTXT$, translations = coalesce(translations, '{}'::jsonb) || jsonb_build_object('fr', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('answer', $SQLTXT$"Contre-indications : Selon la médecine traditionnelle chinoise, ne pas utiliser ce produit en cas d'excès externe, de stagnation du qi, d'obstruction par l'humidité, de stagnation alimentaire, de vide de yin avec signes de chaleur, ou de lésions cutanées à leurs stades précoces ou en présence d'une toxine de chaleur. Effets indésirables connus : Un effet diurétique peut survenir. Cesser l'utilisation en cas d'hypersensibilité/allergie. Un effet laxatif peut survenir. Cesser l'utilisation en cas de douleurs abdominales, de crampes, de spasmes ou de diarrhée. Contre-indications : Si vous êtes enceinte ou allaitante, ne pas utiliser ce produit. Ces mises en garde proviennent des étiquettes et des monographies rattachées à cette fiche."$SQLTXT$::jsonb)) WHERE id = $SQLTXT$fb7511f2-33e4-457e-880f-50a1489c6e59$SQLTXT$::uuid;
UPDATE public.herb_faqs SET answer = $SQLTXT$Known Adverse Reactions: Rare, unpredictable cases of liver injury associated with green tea extract-containing products have been reported (in Canada and internationally). Contra-Indications: Stop use and consult a healthcare practitioner if symptoms of digestive upset (eg. diarrhea) occur, worsen or persist beyond 3 days. Do not use this product if you have an immune compromised condition (e.g. AIDS, lymphoma, patients undergoing long-term corticosteriod treatment). Known Adverse Reactions: May cause mild gastro-intestinal discomfort (such as gas, bloating, cramps). Stop use if hypersensitivity/allergy occurs. These cautions come from the product labels and monographs attached to this entry.$SQLTXT$, translations = coalesce(translations, '{}'::jsonb) || jsonb_build_object('fr', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('answer', $SQLTXT$"Réactions indésirables connues : De rares cas imprévisibles de lésions hépatiques associés à des produits contenant de l'extrait de thé vert ont été signalés (au Canada et à l'international). Contre-indications : Cessez l'utilisation et consultez un praticien de soins de santé si des symptômes de troubles digestifs (p. ex. diarrhée) surviennent, s'aggravent ou persistent au-delà de 3 jours. Ne pas utiliser ce produit si vous avez un état immunodéprimé (p. ex. SIDA, lymphome, patients sous traitement corticostéroïdien à long terme). Réactions indésirables connues : Peut causer un léger inconfort gastro-intestinal (comme des gaz, des ballonnements, des crampes). Cessez l'utilisation si une hypersensibilité/allergie survient. Ces mises en garde proviennent des étiquettes et des monographies rattachées à cette fiche."$SQLTXT$::jsonb)) WHERE id = $SQLTXT$852817bb-b269-4186-8502-ecafb496bbe4$SQLTXT$::uuid;
UPDATE public.herb_faqs SET answer = $SQLTXT$Contra-Indications: Do not use if you have had a heart attack/myocardial infarction. Known Adverse Reactions: Hypersensitivity, such as an allergy, has been known to occur; in which case, discontinue use. Some people may experience mild gastrointestinal disturbances and/or nausea. Contra-Indications: If you are pregnant or breastfeeding, do not use. If you have heart disease, high or low blood pressure, kidney or liver disorder, diabetes or edema (swelling of hands, face and feet) or are taking products containing diuretics, do not use. These cautions come from the product labels and monographs attached to this entry.$SQLTXT$, translations = coalesce(translations, '{}'::jsonb) || jsonb_build_object('fr', coalesce(translations->'fr', '{}'::jsonb) || jsonb_build_object('answer', $SQLTXT$"Contre-indications : Ne pas utiliser si vous avez subi une crise cardiaque/un infarctus du myocarde. Effets indésirables connus : Une hypersensibilité, telle qu'une allergie, a été signalée ; dans ce cas, cessez l'utilisation. Certaines personnes peuvent ressentir des troubles gastro-intestinaux légers et/ou des nausées. Contre-indications : Si vous êtes enceinte ou si vous allaitez, ne pas utiliser. Si vous avez une maladie cardiaque, une pression artérielle élevée ou basse, un trouble rénal ou hépatique, du diabète ou de l'œdème (gonflement des mains, du visage et des pieds) ou si vous prenez des produits contenant des diurétiques, ne pas utiliser. Ces mises en garde proviennent des étiquettes et des monographies rattachées à cette fiche."$SQLTXT$::jsonb)) WHERE id = $SQLTXT$658868ed-fd0a-4892-8e28-3f2043863451$SQLTXT$::uuid;
